INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56756294179', 'Pingente de Prata 925 Medalha Rabo de Sereia Resinada', 'Pingente de Prata 925 Medalha Rabo de Sereia Resinada: Delicadeza e Encanto do Mar O Pingente de Prata 925 Medalha Rabo de Sereia Resinada é uma joia charmosa e cheia de personalidade. Inspirado no universo marinho, o rabo de sereia simboliza liberdade, força e conexão com o mar. Com acabamento resinado que valoriza os detalhes, essa peça é perfeita para quem ama acessórios delicados e cheios de significado. Especificações do Pingente Tamanho: 1,2cm Peso: 1g Material: Prata 925 Destaques do Pingente Design em formato de medalha com rabo de sereia detalhado. Acabamento resinado que realça os traços da peça. Tamanho delicado de 1,2cm, ideal para uso diário. Perfeito para combinar com correntes finas em prata. Confeccionado em Prata 925, garantindo autenticidade, brilho e durabilidade. Uma Joia Inspirada no Mar O Pingente Medalha Rabo de Sereia em Prata 925 é ideal para quem se identifica com o universo das sereias e com a energia do oceano. Uma peça delicada e versátil, perfeita para compor colares cheios de estilo e personalidade. Cuidados com a Joia Evite contato com perfumes e produtos químicos para preservar o brilho da prata e o acabamento resinado. Guarde em local seco e separado para evitar oxidação. Limpe com flanela macia para manter o acabamento impecável. Charme e Delicadeza em Prata 925 O Pingente de Prata 925 Medalha Rabo de Sereia Resinada é uma joia encantadora que une delicadeza, significado e estilo. Uma peça perfeita para quem ama o mar e deseja carregar essa energia em todos os momentos.', 101.64, 58.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-81zuo-mkxxvgxfvvgh21', 'https://shope.ee/an_redir?origin_li