INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23696021732', 'Aparelho de Jantar E Chá 20 Pçs Oxford Ryo Bambu', 'Uma coleção que traz muitos elementos da cultura do Japão. O formato orgânico das peças é inspirado na filosofia japonesa que busca a beleza na imperfeição. Já a decoração tem o bambu em destaque, um elemento sempre presente na história e cultura do país. A estética vintage da peça é alcançada através de uma técnica manual de decoração com esmalte reagente. Conteúdo da embalagem: 4 pratos rasos com 27,5 cm de diâmetro / 4 pratos fundos com 22,5 cm de diâmetro e 4,5 cm de altura / 4 pratos para sobremesa com 21,5 cm de diâmetro / 4 xícaras para chá (220 ml de capacidade) com pires (16 cm de diâmetro) - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Tipo da embalagem: Caixa litografada - Material: Porcelana - Cor: Marrom - Decoração: Estampado - Formato: Orgânico - Tipo do jogo: Jantar e almoço - Linha: Ryo - Modelo: Bambu - Quatidade de peças: 20 - É kit de fábrica: Sim - É apto para lava-louças: Sim - É Apto para microondas: Sim ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 659.89, 599.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7qvf5-lhi2ovkpx2ed6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548911108%2F23696021732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893234928', 'Caixa 12un Fini Chicle Clássicos 14G', 'Os Clássicos da Fini na versão em chicle. É muito amor em um só pacote. Cada embalagem tem 4 deliciosos chicles com os inconfundíveis sabores do Tubes de Uva, Dentadura, Banana e Tubes Morango. Display compacto com 18 embalagens de 14g, ideal para levar na bolsa, deixar na gaveta, compartilhar com os amigos ou devorar tudo sozinho. *Poderá ocorrer a falta de algum dos sabores, formatos e/ou cores apresentados, sendo o mesmo substituído por outro de igual qualidade. Clássicos com 18 unidades de 14g cada - Fini', 26.29, 24.98, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5x0u5ex3hj968', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F22893234928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
