INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397748494', 'Gabarito De Furação Em Angulo Com 14Pc Vonder', 'Marca: Vonder Conteúdo da embalagem: 1 Gabarito de furação. Acompanha: 1 chave hexagonal 2,5 mm, 3 brocas de 3 pontas para madeira (6 mm, 8 mm, 10 mm), 3 limitadores de brocas (6 mm, 8 mm, 10 mm), 2 gabaritos de 6 mm, 2 gabaritos de 8 mm e 2 gabaritos de 10 mm. Destaques e diferenciais: Facilita a fixação de parafusos e cavilhas em ângulos. Aplicações e dicas de uso: Ideal para uso em marcenarias para furação e montagem de móveis. Detalhes Técnicos Material (tipo/composição): Alumínio Dimensões (C x L x A) (mm): 74 mm x 38 mm x 19 mm Comprimento da broca: 92 mm (6 mm), 108 mm (8 mm), 120 mm (10 mm) mm Diâmetro da broca: 6 mm, 8 mm, 10 mm Espessura da madeira indicada: Mínimo: 19 mm / Máximo: 38 mm Massa aproximada (peso) (kg): 0,185 kg Garantia - E (CDC): Garantia legal: 90 dias', 93.9, 93.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyi-lzi4sudemh1384', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F23397748494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
