INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197476454', 'Bicicleta Infantil Aro 20 Bmx Freio V-Brake Branco e Rosa Gottbike', 'Seja o mestre da adrenalina com nossa incrível bicicleta BMX aro 20! Projetada para oferecer uma experiência única de emoção e diversão sobre duas rodas, nossa bicicleta combina um design moderno e arrojado com uma construção robusta e resistente. Montagem: A bicicleta é enviada desmontada e requer montagem. Recomendamos que a montagem seja feita por um profissional para garantir ajustes corretos nos freios e demais componentes, proporcionando maior segurança para a criança. Garantia do Fabricante: 3 Meses Recomendações de Uso: Iniciantes Informações Técnicas: - Material do Quadro: Quadro BMX Aço - Modelo e Composição do Guidão: Guidão BMX em Aço - Modelo e Composição do Garfo: Garfo BMX em Aço - Movimento Central: 45mm - Movimento Direção: Standard - Modelo e Composição do Freios: Freios V-Brake - Tipo de Engrenagem: Catraca 18 Dentes e Coroa 36 Dentes - Marca e Composição do Pedivela: Pedivela Monobloco em Aço - Modelo de Pedal: Pedal Nylon - Pneus: Aro 20 - Modelo e Composição do Aro: Aro 20 Alumínio 36 Furos - Marca e Composição dos Cubos: Cubos rolamentados em Aço 36 Furos - Material do Canote: Aço - Marca e Composição do Selim: Selim P.U. Importante: As fotos são ilustrativas, a cor real do produto pode ser ligeiramente diferente devido a diferença de calibragem de monitor e telas de celular. As transportadoras farão a entrega até a porta do endereço onde foi efetuado o pedido, qualquer movimentação do produto a partir dali é de inteira responsabilidade do cliente.', 799.0, 479.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rd5d-lub4vsko6gq655', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1167162323%2F22197476454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
