INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205680913', 'Pastilha De Freio Bosch Traseira Captiva', 'PASTILHAS TRASEIRA APLICAÇÃO: Captiva Sport 2.4 16V LS 2007-2015 Captiva Sport 3.0 FFV 2011-2013 Captiva Sport 3.0 FFV AWD 2011-2013 Captiva Sport 3.6 24V 2008-2011 CÓD ORIGINAL: 0986BB0774 D-Shape D1275 LEIA COM ATENÇÃO AS COMPATIBILIDADES, EM CASO DE DUVIDAS NOS ENCAMINHE CHASSIS, O MODELO DO CARRO E CÓDIGO DA PEÇA Envio: Pagamentos confirmados ate as 13hs. envio no mesmo dia. Obs: Temos envio por motoboy consulte taxa. Garantia: O PRODUTO CONSTA COM 3 MESES DE GARANTIA POR DEFEITO DE FABRICAÇÃO (NOS TERMOS DA LEI Nº8.078 DE 11/09/1990) O PROCEDIMENTO PODE LEVAR ATE 30 DIAS PARA LAUDO E CONSTATAÇÃO DO DEFEITO E TROCA DO PRODUTO. NAO SERA CONCEDIDA GARANTIA NAS SEGUINTES CONDIÇOES: - O produto apresentar danos provocados por acidente de manuseio, erro de montagem, aplicação ou manutenção inadequada; - Contaminação por: oleos e derivados, particulas metalicas, arenosas ou cristalinas em excesso, etc... - Cargas excessivas e engripamento provocados por outros componentes que comprometem o funcionamento e a vida util da peça; - Violação do produto, sinais de danificação,amassados ou quebras; - Ausência de documentos para analise como: Nota Fiscal ou Pedido de compra que comprovem a data da compra e instalação. ATENÇÃO ANTES DE EFETUAR A COMPRA, VERIFIQUE SE A NUMERAÇÃO ORIGINAL DE NOSSO ANÚNCIO É IGUAL A NUMERAÇÃO ORIGINAL DE SUA PEÇA. SENDO NUMERAÇÕES COMPATÍVEIS, LHE APLICA PERFEITAMENTE. SENDO DIFERENTE, NÃO IRÁ SERVIR; CASO NÃO TENHA A NUMERAÇÃO ORIGINAL EM MÃOS, ENTRE EM CONTATO COM SUA CONCESSIONÁRIA, E SOLICITE O CÓDIGO ORIGINAL DE SUA PEÇA; PEDIMOS A GENTILEZA DA COMPREENSÃO, PRA EVITAR POSSÍVEIS TRANSTORNOS. PARA DEVOLUÇÃO DE PRODUTO, SOMENTE COM A EMBALAGEM ORIGINAL E SEM USO. Garantia do vendedor: 3 meses', 159.0, 159.0, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-823of-mpc8ou8xa6fh9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593927039%2F58205680913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293560212', 'Bolsa em Lona Para Transporte de Ferramentas (323201) - Onsite', 'A Bolsa de Lona Para Ferramentas Com 16 Bolsos 500 x 250 x 305mm (323201) - Onsite, é usada para transportar e organizar ferramentas de forma prática e eficiente. Feita de material resistente, como a lona, essa bolsa oferece durabilidade e proteção para as ferramentas, sendo muito útil para profissionais e entusiastas do ''''faça você mesmo'''' que precisam de suas ferramentas sempre à mão. Aqui estão os principais usos e benefícios de uma bolsa de lona para ferramentas: • Facilidade de transporte: Permite que você carregue suas ferramentas com facilidade de um local para outro, especialmente em obras, oficinas ou locais de trabalho externos. • Organização: Possui compartimentos e bolsos que ajudam a manter diferentes tipos de ferramentas organizadas, como chaves, martelos, alicates e parafusos. • Proteção das ferramentas: A lona é resistente e protege as ferramentas contra sujeira, poeira e até mesmo leves batidas ou quedas. Algumas bolsas podem ser impermeáveis, garantindo proteção contra chuva ou umidade. • Durabilidade: O material de lona é robusto e resistente a rasgos e desgastes, suportando bem o peso das ferramentas e o uso frequente. • Praticidade no trabalho: Facilita o acesso rápido às ferramentas, o que aumenta a eficiência em reparos ou manutenções, uma vez que o profissional tem tudo organizado e à mão. • É uma excelente opção para quem precisa de mobilidade e organização em trabalhos de construção, mecânica, elétrica ou outras atividades que demandam o uso frequente de ferramentas manuais. Código: 323201. Marca: Onsite. Tamanho: 500 x 250 x 305mm. Ean: 1008500989466.', 169.9, 169.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfez-m361hohwpnue2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23293560212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8399815648', 'Luva Tricotada em Poliéster Banho Nitrílico PPM04 PROTEPLUS N8', 'Luva Tricotada em Poliéster com Banho NitrílicoLuva de segurança confeccionada em malha de poliéster. Pigmentos com aplique em borracha nitrílica nas palmas, dedos e pontas dos dedos na cor cinza. Punho com acabamento em elastano e costura em overloque. Aplicação: Trabalhos leves, médios e pesados, manuseio de materiais e produtos secos sob temperatura ambiente e agentes mecânicos (abrasão, corte, rasgamento e perfuração) em indústria metal-mecânica, construção civil, madeireira, plástica, cerâmica, coleta de lixo, jardinagem, uso doméstico e outros. Embalagem: 1 par Referência: PPM 04 Tamanho: 8 Código: 291,0006 EAN:7898960479881', 10.3, 10.3, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/sg-11134201-22120-ot5qyyf8iflvf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F8399815648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
