INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22523095140', 'Acabamento Quadrado Registro Volante Metal Dourado', 'Acabamento Quadrado Para Registro Volante Metal Padrão Deca (16 Estrias) SERVE EM BASES: 1/2, 3/4 E 1 POLEGADA Fabricados com materiais de alta qualidade, os acabamentos de registro da Stillus Home trazem um visual mais moderno e elegante ao seu ambiente. Produzido todo em Metal e com acabamento dourado com Tripla Camada de Cromo, seguindo o padrão das marcas mais nobres do mercado evitando assim que descasque ou perca o brilho. O Acabamento Quadrado Para Registro Volante de Metal Padrão Deca, é fabricado com materiais de alta qualidade e acompanham o padrão ABNT (Associação Brasileira de Normas Técnicas) Registros de Pressão e Gaveta COMPATÍVEL COM: DECA, Kelly, KiMetais, Talita, Esteves, Tigre, Pevilon, Hidrofix, Oneel, Sigma Metais, Furkin, Admo, Oriente Atual, Forusi, Bognar, Bometal, Stoc Metais, entre outros que seguem o mesmo padrão Deca. NÃO É COMPATÍVEL COM: DOCOL, Lorenzetti, Fabrimar ou qualquer outro fabricante que segue o mesmo padrão. ESPECIFICAÇÕES: - Marca Stillus Home - Compatível com registros: 1/2", 3/4", e 1" - Volante e canopla em METAL DOURADO (alta resistência) - ACABAMENTO: Tripla Camada de Cromo Dourado - PADRÃO DA ESTRIA: PADRÃO DECA. - MEDIDAS: VIDE FOTO ÍTENS INCLUSOS: 01 Volante Quadrado em Metal (Manopla). 01 Canopla Quadrada em Metal (Base). 01 Rosca para canopla. 01 Parafuso* Instalação (M4). *Já vai posicionado no furo do volante. 01 Chave Allen Instalação (2mm) GARANTIA: 6 MESES CONTRA DEFEITOS DE FABRICAÇÃO!!!!', 79.89, 41.89, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rat0-maoec5m53giq49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469163480%2F22523095140', NULL, NUL