INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29129086206', 'Filtro Ar Esportivo Lavável Preto Vermelho Titan 150 Fan 150 Fan 160', 'Filtro Ar Esportivo Lavável Preto Vermelho Titan Fan 150 Fan 160 CÓDIGO: COD_17166 APLICAÇÕES: TITAN 150 FAN 150 FAN 160 A partir de 2014 até 2023 - Instalação Completa: Acompanha tampa lateral para fixação fácil e segura do filtro na motocicleta. - Filtro Esportivo: Melhora o desempenho do motor, oferecendo maior vazão de ar e aceleração. - Lavável e Prático: Manutenção simples, com lavagem recomendada a cada 5000 km usando detergente neutro. - Ronco Esportivo: Proporciona um som esportivo ao motor, similar ao de uma moto sem filtro. - Sem Necessidade de Óleo: Dispensa o uso de óleo no filtro, garantindo facilidade de uso e menos manutenção. Liberte a fera que existe na sua moto! Adquira agora mesmo o Filtro de Ar Esportivo e experimente a emoção de pilotar com potência e performance. Conteúdo da Embalagem: - Filtro de ar - Moldura !!!!!!!!!!!!!!! IMAGENS MERAMENTE ILUSTRATIVAS !!!!!!!!!!!!!!! Produzido com os melhores equipamentos, garantindo segurança e durabilidade. Oferecendo sempre o melhor custo benefício, unindo qualidade e eficiência na sua utilidade. SOBRE NOSSA EMPRESA: Somos uma organização com anos de experiência no mercado. Seja você um apaixonado por velocidade, um aventureiro de estrada ou um entusiasta da personalização, cumprimos a missão de fornecer peças e acessórios da mais alta qualidade para elevar sua experiência de pilotagem a um novo patamar. UTILIZE O CAMPO DE PERGUNTAS PARA TIRAR SUAS DÚVIDAS, e apenas confirme a compra em caso de CERTEZA de compatibilidade do produto!', 89.99, 89.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m76sk9jfi1qk43', 'https://shope.ee/an_redi