INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47655610452', 'Jogo Educativo Infantil Ursinho Como Me Sinto Sentimentos Emoções', 'O Ursinho Como Me Sinto da Babebi, foi desenvolvido para ajudar as crianças a reconhecer, nomear e expressar emoções de forma lúdica e divertida. Por meio de peças ilustradas com expressões faciais, a criança aprende brincando, estimulando o desenvolvimento emocional e social desde cedo. Ideal para uso em casa, na escola ou em terapias, este brinquedo promove momentos de interação entre pais e filhos, fortalecendo vínculos afetivos e a comunicação. Especificações Técnicas - Quantidade de Peças: 37 (1 Tabuleiro, 24 Expressões e 12 Fichas com Sentimentos) - Medidas: 28 x 28 cm (Caixa) - Material: Madeira reflorestada - Ilustrações: Ursinhos - Recomendado para: Crianças a partir de 3 anos - Certificação INMETRO: 009272/2022 Ficou alguma dúvida? Sinta-se à vontade para nos enviar uma pergunta! Nossa equipe de atendimento está pronta para te auxiliar da melhor forma!', 79.9, 64.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2fxfiubu9vb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438068303%2F47655610452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
