INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55950733615', 'BODY SPLASH MASCULINO ADVENTUS 200ML - PRIMACIAL PERFUME AMADEIRADO CITRICO', 'Body Man Adventus 200ml Perfume Masculino Sofisticado | Perfume Elegante e Marcante Uma fragrância masculina que transmite sucesso, confiança e elegância em cada borrifada. O Body Man Adventus entrega uma combinação envolvente entre frescor frutado, toque sofisticado e fundo amadeirado, ideal para homens que gostam de um aroma moderno, imponente e muito agradável de sentir no dia a dia. Pirâmide Olfativa: Topo: Bergamota, Maçã, Limão e Pimenta Rosa Coração: Abacaxi, Patchouli e Jasmim Fundo: Vidoeiro, Almíscar, Musgo de Carvalho, Âmbar e Cedro Quando Usar: 🌤️ Dia: Excelente 🌙 Noite: Excelente ☀️ Perfeito para todas as estações 📦 Detalhes do Produto: ✔ Contém 1 body splash masculino de 200ml ✔ Fragrância masculina fresca e sofisticada ✔ Aroma marcante e versátil ✔ Ideal para uso diário ✔ Perfeito para homens que gostam de presença e elegância 💡 Dica de uso: Aplique após o banho e reaplique ao longo do dia para manter a sensação de frescor e presença. É uma ótima escolha para trabalho, compromissos do dia a dia e ocasiões em que você quer estar bem perfumado.', 69.9, 45.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820lz-ml84a8u9o2kl41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F55950733615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
