INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18969253182', 'Remendo A Frio R-02 50 Mm - Caixa Com 80 Peças - VIPAL', 'Remendo a frio R-02 50mm - Caixa com 80 peças - Vipal Disponíveis em diferentes formatos e medidas, os remendos e plaquetas para câmaras de ar têm espessura extrafina e poder de expansão que acompanha a elasticidade da câmara, não criando calosidades. Utilizam a vulcanização química (sistema a frio), que não submete as câmaras de ar ao calor, prolongando sua vida útil. Remendo a frio Vipal R-02 Medida: 50mm Caixa com 80 peças - PRODUTO ORIGINAL, COM NOTA FISCAL E GARANTIA!', 75.0, 75.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lyo1513uxlgl6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F234345625%2F18969253182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
