INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899342365', 'Armário Rose 3 Portas em Aço Itatiaia', 'O Armário de aço Rose da Itatiaia oferece a solução ideal para espaços reduzidos, com a qualidade da cozinha de aço. O revestimento do armário é pelo moderno sistema de pintura eletrostática a pó, que além de ser muito durável, não é poluente, garante mais resistência, proteção conta ferrugem, corrosão e variações bruscas de temperatura. Características: Marca: Itatiaia Modelo: Rose Necessita Montagem: Sim Escala de Brilho: Semi-Brilho Possui Prateleiras: Não Acabamento: Pintura eletrostática a pó Escala de Brilho da Porta: Semi-Brilho Ambiente Principal: Cozinha Linha ou Coleção: Rose Sapatas Niveladoras: Não Material da Porta: Aço Sistema de Montagem: Parafusos Possui Portas: 03 Tipo de Puxador da Porta: Externo Estilo: Clássico Complexidade da Montagem: Média, pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Tipo de Dobradiça/Corrediça da Porta: Simples Material Principal: Aço Possui Pés: Não Acabamento da Porta: Pintura Possui Gavetas: Não Tipo de Porta: Bater Dimensões do produto: Altura: 40 cm Largura: 105 cm Profundidade: 28 cm Peso: 7,9 kg Garantia do Fornecedor: 12 Meses', 389.0, 389.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkcglaxxr18j31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F395742608%2F22899342365', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
