INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893167632', 'Regulador Freio Gm Astra 1995 a 1996 - 203930 - 2112', 'Regulador Freio Gm Astra 1995 a 1996 203930 2112 (AUTOMATICO) (1 RODA - TRASEIRA - LADO ESQUERDO) (SISTEMA VARGA) Compensa o desgaste das lonas, mantendo as sapatas sempre próximas ao tambor. Aplica nas rodas traseiras. Mas também nas rodas dianteiras, com freio a tambor dianteiro. Para regulagem automática, a peça fica entre as sapatas, presa por molas e com o auxilio (ou não) dos acionadores compensa o desgaste das lonas. Ocorre quando pedal de freio é acionado. Regulagem manual, ajuste deve ser feito manualmente por um mecânico. _x000D_ Fabricado em aço, com componentes em aço inox e materiais sinterizados.', 39.12, 39.12, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd4i-lvtpdkdx67j1b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23893167632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
