INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597475114', 'Cubo Roda Fiat Palio 1997 a 2010 - 512878 - HFCD31A', 'Cubo Roda Fiat Palio 1997 a 2010 512878 HFCD31A (Weekend) - Motor 1.6/1.8 - (Dianteira) (4 Furos) (Forjado) (22 Dentes) (Sem Rolamento) (Encanelado) Peça responsável por transmitir o livre movimento realizado pelas juntas homocinéticas sem riscos de atrito, o cubo de roda automotivo ainda é encarregado por realizar o suporte do disco de freio, local onde os parafusos das rodas são fixados. O funcionamento do cubo de roda automotivo ocorre quando as juntas homocinéticas, que estão conectadas ao cubo de roda, transmitem a rotação entre eles, gerando, assim, o movimento da roda.', 105.22, 105.22, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Wheels', 'https://cf.shopee.com.br/file/sg-11134201-7r9ab-ln7e33sa5e012b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19597475114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999033618', 'Calço Coxim Hidraulico Motor S10 98/ Blazer 96/11 Omega 93/ - 1325 - ACX02030', 'Calço Coxim Hidraulico Motor S10 98/ Blazer 96/11 Omega 93/ GM - Omega / Suprema 2.0/2.2 1993/1998 - S10 2.2/2.4 1998/2011 - Blazer 2.2/2.4 1996/2011 - (Dianteiro - Lado Esquerdo/Direito) São divididos em 3 grupos: coxins do motor, coxins do câmbio e coxins do amortecedor. A função do coxim de motor/câmbio é ser o ponto de apoio do motor no chassi, fazendo a absorção da vibração do motor e evitando que seja transmitido para o veículo. O uso de coxins danificados diminuirá significativamente a vida útil do motor/câmbio do veículo.', 93.01, 93.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-lmyrwj1vuggg1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18999033618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56814006121', 'Brinco Zircônia Redonda Citrino 4mm em Prata 925 Delicado e Elegante', 'O Brinco Zircônia Redonda Citrino 4mm em Prata 925 é uma joia delicada e sofisticada, perfeita para quem busca um acessório clássico com um toque de cor. A zircônia redonda em tom citrino de 4mm proporciona brilho intenso e elegância, tornando a peça ideal para o uso diário ou para complementar produções refinadas. Material: Prata 925 Pedra: Zircônia citrino Formato da pedra: Redonda Tamanho da pedra: 4 mm Modelo: Ponto de luz Fecho: Tarraxa tradicional Acompanha: Certificado de garantia de autenticidade. Observação: Não acompanha caixinha. Uma joia atemporal e versátil, perfeita para quem valoriza delicadeza, brilho e sofisticação em qualquer ocasião.', 180.0, 99.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-820lo-mqnal4h7o6wyfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F56814006121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
