INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493598443', 'Esguicho Reto para Mangueira com 12 unidades Tramontina', 'Esguicho Reto Tramontina para Irrigação de Jardins e Hortas Regulável é a solução ideal para quem busca eficiência e praticidade no cuidado com plantas. Fabricado em plástico de alta qualidade, este esguicho é durável e resistente a impactos, garantindo longa vida útil. Seu sistema de regulagem frontal permite ajustar o fluxo de água conforme a necessidade, tornando-o perfeito para diferentes tipos de irrigação. Com design ergonômico e leve, o Esguicho Tramontina proporciona conforto mesmo durante o uso prolongado. Além disso, sua conexão prática é compatível com mangueiras de 1/2", 5/8" e 3/4", facilitando a conexão com engate rápido. Vantagens: Material resistente: Fabricado em plástico durável. Regulagem de fluxo: Ajuste fácil do jato de água. Conexão prática: Compatível com diversas mangueiras. Design ergonômico: Uso confortável e sem fadiga. Uso versátil: Ideal para jardins e hortas. Sustentabilidade: Orientações para descarte responsável. Especificações técnicas: Marca: Tramontina Material: Plástico resistente Sistema de regulagem frontal Compatibilidade: Mangueiras de 1/2", 5/8", 3/4" Engate rápido Dimensões compactas Leveza para manuseio fácil Conteúdo da embalagem: Esguicho Reto Tramontina Garantia: Garantia de 12 meses pelo fabricante', 154.8, 79.5, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfhf-m40fz028grpue4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23493598443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259445406', 'Spaten Puro Malte Cerveja', 'Spaten é uma cerveja Munich Helles puro malte, ideal para quem aprecia uma cerveja de alta qualidade e sabor único. Produzida com água, malte e lúpulo, a Spaten possui um teor alcoólico de 5.2% e amargor de 16 IBU. Beba com moderação.', 5.99, 5.19, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-823rc-moo4iq0g3y826d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58259445406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8738403818', 'Filtro De Ar Nissan March 1.0 16v até 2013 logan sandero clio 1.0 16v até 2013 HLP5138 C3366/1', 'filtro de ar clio flex logan sandero 1.0 16V Filtro de ar de motor Sujeira pode comprometer a força do motor ao alterar a queima do combustível O filtro de ar impede que as impurezas existentes na atmosfera entrem e fiquem incrustadas dentro do motor. Essa sujeira pode comprometer a sua força, danificar seus componentes e piorar o consumo. Quanto mais limpo for o conteúdo aspirado, mais eficiente será a queima de combustível. Qual a função do filtro de ar do motor? O filtro de ar serve para evitar que as partículas de impureza do ar cheguem à câmara de combustão do motor. Com ele em dia reduz-se o desgaste em componentes como pistões e bielas, além de reduzir o consumo de combustível.', 34.99, 34.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lo-mlxvmuxdfwnb24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F8738403818', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
