INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593477148', 'Mistura Para Bolo Sabor Coco Linea 300g - 2 unidades', 'Mistura para Bolo Linea é macia, saborosa e fonte de fibras. Sem adição de açúcares, é adoçado com sucralose, o adoçante derivado da cana de açúcar. De fácil preparo, basta adicionar 2 ovos e água ou leite, sem precisar adicionar margarina ou manteiga. Por ser zero lactose, os intolerantes a lactose podem preparar com água, leite zero lactose ou bebida vegetal. 1 Kit Composto por: - 2 Misturas Para Bolo Sabor Coco Linea 300g INGREDIENTES farinha de trigo enriquecida com ferro e ácido fólico, amido de milho, gordura vegetal de palma, edulcorantes: maltitol e sucralose, espessantes: polidextrose e goma xantana, emulsificante mono e diglicerídeos de ácidos graxos, antiumectante fosfato tricálcico, fermentos químicos: fosfato monocálcio, difosfato de cálcio e bicarbonato de sódio e aromatizante. CONTÉM DERIVADOS DE TRIGO E LEITE. PODE CONTER CENTEIO, CEVADA, AVEIA E SOJA. CONTÉM GLÚTEN.', 52.78, 47.5, NULL, 'Food & Beverages > Baking Needs > Baking Premix Flour', 'https://cf.shopee.com.br/file/sg-11134201-7rdw9-m1egm96tnofyf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F22593477148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899069649', 'Base Liquida Oceane Edition Skin Foundation Semi Matte', 'Descrição: A Base Liquida Oceane Edition Skin Foundation Semi Matte transforma o seu visual e deixa a sua pele do jeito que você sempre sonhou. É uma base semi-matte de média cobertura e acabamento suave. Isso significa que ela uniformiza o tom da pele sem pesar, não marca as linhas de expressão e corrige pequenas imperfeições. Possui longa duração para que você aproveite os seus melhores momentos. Além de todos esses benefícios, esta base líquida possui uma fórmula vegana, o que significa que não contém ingredientes de origem animal em sua composição. Ela é enriquecida com Vitamina E, Hamamélis e Extrato de Pepino e é apresentada em uma embalagem com válvula pump que evita o desperdício e torna a aplicação extremamente prática. Cores: 110F, 210L, 230L, 300M, 315M, 400M, 420T, 440T, 500D, 550D. MODO DE USAR: 1 - Com o próprio dosador da embalagem, aplique uma gota do produto nos seguintes pontos: uma em cada maçã do rosto, no meio da testa, no queixo e na ponta do nariz. 2 - Depois com a ajuda do Pincel ou da Esponja, espalhe delicadamente por todo o rosto e pescoço, cuidando para que cada canto seja preenchido uniformemente. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 35ml. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 59.99, 59.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-7rfez-m33tgi51tknxc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F19899069649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
