INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498153834', 'Conjunto Tomada 10A 250V Horizontal Ilumi', 'A tomada 10A Slim da Ilumi é a escolha perfeita para quem busca funcionalidade e design moderno em um único produto. Com uma corrente de 10 amperes, ela oferece segurança e confiabilidade para suas conexões elétricas diárias. Desenvolvida com materiais de alta qualidade, esta tomada é durável e possui acabamento sofisticado que se adapta a qualquer ambiente. Sua instalação é simples e prática, economizando tempo e esforço ao usuário. Além disso, sua estrutura compacta permite um ajuste perfeito em espaços reduzidos. Benefícios do produto e características: A tomada Ilumi Slim se destaca por seu design discreto e eficiente, tornando-se uma opção ideal para instalações modernas. Sua capacidade de 10A garante que você possa conectar diversos aparelhos sem preocupações com sobrecarga. Especificações técnicas: Marca: Ilumi Corrente: 10A Design: Slim Conteúdo da embalagem: - Tomada 10A Slim Ilumi Garantia: - 3 meses pelo fabricante.', 35.9, 35.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Electric Sockets & Extension Cords', 'https://cf.shopee.com.br/file/sg-11134201-7rcd7-m6iaxesue5jdba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22498153834', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198358690', 'Maquina Para Assentar Piso Com Duas Bateria 12v MAP120 Vonder', 'Maquina Para Assentar Piso Com Duas Bateria 12v MAP120 Vonder O Kit Máquina de Assentar Piso VONDER MAP 120 é a solução perfeita para quem busca agilidade e precisão na instalação de porcelanatos e pisos em geral. Compacta e eficiente, a ferramenta possui alto poder de sucção e regulagem com 5 níveis de vibração ajustáveis via display, proporcionando total controle durante a aplicação. Ideal para pisos com superfície lisa de até 70 cm x 70 cm. Itens Inclusos: 1 Máquina de Assentar Piso com Ventosa 12V modelo MAP 120 2 Baterias Íons de Lítio 12V 2,2Ah 1 Fonte Bivolt Automático 1 Maleta plástica 1 Manual de Instruções Aplicação: Indicada para assentamento de porcelanatos e pisos em geral com superfície lisa (até 70 cm x 70 cm) Detalhes Técnicos Máquina MAP 120: Referência: 6001120000 Tipo de bateria: Íons de Lítio 12V – 2,2 Ah Capacidade de carga: 30 kgf Potência do motor: 120W Tensão de entrada da fonte: 100V ~ 240V (Bivolt automático) Tensão de saída da fonte: 12V DC Tempo de carregamento: 2 horas Níveis de vibração: 5 níveis com controle por display Número de vibrações por minuto (vpm): Nível 1: 2.200/min Nível 2: 5.520/min Nível 3: 6.920/min Nível 4: 8.250/min Nível 5: 9.300/min Aceleração transmitida ao operador (mãos/braços): Nível 1: 3 m/s² Nível 2: 45 m/s² Nível 3: 55 m/s² Nível 4: 70 m/s² Nível 5: 150 m/s² Incerteza da aceleração: 1,5 m/s² Nível de ruído: 60 dB(A) (sem carga) / 70 dB(A) (com carga) Diâmetro da ventosa: 120 mm Dimensões: 320 mm x 120 mm x 130 mm Garantia: 90 dias de garantia legal + 9 meses de garantia contratual Baterias 12V 2,2Ah Íons de Lítio: Referência: 9324120001 Capacidade: 2,2 Ah Tensão: 12V Tipo: Íons de Lítio Indicador de carga: Não Peso aproximado: 0,182 kg Por qu