INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693230668', 'Roupa Intima Plenitud Classic G/XG 16 Unidades', 'A Plenitud Classic é uma roupa íntima descartável com cintura elástica, fácil de colocar e tirar, que proporciona máxima absorção da urina com controle de odores. A roupa íntima Plenitud Classic é indicada para adultos com mobilidade reduzida e necessitam de uma roupa íntima com alto poder de absorção para incontinência intensa durante o dia. Foi desenvolvida com barreira protetora que previne vazamentos, além da tecnologia que neutraliza e controla odores.', 73.13, 73.13, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rdxw-lzfnc92wnx8m98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23693230668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
