INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798275831', 'Tênis Feminino Moleca 5796204', 'Tênis Feminino Moleca 5796204 Estilo, conforto e versatilidade em um só calçado! O Tênis Moleca 5796204 é perfeito para mulheres que buscam praticidade no dia a dia sem abrir mão da moda. Com design moderno e acabamento impecável, ele combina facilmente com looks casuais e urbanos, sendo ideal para passeios, trabalho ou compromissos cotidianos Principais Características Design: Visual contemporâneo com linhas minimalistas que valorizam o estilo feminino. Material: Confeccionado em alta qualidade, resistente e fácil de limpar. Solado: Emborrachado, leve e antiderrapante, garantindo mais segurança ao caminhar. Benefícios Conforto garantido: Palmilha macia que proporciona bem-estar durante todo o dia. Praticidade: Modelo com fechamento em cadarço para ajuste perfeito. Versatilidade: Combina com calças, shorts, vestidos e saias em diferentes ocasiões. Especificações Técnicas Marca: Moleca Modelo: Tênis Referência: 5796204 Gênero: Feminino Material externo: Têxtil-Tecido Material interno: Têxtil-Tecido Solado: Latex-Borracha Altura do solado: 3,0 cm Fechamento: Cadarço Cores disponíveis: Lona/Napa/Preto Branco Numeração: 34 ao 39 Peso: 500 aproximadamente (o par) Tabela de Medidas 34 = 23,5 cm 35 = 24,0 cm 36 = 24,5 cm 37 = 25,0 cm 38 = 26,0 cm 39 = 27,0 cm Por que escolher o Tênis Moleca 5796204? Porque ele une leveza, estilo e conforto em um único calçado, sendo a escolha ideal para quem deseja praticidade e modernidade no dia a dia. Adquira já o seu Tênis Moleca 5796204 Um tênis casual, confortável e cheio de charme — perfeito para completar produções modernas e descontraídas.', 109.9, 91.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824jl-mdw08nez29l20e', 'https://shope.ee/an_redir?origin_link=http