INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597709293', 'Kit Shampoo e Condicionador 250ml Essential e Máscara 200 - Braé', 'Kit Essential Braé Contém Shampoo,Condicionador 250ML e Mascara 200Ml. Kit Braé Shampoo,Condicionador e Mascara ( 3 Produtos) Braé Essential Shampoo 250ml Shampoo nutritivo que repara os fios danificados, promove hidratação progressiva e protege o cabelo contra agressões diárias e térmicas. Com ácido hialurônico, aminoácidos e complexo de óleos, os cabelos ficam mais fortalecidos. Indicado para todos os tipos de cabelos. A Linha Essential foi co-criada ao lado de cabelereiros experts da Braé, para oferecer um tratamento REPARADOR INTENSIVO. Sua fórmula é enriquecida com AC. HIALURÔNICO, ativo consagrado e reconhecido no universo de skin care, que possui PROPRIEDADES HIDRATANTES, além de AMINOÁCIDOS e COMPLEXO DE ÓLEOS poderosos que em conjunto, reparam agressões diárias dos fios danificados. O grande diferencial da linha é que todos os produtos possuem PROTEÇÃO TÉRMICA, garantindo proteção diária dos fios. Tratamento de alta performance para cabelos reparados, nutridos e macios. Conselho de Aplicação: Aplique no cabelo molhado, massageando suavemente sem esfregar os fios. Enxague. Braé Essential Condicionador 250ml Condicionador nutritivo que repara os fios danificados, promove hidratação progressiva e protege o cabelo contra agressões diárias e térmicas. Com ácido hialurônico, aminoácidos e complexo de óleos, os cabelos ficam mais fortalecidos. Indicado para todos os tipos de cabelos. A Linha Essential foi co-criada ao lado de cabelereiros experts da Braé, para oferecer um tratamento REPARADOR INTENSIVO. Sua fórmula é enriquecida com AC. HIALURÔNICO, ativo consagrado e reconhecido no universo de skin care, que possui PROPRIEDADES HIDRATANTES, além de AMINOÁCIDOS e COMPLEXO DE ÓLEOS poderosos que em conjunto, reparam agressões diárias dos fios danificados. O grande diferencial da linha é que todos os produtos possuem PROTEÇÃO TÉRMICA, garantindo proteção diária dos fios. Tratamento de alta performance para cabelos reparados, nutridos e macios. Conselho de Aplicação: Deve ser usado após o shampoo. Aplique massageando suavemente do comprimento às pontas. Deixe agir de 1 a 2 minutos. Enxague. Braé Essential - Máscara 200g Tratamento reparador intensivo, possui fórmula com ácido hialurônico, aminoácidos e complexo de óleos poderosos que em conjunto, reparam agressões diárias dos fios danificados. Possui proteção térmica. Indicado para todos os tipos de cabelos. Conselho de Aplicação Após lavar o cabelo com shampoo, aplique massageando vigorosamente da raiz até as pontas. Deixe agir de 10 a 15 minutos. Enxague.', 336.14, 336.14, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-lyvacimptl4cb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F23597709293', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
