INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493698891', 'LUIS RICARDO MUITO ALÉM DO PALHAÇO MAIS FAMOSO DO MUNDO', 'LUIS RICARDO MUITO ALÉM DO PALHAÇO MAIS FAMOSO DO MUNDO Um livro repleto de confissões jamais ditas em nenhum canal!Ao longo de seus mais de 40 anos de carreira, a história de LUIS RICARDO se confunde com a história do SBT. Estreou no mesmo ano da criação da emissora, onde está até hoje.Porém, a vida de Luis Ricardo é cercada de enredos entrelaçados entre sua vida com a família no circo, como intérprete do maior palhaço do mundo e substituto eficaz do maior comunicador do Brasil, Silvio Santos.Nascido numa família circense e tendo sua bisavó como balonista na Europa, Luis Ricardo se revela nesta obra que irá te envolver não só pelas histórias, mas pelas lições e reflexões que irão tocar seu coração do início ao fim!. Informações Adicionais Autor: WILLIAM, SANCHES Data Publicação: 09/03/2025 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: LUIS RICARDO MUITO ALÉM DO PALHAÇO MAIS FAMOSO DO MUNDO Idioma: INDEFINIDO Páginas: 192 Edição: 1 ISBN-13: 9786550475314 ISBN-10: 6550475317', 62.9, 62.9, NULL, 'Books & Magazines > Books > Biography & Memoirs', 'https://cf.shopee.com.br/file/sg-11134201-7rbly-m62hdfuj7zk0b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23493698891', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
