INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997920082', 'Parafusadeira Furadeira Com Impacto PFV120I Bivolt 12v Vonder', 'Parafusadeira Furadeira Com Impacto PFV120I Bivolt 12v Vonder A Parafusadeira/Furadeira 12V VONDER, disponível na Zbrothers, é a ferramenta perfeita para quem busca praticidade, potência e versatilidade. Com uma bateria de íons de lítio de 12V, este modelo oferece maior autonomia e durabilidade para realizar diversas tarefas com eficiência. Conteúdo da Embalagem: 1 Parafusadeira/Furadeira VONDER 12V 1 Maleta Plástica para Transporte 1 Bateria 12V - 1,3 Ah (Íons de Lítio) 1 Fonte de Alimentação Bivolt Automática (100V - 240V) 6 Brocas (1,5 mm, 2,5 mm, 3 mm, 4 mm, 5 mm, 6 mm) 6 Bits (Fenda 5 mm e 6 mm, PZ1, PZ2, PH1, PH2) 1 Prolongador de 60 mm Principais Características: Modelo: PFV 120I Mandril: Aperto rápido de 3/8" - 10 mm Bateria: 12V - 1,3 Ah (Íons de Lítio) Tensão de Entrada: 100V - 240V (Bivolt Automático) Velocidade: 2 velocidades variáveis (0-400 RPM e 0-1.400 RPM) Funções: 3 modos de operação (Parafusadeira, Furadeira sem Impacto e Furadeira com Impacto) Perfuração: Aço: Até 10 mm Madeira: Até 16 mm Concreto/Alvenaria: Até 10 mm Impactos por Minuto (IPM): 0 - 21.000/min Peso: 1,07 kg Normas: ABNT NBR IEC 60745-1, ABNT NBR IEC 60745-2-1, ABNT NBR IEC 60745-2-2 Benefícios: Alta Eficiência: A bateria de íons de lítio oferece maior tempo de uso e desempenho superior. Versatilidade: Conta com 18 posições de torque, 3 funções de operação e 2 velocidades para se adequar a diferentes trabalhos. Conforto e Praticidade: Cabo emborrachado para maior conforto, LED integrado para iluminar áreas de trabalho e indicador de carga da bateria para garantir que você não fique na mão. Organização: Todos os acessórios são organizados na maleta de transporte, garantindo fácil acesso e prolongando a vida útil do produto. Aplicações: Aparafusamento e perfuração em diversos materiais, como madeira, metal e alvenaria. Ideal para profissionais e hobistas que buscam uma ferramenta eficiente e fácil de manusear. Garantia: Legal: 90 dias Contratual: 9 meses (Para locadoras, garantia exclusiva de 90 dias)', 279.9, 279.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mikla3b6ajnm72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F18997920082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
