INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093240860', 'Sandália Mississipi de Salto Baixo Metalizada MB942', 'Produto marca Mississipi. A Sandália Mississipi de Salto Baixo da coleção Primavera/Verão 2024 é a escolha perfeita para mulheres que buscam um calçado versátil, prático e com um toque de sofisticação e está disponível na cor metalizada. Seu design minimalista e atemporal, com tiras finas que envolvem os pés e detalhes de nós, a torna ideal para diversas ocasiões, desde um dia de trabalho até um happy hour com as amigas. o salto baixo de 2 cm confere um toque de elegância e alonga a silhueta, enquanto a tira frontal com textura brilhante adiciona um toque de modernidade e brilho. O destaque desta sandália fica por conta da combinação de conforto e estilo. o calce fácil, sem fechamentos, garante praticidade e leveza, enquanto o salto baixo proporciona estabilidade ao caminhar. Além diso, a tira frontal com textura brilhante, confere um ar sofisticado e elegante e o material sintético garante durabilidade, tornando-a ideal para o uso diário. Peso: 0,521 kg Altura da sola: 2,00 cm', 119.9, 119.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134201-820ls-mqxx21vpxj4499', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23093240860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
