INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20176319044', 'round lab 1025 dokdo cleanser 20, 40g', 'Laboratório redondo 1025 dokdo limpador 20, 40g envio da coreia Informações do produto Data de validade: 25.04.24 Ajuda a limpar suavemente com bolhas finas para tornar sua pele saudável. Cuidados com o equilíbrio de umidade do equilibrado de Ulleungdo água do mar profundo. A água do fundo Ulleungdo da Dokdo Cleanser Redonda Lab 1025 contém com segurança 27 minerais de origem natural, como magnésio, cálcio e zinco, com tecnologia patenteada para fabricação de água mineral usando uma membrana nanofiltração. Limpa completamente a poeira ultrafina. Remove de forma limpa poeira ultrafina invisível, resíduos e resíduos de maquiagem para manter sua pele clara e úmida. Limpador fraco que equilibra a pele 5.0-6.0 limpador fracamente ácido que equilibra a pele. Hidrata sem aperto com fator hidratante. Os ingredientes calmantes do pantenol, alantoína e ceramida NP protegem confortavelmente a pele irritada pelo ambiente externo. [Como Usar] Ao lavar o rosto, pegue uma quantidade adequada, espuma o suficiente, massageie todo o rosto suavemente e enxágue bem com água morna. Capacidade do produto] 20, 40g [Opções] Limpador de dokdo 20g Limpador dokdo 40g #Good Preço do preço #Good Qualidade de qualidade #Korean Cosméticos Cosméticos #KBeleza ————————————————————————————————————————————————————————————————————————————————————————————————— ♡Beleza 1.Fazemos desinfecção três vezes por semana.√ 2.Vendemos 100% genuíno.√', 36.26, 36.26, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134207-7rdwl-lxkqtfgmc9en64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F457864097%2F20176319044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19819507152', 'Amino Acqua Infusion Therapy 250ml Fortalecedor Capilar', 'AMINO ACQUA INFUSION THERAPY Água polarizada para vaporização, ionização, preparados cosméticos e outras misturas terapêuticas. Sua composição é rica em PCA-Na e aminoácidos essências para a pele, para o couro cabeludo e também para os cabelos. Contribui para a hidratação e melhora o processo de absorção de produtos combinados. Promove excelente associação com argilas, máscaras e outros preparados cosméticos. Sua polaridade catiônica aumenta expressivamente o condicionamento dos cabelos e melhora a capacidade secativa das argilas por intensificar a interação do produto com a pele. Seu potencial vasodilatador melhora a permeabilidade dos produtos combinados e impulsiona os resultados terapêuticos de forma notável e agradável. Produto de concepção moderna que vem ganhando destaque no campo das terapias complementares por sua notável distribuição de benefícios e veracidade de resultados. MODO DE USO Promova associação com argilas em proporções que alcancem uma viscosidade agradável e que favoreça o processo de aplicação. Produto passível de ionização para procedimentos estéticos e terapêuticos que possam contribuir para a melhoria das condições gerais da pele, couro cabeludo e cabelo. Produto fortalecedor da estrutura capilar. Pode ser usado como solução reconstrutora, antes e depois de procedimentos químicos. Use um borrifador como instrumento de aplicação. INFORMAÇÕES IMPORTANTES Água nutritiva polarizada para infusões e misturas terapêuticas. Certificado pela ABT - Academia Brasileira de Tricologia. Não testado em animais. Sem corantes artificiais.', 59.31, 59.31, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd5v-lxafntjxstcv78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415568490%2F19819507152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
