INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698923153', 'Areia para Gato Pipicat Classic 4kg', 'Areia para Gato Pipicat Classic A escolha ideal para garantir higiene, praticidade e conforto no dia a dia do seu gato. - Fácil de usar: basta colocar uma camada de aproximadamente 5 cm de altura na caixa de areia. - Forma torrões firmes: a urina se concentra em pequenos torrões, facilitando a remoção. - Mais economia: retire apenas os torrões formados e aproveite o restante do produto. - Manutenção simples: complete a quantidade retirada e faça a troca total da caixa a cada 4 semanas* ou conforme a necessidade do seu gato. *Rendimento estimado considerando 1 bandeja para 1 gato em condições normais de saúde.', 21.99, 15.69, NULL, 'Pets > Pet Grooming > Others', 'https://cf.shopee.com.br/file/sg-11134201-824i3-mf1g5fkfx5ak0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248266601%2F23698923153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
