INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254123292', 'Kit 3 Sérum Efeito Secativo 30ml Dermachem', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: COMBO 3 x Sérum Facial (Verde) Pele Oleosa 30Ml - - - - - - - - - - DESCRIÇÃO: O Sérum efeito secativo DERMACHEM Laboratory foi desenvolvido com um blend de ácidos SECATIVOS como o ácido salicílico, ácido glicólico e o ácido láctico, que agem juntamente com o íon de enxofre e o ácido hialurônico, na redução da inflamação acneica, secagem das espinhas e diminuição do seu reaparecimento. O resultado é uma pele limpa e renovada! - - - - - MODO DE USO: ROTINA DIURNA - Pela manhã, limpe bem o rosto com o sabonete de limpeza da Linha DERMACHEM. Aplique de 1-2 gotas do Sérum no rosto, pescoço e colo. Faça uma massagem com movimentos circulares para melhor absorção do produto. Aplique o protetor solar de sua preferência. Ao longo do dia repita esse cuidado. ROTINA NOTURNA -Á noite, com a pele limpa e seca aplique novamente o Sérum. Utilize o Sérum 3x ao dia. Não enxaguar. - - - - - - - - - - Enviamos o seu pedido o quanto antes possível! Agradecemos a preferência.', 46.8, 36.9, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/br-11134207-820lb-moprfmqtwava9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F58254123292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
