INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594347014', 'Super Flush Corretivo Koube 450 mL – Manutenção Eficiente do Motor', 'PRODUTO NOVO Deseja restaurar a performance do seu motor removendo borras e incrustações? Características do Produto – Marca: Koube – Volume: 450 mL – Tipo de Produto: Aditivo de Limpeza para Motor – Uso Recomendado: Sistemas de lubrificação automotivos – Composição: Surfactantes aniônicos e catiônicos, agentes dispersantes, nafta destilada leve e hidrocarbonetos alifáticos – Cor: Castanho – Origem: Brasil Por que escolher este produto – Dissolve e remove borras, graxas, vernizes e incrustações avançadas – Restaura a eficiência do sistema de lubrificação – Compatível com motores flex e diesel – Fácil aplicação, sem necessidade de remoção de componentes Dicas de Uso – Com o motor frio, verifique o nível de óleo, que deve estar no máximo – Adicione todo o conteúdo da embalagem ao motor – Ligue o motor e deixe funcionar por 50 a 60 minutos a 2000 rpm ou em trânsito, com a luz do óleo apagada – Desligue o motor e drene todo o óleo imediatamente – Complete com óleo novo até o nível máximo indicado pelo fabricante – Funcione o veículo por 10 minutos, desligue e drene o óleo novamente – Remova o cárter e a tampa de válvula para uma limpeza completa com água aquecida e pulverizador pneumático, removendo o defletor se presente Perguntas Frequentes – Este aditivo é adequado para todos os tipos de motores? Sim, é compatível com motores flex e diesel. – Posso utilizar este produto preventivamente? Sim, pode ser usado em manutenção preventiva ou após contaminação por óleo. – Há risco de entupimento no sistema de lubrificação? Não, o produto não prejudica o funcionamento dos componentes do sistema. Super Flush Corretivo Koube 450 mL — mantém o sistema de lubrificação limpo e eficiente.', 105.9, 93.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdevux0vuuhdf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349667948%2F22594347014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14537941525', 'Esferas Plásticas Rossi Para Airsoft Bbs 0.20g 6mm 1.000un', 'Esferas Plásticas Rossi Para Airsoft Bbs 0.20g 6mm 1.000un Essas são Esferas plásticas mais conhecidas como BBS; Munição compatível com Rifles, Pistolas, Revólveres, Snipers, Shotguns, Gbb''s e Aeg''s que possuam calibre 6mm e que sejam categorizadas como Airsoft. Produzidas pela ROSSI, uma empresa brasileira que tem mais de 130 anos de história e não a toa é reconhecida e respeitada como uma das mais importantes do segmento de Tiro Esportivo, oferecendo produtos de qualidade indiscutível. Passadas por um rigoroso sistema de qualidade para proporcionar aos atiradores o máximo de desempenho, elas são bolinhas sem emendas ou rebarbas garantindo uma maior vida útil ao equipamento. Na ''mamadeira'' contém 1000 unidades de bbs com gramatura de 0.20g. Características: - Marca: Rossi - Calibre: 6mm - Material: Plástico - Formato: Esférico - Coloração: Brancas - Gramatura: 0.20g - Quantidade: 1000 unidades - Dimensões da embalagem: 11,5cm x 6,4cm - Peso bruto total: 229 gramas Itens Inclusos: - 1x Esferas Plásticas Rossi Para Airsoft Bbs 0.20g 6mm 1.000un - 1x Nota Fiscal', 46.46, 46.46, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/69c25ee5350f71af4465e617b55ae137', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F618731843%2F14537941525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50255004946', 'Pinça para Churrasco e Frios Arienzo 13cm Inox Brinox - 1661/000', 'Equipe a sua cozinha com os utensílios corretos e transforme o ato de cozinhar em um prazer. A linha Arienzo desenvolveu uma série de utensílios indispensáveis aos cozinheiros de mãos cheias. A pinça para churrasco e frios é multiuso. A forma do seu bojo lhe permite servir alimentos fatiados, como o queijo para o café da tarde, ou em pedaços como a carne assada para o almoço de domingo. A peça é inteiramente produzida em aço inoxidável, um material que reúne funcionalidade e elegância: resistente e fácil de limpar, possui um sofisticado acabamento em alto brilho e pode ir à lava-louças. A pinça para churrasco e frios da linha Arienzo tem 13cm de comprimento total. Informações sobre o Produto: - Material: Aço Inox Características: - Marca:Brinox - Modelo:1661/000 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Pinça p/ Churrasco', 19.0, 12.73, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/sg-11134201-8260a-mjr0q83o8g7a6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F50255004946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599031564', 'Darker 500ml Pneu Pretinho Revitalizador Borracha Vintex', '🚗 Bem-vindo à sua loja de soluções automotivas seguras e confiáveis! Aqui, cada detalhe é pensado para cuidar do que move você: 👨‍👩‍👧‍👦 sua família, 🛡️ sua segurança e 🛣️ seus melhores momentos na estrada. 🛠️ Darker 500ML Vintex - Revitalizador de Borracha 🖤 DARKER foi desenvolvido para renovar e dar brilho em pneus e borrachas em geral, especialmente em caminhões. ✨ O produto forma um filme preto, sólido, semi-flexível e de alta resistência, promovendo durabilidade prolongada. 🔎 Referências Compatíveis: 📌 35311, 2050436 📋 Informações do Produto: 🏷️ Marca: Vintex 🧴 Tipo: Remove e dá brilho 🔧 Condição: Novo ⚖️ Volume: 500ml 👁️ Aparência: Líquido ✋ Aplicação: Manual 🛡️ Garantia: 90 dias 💬 Antes de realizar seu pedido, esclareça suas dúvidas. ✅ APLICAÇÕES: 🛞 Renovação e revitalização de pneus → Restaura o aspecto visual de pneus envelhecidos, devolvendo o preto intenso e aparência de “pneu novo”. ⚫ Brilho em superfícies de borracha → Aplicável em molduras, vãos, borrachas de portas e outros componentes. 🌞 Proteção e durabilidade → Forma um filme resistente contra ressecamento, rachaduras e exposição solar. 🚚 Acabamento estético em veículos utilitários e caminhões → Ideal para veículos pesados que sofrem maior desgaste visual e físico. 🌟 Principais Características: 🧽 Protege, conserva e dá brilho 🖤 Deixa os pneus com aspecto de novo 🔧 Ideal para estética automotiva 💪 Produto de alta performance e durabilidade 🧑‍🔧 Modo de Usar: 🧼 Limpe bem e seque a superfície (pneu ou borracha). 🔄 Agite o frasco antes de aplicar. 🖌️ Aplique de forma uniforme com pincel ou trincha. ⏱️ Aguarde secar por cerca de 30 minutos. ✨ Para mais brilho, aplique uma segunda demão após a secagem inicial. 🛒 Onde Comprar com Segurança e Garantia? Adquira agora o Darker 500ml da Vintex em uma de nossas Lojas Oficiais: 🏬 Camillo Parts 🏬 Genuine Automotive 🏬 Edumac Parts ✅ Produto original, com garantia e suporte especializado que você merece! ⚠️ Aviso Legal: 🚫 É proibido o uso, cópia ou alteração de nossas fotos, imagens e conteúdo presentes nos anúncios. 📜 Conforme a Lei 9.610/98, qualquer violação será tratada legalmente, pois possuímos direitos autorais sobre este material.', 48.63, 33.56, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-82592-mfygpdgjvxu75a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349667948%2F23599031564', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41267334899', 'Bicicleta Infantil Aro 20" Apollo Preto e Laranja Nathor - 101200160015', 'Indicada para crianças a partir de 7 anos ou com altura entre 1,20m e 1,50m. Conforto, segurança e muitas aventuras! As bicicletas aro 20″ Nathor garantem máxima segurança e conforto a cada pedalada! Possuem regulagem de ângulo do guidão (se adapta à postura do ciclista), movimento central avançado (mais facilidade para pedalar) e freios v-brake dianteiro e traseiro. Conta também com pezinho de descanso, protetor de corrente, pneus com câmara, quadro em aço carbono e aro em alumínio, diferenciais que levam muito mais conforto e segurança! Movimento central avançado Esta tecnologia permite que o ciclista fique de forma confortável e ergonômica no selim com a distância ideal ao pedal. Esta posição ajuda a reduzir a fadiga nas costas, pescoço, ombros, braços e pulsos, além de proporcionar maior visão panorâmica. Mesa de direção com regulagem de ângulo A aro 20″ possui guidão ajustável, conforme a criança vai crescendo, você pode regular o guidão permitindo que a se mantenha adequada. Cor da maçaneta do freio A aro 20” possui a maçaneta da cor amarela, para direcionar o acionamento do freio traseiro de forma intuitiva e garantir ainda mais segurança da criança.Informações Técnicas: Tamanho da roda: 20" Altura máxima recomendada: 120-150cm Peso máximo recomendado: Até 70kg Peso do produto: 10.6 Kg Peso com a embalagem: 12.2 Kg Cubagem: 0.14 m³ Dimensões da embalagem (CxAxL): 55 x 23 x 112 CM Características: - Marca:Nathor - Modelo:101200160015 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Bicicleta Aro 20" Apollo', 910.25, 819.22, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-824i3-me7arlmenxmtbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F41267334899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694531957', 'Notebook ASUS Vivobook 15 X1504VA Intel Core i5 1334U 4GB Ram 256Gb SSD Linux Tela 15,6" LED NJ1726', 'Com visual moderno, componentes atualizados e conforto superior, o ASUS Vivobook 15 é a escolha ideal para quem precisa de um notebook confiável para trabalhar, estudar e realizar tarefas do dia a dia. Este computador não só combina alto desempenho, experiência audiovisual imersiva e construção robusta, como também protege sua saúde com tecnologias exclusivas da ASUS. DESEMPENHO PARA IR ALÉM Part Number 90NB10J2-M026P0 SKU ASUSX1504VA-NJ1726 EAN Code7908737300734 Código de homologação Anatel00595-18-04423 ProcessadorIntel Core i5 1334U 1.3 GHz, 12 MB Cache Memória RAM4 GB (4 GB OnBoard + 0 GB OffBoard) Armazenamento256 GB SSD Tela15.6'''' LED-backlit Anti-Glare Resolução da Tela1920x1080 Placa de VídeoIntel UHD Graphics Garantia12 meses Tela Sensível ao ToqueNão Clock de Memória3200 MHz Wi-Fi 5(802.11ac) (Dual band) 1*1 + Bluetooth® 5.1 Placa de vídeoIntegrada Teclado retro iluminadoNão Câmera FrontalHD Bluetooth 5,1 Áudio SonicMaster Alto-falantes embutidos Microfone embutido Saídas 1x USB 2.0 Tipo-A 1x USB 3.2 Ger 1 Tipo-C 2x USB 3.2 Ger 1 Tipo-A 1x HDMI 1.4 1x Conector de áudio combo 3.5mm 1x DC-in Adaptador de Energia45 W Bateria3 Células / 3780 mAh Sistema OperacionalKeepOS Características Especificações Militares US MIL-STD 810H Tampa de privacidade para a Webcam Certificação TÜV Rheinland Energy star 8.0 EPEAT Silver REACH RoHS Peso do Produto1.7 Kg Dimensões35.97 cm X 23.25 cm X 1.79 cm', 3299.0, 3299.0, NULL, 'Computers & Accessories > Laptops', 'https://cf.shopee.com.br/file/sg-11134201-8259w-mfu4j73y4xe72d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1644527155%2F23694531957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29690519889', 'Boneco Funko Pop! Animation Naruto Shippuden (Escolha o Personagem)', 'Leve os maiores ninjas de Konoha (e além) direto para a sua estante com os Bonecos Funko Pop! Naruto Shippuden! Cada figura traz detalhes fiéis ao anime e representa momentos marcantes da jornada de Naruto e seus aliados – ou rivais. Com acabamento em vinil de alta qualidade e entre 10 e 15 cm de altura, essas miniaturas são ideais para colecionadores e fãs apaixonados pela saga ninja mais famosa do mundo! Personagens disponíveis: Jiraiya: O lendário Sannin em sua clássica pose de batalha. Naruto Uzumaki com Shuriken (1843): Em ação com chance de versão Chase metálica! Neji Hyuga Plus: Em versão ampliada com Byakugan ativado. Gaara: Exclusivo da San Diego Comic Con, com seu jutsu de areia. Sasuke com Primeiro Susano’o: O clã Uchiha representado com poder total! Naruto Clássico (71): O herói da Folha Oculta em sua forma original. Informações Gerais: Material: Vinil Altura aproximada: 10 a 15 cm Origem: Importado Certificação: INMETRO Idade recomendada: A partir de 3 anos Marca: Candide Dimensões da embalagem do Funko: 16cm (A) x 11,5cm (L) x 9cm (C) - Conteúdo da embalagem: 1 boneco Funko Pop! Naruto Shippuden (Escolha o personagem) Escolha seu personagem favorito no momento da compra e reviva as batalhas épicas de Naruto Shippuden na sua coleção!', 158.83, 158.83, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824iy-mdx707g0od1g84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F29690519889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209113002', 'Torneira Para Banheiro Misturador Monocomando Baixa Araguaia Pingoo - Prata Escovado', 'O Misturador Monocomando Araguaia Baixa é perfeito especialmente para você que mora em regiões onde o inverno é mais rigoroso. Além do seu design slim e moderno, a Linha oferece também atributos técnicos indispensáveis para a sua utilização. O cartucho monocomando permite a precisa regulagem da vazão e da temperatura da água, feita em apenas um comando. Ela garante funcionamento perfeito em baixa e alta pressão. Já o arejador, além de garantir economia de água, evita respingos e proporciona conforto para as mãos. O volante em alavanca proporciona maior leveza na abertura e no fechamento. Especificações: Marca: Pingoo Dimensões: Verificar nas Imagens do anúncio. Material Predominante: Latão Acabamento: Escovado Pressão: 5 a 40 mca Misturador: Sim Água quente/Fria *(Caso queira usar apenas com agua fria, basta utilizar um conector T) Sistema: Monocomando Bica Giratória: Não Arejador: Sim Spray: Jato Cartucho Cerâmico: Sim Extensível: Não Entrada Filtro: Não Instalação: Bancada Indicação: Banheiro Furo da Bancada: 3,5 cm Conexão de entrada: 1/2'' Itens inclusos: Par de flexíveis de aço trançado de 50 cm Anéis de Vedação Sistema de fixação', 217.9, 217.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-81zvb-mn634r2vygp0cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1758065666%2F58209113002', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40932269615', 'Livro Os Irmãos Karamázov - Clássico Adaptado de Fiódor Dostoiévsk', 'ma das maiores obras da literatura mundial, agora em uma edição adaptada que preserva a força narrativa e os grandes temas de Fiódor Dostoiévski. Considerado por muitos críticos e escritores a obra-prima do autor, Os Irmãos Karamázov foi seu último romance, publicado em 1880, poucos meses antes de sua morte, e permanece como um dos maiores clássicos da literatura universal. A família Karamázov, marcada por conflitos, excessos e uma herança emocional devastadora, é o ponto central desta narrativa. Fiódor Karamázov, pai negligente e devasso, mantém ao seu redor três filhos profundamente diferentes entre si: Dmítri, impulsivo e dominado pelas paixões; Ivan, racional e atormentado por dúvidas; e Aliôcha, sensível e movido por uma fé silenciosa. Quando um crime abala essa família já fragmentada, antigas tensões vêm à tona, revelando ressentimentos, disputas e segredos que nunca foram resolvidos. À medida que a investigação avança, cada um dos irmãos é confrontado não apenas com a verdade dos fatos, mas também com questões que ultrapassam qualquer julgamento: Culpa, liberdade, fé e responsabilidade. Mais do que um romance sobre um crime, esta é uma obra que convida o leitor a refletir sobre a natureza humana, as relações familiares, os limites da justiça, os conflitos entre razão e espiritualidade e o peso das escolhas individuais. Nesta adaptação cuidadosa, a complexidade do romance original ganha uma forma mais acessível, sem perder a profundidade que tornou a obra um marco da literatura. O texto preserva a essência da narrativa e dos grandes dilemas criados por Dostoiévski, tornando este clássico uma excelente porta de entrada para estudantes, novos leitores e todos aqueles que desejam conhecer uma das mais influentes obras da literatura mundial. O resultado é uma leitura envolvente, capaz de despertar reflexões que atravessam gerações e permanecem atuais até hoje. Editora: Principis Edição: 1, 2026 Autor: Fiódor Dostoiévski Idioma: Português Páginas: 288 Dimensões: L 15.50 x A 22.60 x E 1.50 ISBN: 9786550974879 Coleção: Clássicos da literatura mundial Linha Editorial: Principis - Clássicos da literatura Faixa Etária: + 16 anos Assuntos (tags): Rússia, Literatura Russa, Clássicos, Família, Irmãos, Moralidade, Culpa, Responsabilidade, Mistério, Crime, Julgamento, Assassinato, Conflitos, Fiódor Dostoiévski, Dostoiévski, Os Irmãos Karamázov, Clássico russo, Romance clássico, Conflitos familiares, Pai e filhos BISAC: Ficção / Ficção / Clássicos Linha de Produto: Principis Encadernação: Brochura Acabamento: Laminação fosca Material: Papel', 34.9, 34.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-825b0-mq7ykxd28yrled', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F40932269615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397786421', 'Livro Literatura infantil A árvore do caju', 'As páginas deste livro repetem o saber ancestral igualzinho a contadora de histórias ouviu contar a sua avó. Foi assim...Naquele mesmo lugar, no tempo distante, uma anciã balançou sua maraca, entoou seus cânticos sagrados à sombra de uma grande árvore. Com o mesmo encantamento das noites de céu estrelado, a nova semente brotou e cresceu forte, fez caule, folhas e frutos. Até hoje, o povo Tabajara em grande roda de toré dança para manter viva a tradição. Escrito por Auritha Tabajara e ilustrado por Rodrigo Mafra._x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2024_x000D_ Autor: Auritha Tabajara_x000D_ Ilustrador: Rodrigo Mafra_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.30_x000D_ ISBN: 9786553843707_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na Escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Povos originários, Cultura indígena, Natureza, Memória afetiva, Indígena_x000D_ BISAC: Literatura Infantil / Povos & Lugares_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdwh-lz9c23ixz6088a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F21397786421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599179460', 'Livro O curioso caso de Benjamin Button', 'No ano de 1860, em Baltimore, nos Estados Unidos, nasce Benjamin Button, um indivíduo com a estranha condição de envelhecer ao contrário. Na fase em que deveria ser uma criança, Benjamin tem a aparência e o humor de um senhor de mais de setenta anos de idade, que prefere fumar charutos, ler enciclopédias e conversar com o próprio avô sobre banalidades do que tomar parte em atividades infantis, das quais seu pai, Roger, tenta obrigá-lo a gostar. Embora a expectativa de todos seja a de que Benjamin não vá sobreviver às condições precárias de sua saúde, conforme os anos avançam, ele fica cada vez mais jovem, forte e ávido por desbravar o mundo da forma peculiar que lhe foi proporcionada. Com reflexões sobre vida e morte, família e afeto, e a fragilidade da condição humana como um todo, o curioso caso de Benjamin Button se tornou uma das histórias mais clássicas do consagrado autor norte-americano F. Scott Fitzgerald._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2023_x000D_ Autor: F. Scott Fitzgerald_x000D_ Ilustrador: Venez Caitano_x000D_ Idioma: Português_x000D_ Páginas: 80_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.60_x000D_ ISBN: 9786550970932_x000D_ Coleção: Clássicos da literatura mundial_x000D_ Linha Editorial: Principis - Clássicos da literatura_x000D_ Faixa Etária: + 14 anos_x000D_ Assuntos (tags): Família, Morte, Afeto, Reflexão, Sentimentos, Romance (gênero literário), Literatura Americana_x000D_ BISAC: Ficção / Clássicos_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Adult''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbl4-lqcfzt4vsmui99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F21599179460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
