INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393479114', 'Bomba Combustível Range Rover Evoque 2.0 Turbo 2012 A 2018', 'ZAMPERLINI DISTRIBUIDORA DE AUTOPEÇAS E AUTO ELÉTRICA Preço bom, atendimento rápido e personalizado é o que você encontra em nossa loja de autopeças. Desde 1989 no mercado brasileiro, trabalhamos com uma equipe de funcionários especializados, para garantir uma excelente experiência de compra a cada consumidor. Além das peças automotivas, temos um autocenter completo para uma melhor expediência aos nossos clientes. PRODUTO: BOMBA COMBUSTÍVEL RANGE ROVER EVOQUE 2.0 TURBO 2012 A 2018 APLICAÇÃO • Land Rover Evoque 2.0 16v Turbo 2012 Até 2018 ------------------------------------------------------------------------------------- lINFORMAÇÕES ADICIONAIS • Codigo Do Produto: 10482 - 43067 • Bomba Combustível Range Rover Evoque 2.0 Turbo 2012 A 2018 • Vazão (L/H) 100 • Volts 12v • Pressão (Bar) 4,0 • Amperes 6,0 • Combustível Gasolina • Tipo Interna • Obs Não Acompanha Flange E Sensor De Nivel • Fabricante: Euro • Produto Novo ------------------------------------------------------------------------------------ REFERENCIAS ORIGINAL CJ329H307AB LR026192 LR04427 LR057235 ------------------------------------------------------------------------------------ ITENS INCLUSOS 01 - Bomba Combustível Range Rover Evoque 2.0 Turbo 2012 A 2018 ZAMPERLINI DISTRIBUIDORA DE AUTOPEÇAS E AUTO ELÉTRICA', 555.76, 555.76, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1gzz0eess94c5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332531144%2F23393479114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
