INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18711719271', 'Amplificador Bluetooth Som Ambiente + 2 Caixas Teto Embutir', 'Mais de 15 anos de experiencia no mercado com os melhores produtos e o melhor atendimento! Amplificador Bluetooth + 2 Caixas de teto Embutir Arandela 70W Compativel com ALEXA e GOOGLE ASSISTENTE Solucao moderna e eficiente para a reproducao de musica sem fio, o amplificador Bluetooth para som ambiente foi desenvolvido para ficar oculto na caixa de som. Com ele, voce reduz a quantidade de fios da sua instalacao e pode se conectar ao smartphone de forma simples, pratica e segura. Depois, e so se divertir ouvindo as musicas armazenadas no seu celular ou simplesmente reproduzindo suas playlists favoritas em qualquer servico de audio. O AMPLIFICADOR VAI INSTALADO NA ARANDELA, PRONTO PARA USAR Conta com uma arandela ativa de 70W Rms e uma passiva, podendo ser instalada em forro de drywall, gesso, madeira , pvc, possui garras para fixacao ajustaveis. A arandela ativa e ligada a energia por fonte bivolt e e controlada pelo Bluetooth que estiver conectado a ela A arandela passiva e ligada na ativa por meio de fio paralelo (nao incluso), a passiva nao necessita ser ligada a energia Caracteristicas tecnicas da Arandela ativa: Alto Falante: 6 polegadas Tweeter coaxial com piezo duplo Potencia Nominal: 70W Rms Faixa de Frequencia: 100 Hz - 20kHz Impedancia: 8 Ohms Alto falante mid bass com borda de borracha Dimensoes: 6x19,5x19,5 cm Cor: Branca Caracteristicas tecnicas da Arandela passiva: Alto Falante: 6 polegadas Potencia Nominal: 70W Rms Faixa de Frequencia: 100 - 20kHz Impedancia: 8 Ohms Dimensoes: 6x19,5x19,5 cm Cor: Branca Conteudo da embalagem: 1 Arandelas Redonda Ativa 1 Fonte Bivolt 110v/220v 1 Arandela redonda branca passiva 2 Kits de suporte para fixacao', 589.99, 589.99, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/br-11134207-7r98q-lm6ffg5rqsl3e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F625420381%2F18711719271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997494089', 'Kit Desodorante Aerosol Nivea Dry Impact For Men 200ml - 4 unidades', 'O Desodorante Aerosol Nivea Dry Impact For Men Possui em sua composição dobro de agentes minerais causando assim um efeito eficaz contra maus odores e transpiração. Modo de uso: Usar somente nas axilas. Aplique nas axilas á uma distancia de 15cm. Caso ocorra irritação e/ou prurido no local da aplicação, suspender o uso e procurar orientação médica. Sobre a marca: Ao longo dos anos a Nívea veio desenvolvendo produtos específicos para limpeza, hidratação, proteção e preservação dos nutrientes essenciais para uma pele sempre saudável e bem cuidada. O objetivo da Nívea sempre foi o mesmo: ajudar pessoas de todas as idades a aproveitarem o sol, onde e quando quisessem.', 102.55, 79.16, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-820ng-mnyc4z565dz75a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F21997494089', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898969323', 'Kit Desodorante Aerosol Monange Proteção Seca 90g - 3 unidades', 'O Desodorante Monange Proteção Seca é antitranspirante de alta performance e garante proteção 48 horas. Possui uma fragrância floral suave com perfeito equilíbrio reconfortante do talco, deixando a pele com sensação prolongada de banho. Com rápida absorção, o desodorante proporciona toque seco, pele macia e nutre até a 2ª camada da pele*. A linha de desodorantes Monange não contem álcool etílico em sua formulação e é dermatologicamente testada. *A segunda camada da pele é a subcórnea da epiderme e os resultados foram obtidos por meio de prova instrumental', 36.41, 36.41, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-824hk-mpi22k2najgr8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F19898969323', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
