INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206662258', 'Tênis Cano Médio Infantil Menina Branco Preto e RosaPampili', 'Esse tênis cano médio é puro carinho para acompanhar o dia a dia da menina. A combinação de cores clássicas ganham um toque delicado, criando um visual super moderninho para os primeiros passos .Pensado para a rotina das meninas, esse tênis infantil traz um calce fácil com fecho duplo de contato. O cano médio proporciona mais estabilidade e suporte para os pés, enquanto o colarinho comfy, o forro absorvente e a palmilha anatômica cuidam do conforto ao longo do dia. O solado antiderrapante completa a experiência, ajudando a deixar cada passinho mais seguro e inclusivo com a descrição em braile para identificação. Aposte! Combine com conjuntos, jardineiras ou vestidos confortáveis para criar looks cheios de estilo e liberdade para a menina brincar à vontade.', 199.9, 199.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820lq-mlnt7wcbrm6d75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F58206662258', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
