INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8144461409', 'Kit Borrachas De Vedação Celta 2000 2001 2002 2003 2004 4 P', 'Temos o prazer de trazer mais um produto de excelente qualidade, sucesso de vendas com preço justo! Kit Borrachas Vedação de 4 Portas + porta malas. Essa é a borracha que faz o contorno da porta, vai fixada na carroceria, evitando que entre água, poeira para dentro do veiculo, diminuindo até barulhos internos e amortecendo o fechamento da porta Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e poeiras. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Essas borrachas protetoras são conhecidas como guarnição, e, além de serem instaladas no teto e nas portas, também podem ser encontradas nas áreas de contato entre capô, no porta-malas e nos vidros, evitando o contato direto da tampa com a carroceria. Essa é a borracha que faz o contorno da porta, vai fixada na carroceria, evitando que entre água, poeira para dentro do veiculo, diminuindo até barulhos internos e amortecendo o fechamento da porta. Compatível com Compatível com Celta 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 - Em todas as versões fabricadas. Acabamento com aba. Para outros carros e modelos, entre em contato conosco. Borrachas na cor preta. Produto de excelente qualidade 100% garantido. Fixado por encaixe Garantia de 3 meses', 342.9, 342.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/b0116af9ceb10f4ac9226dec8f012f5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F8144461409', NULL, NULL