INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26065246140', 'Relógio Controle de Ponto Digital LCD Com Biometria RE1033 Knup', 'Este controlador de acesso digital foi projetado para oferecer segurança avançada e controle eficiente em ambientes corporativos e residenciais. Com capacidade para gerenciar até 1.000 usuários, ele permite múltiplos métodos de autenticação, como biometria, cartão, senha ou uma combinação dessas opções. Isso proporciona flexibilidade e segurança adicionais para o controle de acesso. Principais Características: - Display colorido LCD: Interface visual clara e de fácil navegação. - Armazenamento de registros: Capacidade de armazenar até 100.000 registros de presença, permitindo o controle e monitoramento detalhado de entradas e saídas. - Métodos de identificação: Suporte para biometria, cartão e senha, garantindo múltiplas opções de segurança. - Controle de abertura de portas: Facilita a integração com sistemas de abertura de portas eletrônicas. - Relatório de presença: Gera relatórios detalhados sobre as entradas dos usuários. - Tensão de operação: Funciona com uma tensão de 9 a 12Vdc. Conteúdo: 1x Relógio Controle de Ponto RE1033', 341.8, 247.94, NULL, 'Computers & Accessories > Office Equipment > Absence Machines', 'https://cf.shopee.com.br/file/sg-11134201-82615-mk3wu69al7nq02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F26065246140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
