INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57952469094', 'Tênis Reserva Yankee Stratus Preto e Verde - Masculino', 'Estilo urbano elevado ao futuro com conforto e atitude! Tênis Reserva Yankee Stratus Preto e Verde - Masculino Ficha Técnica: Marca: Reserva Cor: Preto e verde com detalhes metálicos Gênero: Masculino Indicação: Uso em eventos sociais e streetwear Material: Mix de couro, material sintético e têxtil Fechamento: Cadarço Solado: Tratorado com design robusto Lingueta: Acolchoada com detalhe Yankee Stratus Detalhes: Logo Reserva nas laterias, Recortes vazados, painéis metálicos, acabamento brilhante e design futurista O Yankee Stratus é um sneaker que transcende tendências. Porque investir: Com recortes arrojados e uma estética que une o retrô dos anos 2000 ao visual futurista, ele traz profundidade ao visual urbano. A mistura de materiais e texturas entrega personalidade de sobra, enquanto o solado tratorado garante presença em qualquer ocasião. Tenha estilo, conforto e atitude - tudo no mesmo par. Conteúdo da embalagem: 1 par de Tênis Reserva Yankee Stratus Preto e Verde – Masculino', 1249.99, 780.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8226b-mhs0bmn05uypbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F57952469094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
