INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12437125761', 'Estante plástica com 4 prateleiras PTR08 - São Bernando', 'Produto: Estante plástica com 4 prateleiras - PTR08 Marca: São Bernardo Cor: Preto Descrição: A Estante plástica com 4 prateleiras PTR08 da São Bernardo é a solução ideal para quem busca aliar praticidade e design moderno no mesmo produto. Essa estante se encaixa perfeitamente em qualquer tipo de ambiente, seja ele quarto, dispensa, lavanderia, garagem, escritório, cozinha, sala ou banheiro. Composta por quatro prateleiras espaçosas, a Estante PTR08 proporciona uma excelente capacidade de armazenamento, facilitando a organização de diversos tipos de objetos, de livros e utensílios domésticos a ferramentas e materiais de escritório. Além do seu aspecto funcional, esta estante conta com um design elegante que adiciona um toque de sofisticação ao seu lar. Características: - Fácil montagem: Organize seus pertences em minutos; - 4 prateleiras: Otimize espaço e diga adeus à bagunça; - Resistente e durável: Material plástico de alta qualidade; - Multiuso: Perfeita para qualquer ambiente. Especificações: Material: plástico. Medidas montada (LxAxP): 70 x 139 x 38 cm Dimensões (C x L x A): 20.00 x 37.00 x 68.00 centímetros Peso: 4.00 Kg', 140.89, 140.89, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-8261y-mlnl424xzwg84f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F12437125761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40180865939', 'Combo Duo Pack Sucrilhos Original 240g + Power Pops 200g Kellogg''s 2 Uni', 'O Novo Duo Pack Sucrilhos® Original 240 g - Power® Pops® 200 g reúne dois cereais campeões em uma única embalagem, agora com 50g grátis. De um lado, Sucrilhos® Original traz os tradicionais flocos de milho super crocantes e o sabor clássico e açucarado. Do outro, Power® Pops® chega como o grande destaque do pack, com nova fórmula, agora com mais sabor de chocolate, bolinhas maiores e deliciosamente crocantes — uma evolução que torna a experiência única e deliciosa. O Duo Pack é perfeito para quem já ama Sucrilhos® Original e quer aproveitar a oportunidade de experimentar o novo Power® Pops®, agora muito mais saboroso e surpreendente. Ideal para consumir com leite, frutas ou iogurte, ele permite diferentes combinações no café da manhã ou no lanche da tarde, oferecendo uma experiência superior de sabor e textura em cada colherada.', 41.99, 41.99, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Cereal, Granola & Oats', 'https://cf.shopee.com.br/file/sg-11134201-824if-mpnnjvpfqjgvce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638330698%2F40180865939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
