INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203621194', 'Corretivo BT Skinplush - Bruna Tavares', 'O BT SKINPLUSH é um corretivo versátil de textura soft mousse que proporciona cobertura leve a média com acabamento aveludado. Além da performance como maquiagem, a fórmula exclusiva do BT SKINPLUSH é enriquecida por diversos benefícios. Possui um ativo derivado da planta Sambucus Nigra que auxilia na redução das olheiras e bolsas ao redor dos olhos, conta com o poderoso Phytosqualan que atua na hidratação e elasticidade da pele, também possui Extrato de Camomila que promove ação calmante para as olheiras e Vitamina E, poderoso antioxidante que combate o envelhecimento precoce da pele.', 75.9, 75.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mjol5kip4lqb37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687531684%2F58203621194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
