INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9794703378', 'Carcaça Painel Completa Pro Tork CG Titan 1995 1996 1997 1998 1999 Preto', 'A Pro Tork possui uma linha completa de plásticos para que você possa realizar a substituição por um excelente custo x benefício. A linha de painéis contém todos os componentes compatíveis com as principais motos do mercado brasileiro, fabricados nos moldes do original. Especificações: - Fabricada em termoplástico de alta resistência; - Resistente aos raios Ultra Violeta; - Design personalizado e mais resistente que os plásticos originais; - Mesmo molde do modelo original, não necessita adaptações; - ABS 100% virgem Aplicação: - CG Titan 125 1995; - CG Titan 125 1996; - CG Titan 125 1997; - CG Titan 125 1998; - CG Titan 125 1999. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada. A Sportbay não se responsabiliza pela má instalação do produto. Sportbay - Seu Esporte, Nossa Paixão.', 84.11, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lhghbhzrhyz245', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F9794703378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
