INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694273631', 'Brinco Solitário Meia Pérola Pequeno Delicado Lindo Clássico 525291', 'BRINCO ROMMANEL Folheado a Ouro 18k, formado por meia pérola de 8 mm com base e contorno folheado a ouro. TAMANHO: 1,30 cm - Nome: Brinco Rommanel 525291 - Gênero: Adulto - Indicado Para: mulheres modernas que apreciam peças clássicas - Material: Folheado a Ouro 18k, 22k e 24k QUALIDADES: - Joia antialérgica - Não provoca coceira ou vermelhidão na pele - Não escurece - Mantém a cor e o brilho - Alta durabilidade - Adequado para pessoas com ácido úrico - Produtos Rommanel são livres de níquel e chumbo - Segurança no uso FOLHEAGEM A OURO: - Joias em ouro amarelo e ouro branco - Camada de ouro mais espessa - 3 processos de folheagem a ouro 18k, 22k e 24k - Visual semelhante a joias de ouro maciço - Maior resistência comparado a outras semijoias SOBRE A ROMMANEL: - Acabamento artesanal - Mais de 30 anos de mercado - Presença em mais de 40 países - Qualidade, durabilidade e estética única - Embalagem exclusiva Rommanel - Joia embalada com proteção', 128.1, 93.99, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/sg-11134201-7rdxy-mcrq3i0d8dly47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593190827%2F23694273631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297991390', 'Tubo Int. Telescopio (Bengala) Gp7 Xtz 125 03/15', 'O Tubo Interno Telescópio GP7 XTZ 125 03/15 é uma peça essencial para a manutenção da suspensão de motocicletas Yamaha XTZ 125 fabricadas entre 2003 e 2015. Este tubo interno de bengala oferece resistência e durabilidade, proporcionando um melhor desempenho da suspensão dianteira da moto. Características principais: Compatibilidade: Projetado para modelos XTZ 125 de 2003 a 2015.Descrição do Produto: Acompanha bucha guia, sendo uma opção de reposição ideal para quem busca qualidade e precisão na suspensão. Entrega: Está disponível em diversas plataformas de e-commerce e com algumas opções de frete grátis dependendo da localização. Este tubo é ideal para garantir a absorção eficiente de impactos, mantendo a estabilidade e o conforto nas trilhas e no uso diário.', 105.73, 79.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rff6-m3v72llurx5ubc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1117095756%2F21297991390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
