INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798139275', 'Pistola de Pintura Elétrica 650W com Alça HVLP 800ml 3 padrões de pulverização 220V Pró Euro', 'PISTOLA DE PINTURA ELÉTRICA 650W 220V 800ML HVLP PROFISSIONAL PRÓ EURO A Pistola de Pintura Elétrica Pró Euro 650W foi desenvolvida para quem busca praticidade, acabamento uniforme e alta produtividade em pinturas residenciais, prediais e profissionais. Com tecnologia HVLP (High Volume Low Pressure), proporciona melhor aproveitamento da tinta, reduzindo desperdícios e garantindo uma aplicação mais uniforme em diversas superfícies. Possui reservatório de 800ml, vazão de até 500ml/min e três tipos de jato ajustáveis, permitindo maior versatilidade para diferentes tipos de pintura e acabamento. Ideal para aplicação de tintas, vernizes, esmaltes, seladores e outros materiais compatíveis, tanto à base de água quanto solvente. PRINCIPAIS VANTAGENS Motor potente de 650W Tecnologia HVLP para melhor aproveitamento da tinta Reservatório de grande capacidade com 800ml Vazão de até 500ml/min Regulagem da quantidade de material 3 padrões de pulverização Jato Vertical Jato Horizontal Jato Circular Mangueira de 1,5 metro para maior mobilidade Estrutura leve e ergonômica Ideal para trabalhos profissionais e domésticos APLICAÇÕES Pintura de paredes Pintura residencial e predial Portões e grades Estruturas metálicas Móveis de madeira MDF e compensados Vernizes e seladores Pequenos reparos e retoques Marcenarias Oficinas e manutenção em geral ESPECIFICAÇÕES TÉCNICAS Potência: 650W Tensão: 220V Frequência: 60Hz Tecnologia: HVLP Tipo de motor: Escovado Enrolamento: Cobre Reservatório: 800ml Vazão máxima: 500ml/min Viscosidade máxima: 80 DIN-S Comprimento da mangueira: 1,5m Diâmetro do bocal: 42mm Regulagem de fluxo: Sim Material da carcaça: Poliamida 6 (PA6) Cabo elétrico: 1,6m com plugue de 10A PESOS E MEDIDAS Ferramenta: 200 x 125 x 220 mm Peso: 1,47 kg Embalagem: 300 x 230 x 195 mm Peso total: 1,86 kg ITENS INCLUSOS 1 Pistola de Pintura Elétrica Pró Euro 1 Reservatório 800ml 1 Mangueira de 1,5m 1 Alça de Ombro 1 Funil para Teste de Viscosidade 1 Agulha de Limpeza do Bocal Manual de Instruções DIFERENCIAIS Excelente acabamento em pinturas e vernizes Menor desperdício de material Fácil regulagem de vazão Leve e confortável para uso prolongado Ideal para uso profissional e doméstico Aplicação rápida e uniforme GARANTIA: 3 meses de garantia contra defeitos de fabricação.', 249.9, 199.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi314who2upv09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421509827%2F22798139275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
