INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293273760', 'Lavadora de Roupas Wanke Premium Semiautomática 20Kg', 'A Lavadora Comfort 20Kg da Wanke é antiga e tem mais de 100 anos de tradição. Este modelo é fácil de usar para lavar roupas. Oferece várias opções de lavagem para tecidos com diferentes tipos de sujeira. Função para enxaguar as roupas, garantindo que fiquem limpas e sem resíduos de sabão. A Lavadora Comfort 20Kg da Wanke é uma ótima escolha para quem quer eficiência, praticidade e tradição na lavagem de roupas. Características: Botão ergonômico Classificação Inmetro A Cuba maior Dispenser para sabão em pó e amaciante Enxague Mangueira de Entrada de água acoplada ao gabinete Motor WEG Retentor de fiapos Saída de Água por Gravidade Selo Inmetro 000806/2023 Timer com 10 programas de lavagem Timer contínuo de 10 minutos Dimensões: Altura: 94 cm Largura: 58 cm Profundidade: 55 cm Peso: 9,31 kg Garantia do fornecedor de 12 meses. *Imagens meramente ilustrativas, tonalidades podem sofrer alterações. Objetos decorativos das imagens não acompanham o produto.', 659.9, 629.0, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/sg-11134201-7rdy8-m01swofoxfex6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F23293273760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599440592', 'Torrada Lev Magic Toast Integral', 'A Torrada Integral Lev Magic Toast da Marilan é crocante e saborosa, perfeita para um lanche rápido e nutritivo. Cada pacote de 110g contém 6 unidades, ideal para levar na bolsa ou para ter sempre à mão. * Ingredientes: Farinha de trigo integral, amido de milho, creme de milho, farinha de arroz, farinha de trigo enriquecida com ferro e ácido fólico, açúcar, açúcar invertido, farinha de aveia integral, sal, antiumectante carbonato de cálcio, fermento químico bicarbonato de sódio. * Alérgicos: Contém lactose, trigo, aveia. Pode conter cevada, leite, amendoim e soja.', 7.49, 7.49, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-81zua-mmkd9n7xqu4j92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F23599440592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202407439', 'Berço Mini Cama 4 em 1 Americano em MDF Zuri Móveis Peroba', 'Berço Mini Cama Zuri Móveis Peroba, une charme e funcionalidade em um design elegante e atemporal, com pés estilo palito de picolé e acabamento laqueado. Fabricado 100% em MDF com pintura atóxica, oferece segurança, conforto e durabilidade. Possui estrado com altura regulável, bordas arredondadas e acompanha suporte para cortinado, sendo ideal para compor um quarto acolhedor desde os primeiros dias do bebê. Características: Estrutura: 100% MDF Acabamento: Pintura UV Atóxica Espessuras: Estrutura 12mm, Moldura e Barra das Grades 25mm Estrado: Regulável em 2 posições (24,50cm e 53cm) Material do Estrado: MDF e madeira/laminado de madeira Tamanho do Colchão Indicado: 70cm x 130cm (Infantil Americano) Produto Flex: Pode ser montado como Berço, Mini cama, Mini sofá ou Escrivaninha. Certificado INMETRO: Berço Zuri 002874/2025 Suporta até: 40kg Dimensões: Altura: 134,3 cm Largura: 132,4 cm Profundidade: 76 cm Peso: 33,40 kg Garantia do fornecedor de 3 meses', 759.9, 659.9, NULL, 'Mom & Baby > Nursery > Cribs & Cradles & Beds', 'https://cf.shopee.com.br/file/sg-11134201-81zu8-min59h13focoac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F58202407439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
