INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597731045', 'Estante Home Theater Maceió Freijó Off White - Colibri', 'Estante Home Theater Maceió Freijó Off White - Colibri Estante Home Theater Maceió Freijó Off White Colibri Apresentamos a estante home theater da linha Maceió fabricada pela Colibri, é uma peça destaque, versátil para qualquer ambiente, com um design moderno e sofisticado . Possui quatro prateleiras, quatro nichos oferecendo amplo espaço para organização, exposição de objetos decorativos e para acomodar seus aparelhos eletrônicos. A porta basculante equipada com dobradiças pistão a gás garantindo suavidade ao abrir e fechar as portas. Produzida em materias excelentes MDP que garantem qualidade. Acomoda TVs até 65 polegadas, com detalhes ripados, spot em led, trazendo sofisticação e deixando seu ambiente mais aconchegante. Combine funcionalidade e beleza será uma escolha perfeita para deixar seu ambiente ainda mais belo! Garanta já a sua! Características Técnicas: - Produzido em MDP 25/15/12 mm - Pintura na cor Freijó Off White - Acabamento em UV fosco brilho - Possui 4 prateleiras - Possui 1 porta basculante - Dobradiças pistão a gás - Possui 4 nichos - Spot led - Indicados para TVs de até 65 polegadas - Lindo design Dimensões: Altura: 185,3 cm Largura : 200 cm Profundidade: 40,8 cm Informações importantes: *Não realizamos a montagem ou instalação do produto, porém acompanha manual de instruções. *Toda mercadoria segue segurada contra qualquer sinistro, em caso de anormalidade, recuse. *As caixas ou pacotes possuem identificação com o nome, cidade e quantidades de volumes relativos à compra para conferencia do recebedor.', 854.05, 854.05, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rdxt-lzf858j6d2sa4f', 'https://shope.ee/an_redir?origin_link=https%3A%