INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492968660', 'Aditivo de radiador pronto uso 10 litros aditivo de radiador diluído', 'Aditivo pronto uso O aditivo tem um papel extremamente importante no funcionamento do sistema de arrefecimento: ele compõe, da melhor maneira, juntamente com a água, o fluido do radiador. Conforme acontece a circulação da água pelo motor, ela esquenta e pode entrar em ebulição. O que é aditivo pronto para uso? Aditivo para radiador sintético pronto uso é um produto de alta qualidade ,aditivos anticorrosivos protetivos de última geração. Garante total proteção contra cavitação e corrosão em ligas metálicas presentes nos radiadores e componentes.', 39.99, 39.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk2iixrkri0wbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F22492968660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497503370', 'Filtro De Ar Condicionado Honda Hrv honda Fit 2009 em diante honda city 2009 em diante', 'FILTRO DE AR CONDICIONADO HRV FILTRO DE AR CONDICIONADO FIT 2009-->> CES1507 FILTRO DE AR CONDICIONADO CITY 2009-->> Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 19.99, 19.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lv51zn98uykv72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F23497503370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
