INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47550155464', 'Molho De Jabuticaba Com Pimenta 180ML CIA DO TEMPERO', 'Descubra o toque de mestre que faltava em suas refeições com o Molho Especial da Cia do Tempero. Desenvolvido cuidadosamente para realçar o sabor de saladas e alimentos grelhados, este molho possui uma combinação única de ingredientes que resulta em um sabor equilibrado e sofisticado. Sua textura cremosa na medida certa é perfeita para finalizar pratos, garantindo uma experiência culinária elevada com muita praticidade e sabor. ℹ️ Benefícios ✅ Fórmula especial para saladas e grelhados. ✅ Sabor sofisticado que eleva suas receitas. ✅ Textura leve e cremosa, ideal para finalizar pratos. ✅ Traz um toque gourmet para as refeições do dia a dia. ✅ Versátil, podendo ser usado também em sanduíches e wraps. ℹ️ Ficha Técnica Produto: Molho Especial Marca: Cia do Tempero Indicação Principal: Saladas e alimentos grelhados. Sugestão de Uso: Utilize para temperar saladas, regar legumes, frango grelhado, peixes e outros pratos leves. Armazenamento: Conservar em local seco e fresco. Após aberto, manter na geladeira e consumir em até 30 dias.', 23.8, 23.8, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mg8ni4q9jm6kb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F47550155464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
