INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21202554611', 'Limpa Parabrisa Detergente Shampoo Concentrado 100ML Remove Gordura e Sujeiras Impregnadas', 'Limpa Para-brisa Orbi Clean 100ml – Envio Rápido! Mantenha seu para-brisa sempre limpo, garantindo máxima visibilidade e segurança com o Limpa Para-brisa Orbi Clean 100ml. Desenvolvido com fórmula concentrada e de alta performance, o produto remove com facilidade sujeiras, poeira, oleosidade e resíduos que prejudicam a visão ao dirigir. ✅ Limpeza eficiente: Elimina rapidamente sujeiras, manchas e gordura sem agredir o vidro ou as borrachas. ✅ Melhora a visibilidade: Evita ofuscamento, reflexos indesejados e aumenta a segurança, principalmente em dias de chuva ou à noite. ✅ Fácil de usar: Basta adicionar ao reservatório de água do limpador de para-brisa, conforme instruções, e pronto! ✅ Protege e conserva: Ajuda na preservação do sistema de limpeza e do próprio vidro, prevenindo riscos e desgaste. ✅ Produto compacto: Frasco de 100ml ideal para carregar no veículo e ter sempre à mão. Destaques: 🚚 Envio rápido e seguro ✨ Produto original Orbi Química 💧 Uso prático e econômico Garanta já o seu e dirija com mais segurança, conforto e visibilidade!', 12.9, 12.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mahhjbhd24y794', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357432948%2F21202554611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
