INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294460502', 'Sonic Racing CrossWorlds Launch Edition PS5 Midia Fisica', 'SONIC RACING: CROSSWORLDS – LAUNCH EDITION – PS5 Produto 100% original, lacrado e com nota fiscal Pronta entrega – envio imediato Informações do Produto Mídia: Física (disco) Plataforma: PlayStation 5 Versão: Importada Idiomas (áudio): Inglês, Francês e Espanhol Idiomas (texto/legenda): Inglês, Francês, Espanhol e Português Jogadores: • Offline: 1 a 4 jogadores Estado: Novo e lacrado Conteúdo da Embalagem 1 (um) jogo Sonic Racing: CrossWorlds – Launch Edition – PS5 Conteúdo digital para o primeiro lote: • Personagem Sonic Lobo • Adesivo • Carro Garantia 90 dias de garantia Produto original com nota fiscal, garantindo cobertura contra defeitos de fabricação Sobre o Jogo Em Sonic Racing: CrossWorlds, cada corrida é uma verdadeira aventura. Ao atravessar Anéis de Teletransporte, você será lançado em mundos surpreendentes que vão da terra ao mar, do ar ao espaço, onde cada pista apresenta novos desafios e surpresas a cada curva. Corra sozinho ou forme sua equipe dos sonhos. Dispute corridas localmente com amigos ou enfrente jogadores do mundo inteiro em competições online, usando estratégia, habilidade e velocidade para conquistar a vitória. Construa a máquina perfeita personalizando seu veículo de acordo com o seu estilo de corrida. Desbloqueie gadgets especiais, utilize itens estratégicos no momento certo e deixe seus adversários para trás. Em CrossWorlds, velocidade é apenas o começo. O que realmente importa é como você corre e com quem você corre. A linha de chegada está à sua espera. Atenção Imagens meramente ilustrativas. Informações sob responsabilidade do fabricante/fornecedor. Antes de finalizar a compra, utilize o campo de perguntas para esclarecer dúvidas. Nossa equipe está à disposição para ajudar. Gamer Hut Store – sua loja gamer de confiança', 359.89, 359.89, NULL, 'Gaming & Consoles > Video Games > Playstation', 'https://cf.shopee.com.br/file/sg-11134201-824jh-mfeeih37bfuz48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609735381%2F23294460502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250795854', 'Gradius Origins Capa Salamander 3 PS5 Limited Run Midia Fisica', 'GRADIUS ORIGINS CAPA SALAMANDER 3 PS5 **PRODUTO 100% ORIGINAL, LACRADO E COM NOTA FISCAL** **PRONTA ENTREGA - ENVIO IMEDIATO** - Mídia: Física (disco ou cartucho no caso se for Nintendo); - Console: Compatível com PS5; - Versão: Importado; - Legenda ou Texto: Alemão, Espanhol, Francês, Inglês, Japonês, Português; - Jogadores: 1-2; CONTEÚDO DA EMBALAGEM: 1 (um) Jogo GRADIUS ORIGINS CAPA SALAMANDER 3 PS5; IMAGENS MERAMENTE ILUSTRATIVAS Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor GARANTIA: 90 dia(s) de Garantia Produto 100% Original. A nota fiscal garante contra defeito de fabricação! **ATENÇÃO** Antes de finalizar a compra, pergunte quantas vezes for necessário e tire todas as suas dúvidas. Nossa equipe de vendedores está à disposição para auxiliar. Se não conseguir localizar o item que precisa ou se necessitar de mais alguma informação sobre o produto entre em contato conosco (GAMER HUT STORE). SOBRE O JOGO GRADIUS ORIGINS é a coleção definitiva dos clássicos jogos de tiro Gradius, apresentando 18 versões de sete títulos lendários de arcade – incluindo, pela primeira vez em consoles domésticos, a versão Gradius III AM Show. Esta edição não é apenas uma homenagem a uma das séries de jogos de tiro mais importantes da história, mas também uma oportunidade perfeita para aprender sobre seu desenvolvimento – desde o icônico Gradius, passando por Salamander e Life Force, até Gradius III e Salamander 2. A coleção também oferece uma série de melhorias modernas que permitem aos jogadores desfrutar dos jogos tanto em suas versões originais quanto nas aprimoradas. Os novos recursos incluem salvamento rápido, retrocesso, Modo Invencível e Modo Treinamento, tornando o aprendizado, a experimentação e a quebra de recordes mais divertidos do que nunca.', 379.89, 379.89, NULL, 'Gaming & Consoles > Video Games > Playstation', 'https://cf.shopee.com.br/file/sg-11134201-82288-mhbyonzsoo3s50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609735381%2F58250795854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
