INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994659123', 'Liquidificador Mondial 1,5l Easy Power 550w L-550-b Liquidificador L-550-b 220v-60hz .', 'Liquidificador Mondial 1,5l Easy Power 550w L-550-b Liquidificador L-550-b 220v/60hz . Com 550W DE POTÊNCIA, COPO DE 1,5L útil, 1,9L total, além de 2 VELOCIDADES + PULSAR, FUNÇÃO AUTOLIMPEZA E LÂMINAS SUPER AFIADAS, o Easy Power L-550-B é um liquidificador preto, de montagem rápida e prática. Com POTÊNCIA DE 550W, ele tem melhor desempenho nas receitas do dia a dia, como sucos, vitaminas, papinhas de bebê, cremes e smoothies. Seu copo de 1,9 l é RESISTENTE a quedas e riscos, pois é feito de polipropileno. Ele tem 2 VELOCIDADES + PULSAR, para uma mistura mais rápida. E ele ainda tem a FUNÇÃO AUTOLIMPEZA: basta encher o copo até a metade com água e um pouco de detergente, apertar o botão pulsar algumas vezes e pronto! Já a BASE ANTIDERRAPANTE traz mais e seu GUARDA-FIO faz o liquidificador caber perfeitamente no seu armário. O Liquidificador Power Easy L-550-B foi desenvolvido para USO DOMÉSTICO, sendo melhor para uso residencial. Tudo isso com 1 ANO DE GARANTIA - L-550-BCor - PretoVoltagem (Tensão) - 127V/220VItens inclusos - 01 Liquidificador - Manual de InstruçõesMaterial do copo - PP e San CristalCapacidade (Total) - 1,9LCapacidade (Útil) - 1,5LPotência - 550WVelocidades - 2 VelocidadesFunção pulsar - SimFunção auto-limpeza - SimFiltro - SimDimensões do produto - 25,50cm x 31cm x 18,50cm (LxAxP)Peso do produto - 1,400kgGarantia - 1 ano', 99.9, 99.9, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/sg-11134201-821fa-mgmnj5csos200e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617519379%2F22994659123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
