INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25043328943', '1/3/6 Unidades Refil Para Tinta Marcador Permanente Recargas Marcadores 20Ml Escolar Escritório', 'O Conjunto com 06 Marcadores Permanentes e Marca Textos é ideal para uso escolar e de escritório, oferecendo versatilidade e praticidade. Com canetas de alta qualidade, esse kit inclui marcadores permanentes para escrever de forma duradoura em diversos materiais, como plástico, vidro e papel, e marca-textos para destacar e organizar suas anotações. A embalagem compacta vem com 6 cores diferentes, garantindo que você tenha sempre a cor certa para cada tarefa. Perfeito para professores, estudantes e profissionais, este conjunto também é ideal para uso em quadros brancos e CDs.', 19.9, 8.46, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/br-11134207-820ls-mmq2vf35fthi9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F25043328943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
