INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10614301157', 'Capa Do Tanque Yamaha Ybr 125 Factor De 2009 A 2015 Sem Logo - Azul - Vermelha - Cinza - Preto.', 'EMPRESA: J&J MOTORCYCLES Veja Algumas das Vantagens de Comprar Conosco: • Qualificações Positivas • Rapidez no Envio • Ótimo Atendimento • Compra Totalmente Segura ......................................................................................................................................................... PRODUTO: Capa Do Tanque Yamaha Ybr 125 Factor De 2009 a 2015 Com Logo ......................................................................................................................................................... DESCRIÇÃO: • Capa De Tanque • Com Logo • Presilhas Em Metal • Material: Courvin • Fabricante: Proter • Marca: Yamaha • Modelo: Ybr 125 Factor • Versões: Todas • Anos: De 2009 a 2015 • De Fácil Instalação • Ótimo Acabamento • Cores: Preto / Azul / Cinza / Vermelho ......................................................................................................................................................... IMPORTANTE: • Leia todo o anúncio, caso tiver alguma dúvida esclarecer no campo de perguntas antes de comprar • Temos mais de 5000 itens, faça um orçamento conosco • Com garantia e qualidade para melhor atender', 46.9, 46.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Covers', 'https://cf.shopee.com.br/file/c443aca2c0d2263f69f7c23edcae441e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F307813655%2F10614301157', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893986756', 'KIT RELAÇÃO ABSOLUTE PRIME 12V - CÂMBIO TRASEIRO + ALAVANCA - 1X12V', 'KIT RELAÇÃO ABSOLUTE PRIME 12V - CÂMBIO TRASEIRO + ALAVANCA - 1X12V ** CONJUNTO ESPECÍFICO PARA RELAÇÃO COM COROA ÚNICA ** ** EXCLUSIVO PARA CASSETE DE 12V – 11/50 OU 11/52 DENTES ** Itens que compõe o anúncio: - 01 und - CÂMBIO TRASEIRO ABSOLUTE PRIME 12V – CINZA - Sistema Clutch; - 01 und - ALAVANCA ABSOLUTE PRIME 12V – CINZA – LADO DIREITO. Descrição: O kit de transmissão ABSOLUTE PRIME 12V é indicado para os ciclistas que estão iniciando no mundo das relações de coroa ÚNICA. O conjunto é formado por um câmbio traseiro e uma alavanca direita ambos específicos para trabalhar com cassete de 12v com escalonamento 11/50, 11/51 ou 11/52. A alavanca segue com cabo de aço instalado e fixação por abraçadeira. As trocas de marchas são feitas com o dedo POLEGAR ou com os dedos INDICADOR e POLEGAR. Sobe até 04 posições de marchas com um movimento completo da alavanca e desce 01 posição de marcha por acionamento. O câmbio traseiro tem ÓTIMA construção de materiais e acabamento, mesmo não possuindo sistema de trava, conta com o poderoso sistema CLUTCH, que garante uma grande pressão no cage. Garantiando sempre uma maior tensão da corrente e bastante eficaz em terrenos acidentados. O conjunto foi desenhado para trabalhar com cassete de 50 dentes, 51 dentes ou 52 dentes, não necessita de prolongador ou outro artifício para montagem. O kit é indicado para quem deseja realizar um upGrade de componentes na sua bike e convertê-la para 1x12v a nível INTERMEDIÁRIO de uso. Especificações: - Marca: ABSOLUTE - Modelo: PRIME 12V; - Modalidade: MTB - INTERMEDIÁRIO; - Compatível com COROA ÚNICA e Cassete 11/50 ou 11/52 de 12V; - Roldana do Câmbio Traseiro: Dentes cada; - Indicador de posição de marcha na alavanca: Não; - Material: Alumínio, Aço e Plástico; - Cor: Preto; - Origem: CHINA; - Peso aproximado: CÂMBIO – 286g, ALAVANCA - 139g. Atenção: - Acompanha Embalagem Original; - Produto original ABSOLUTE; - Importado por ISAPA; - Garantia de 90 dias; - Acompanha nota fiscal. Aguardamos o seu pedido! INDIAN BIKE SHOP', 452.96, 452.96, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rfh6-m9xvjbsi3and92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22893986756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58214625726', 'Kit 2 Tubos Solda Estanho 1mm Cobix 63x37 Fio Fluxo Estanho Chumbo Profissional Eletrônica Solda 220V', 'Estanho Tubinho - Cobix - Indicado para soldar componentes eletroeletrônicos - Possui fluxo RA composto por resina, solvente e ativadores agressivos para superfícies moderadamente oxidadas - O resíduo de fluxo RA é corrosivo e deverá ser removido logo que possível após a refusão para evitar danos na montagem - O fluxo do tipo ''''RA'''' é indicado para remover o filme de óxido superficial do cobre, latão, bronze e bases estanhadas. - Especial para reparos em aparelhos eletroeletrônicos - Kit composto por 2 peças do estanho tubinho.', 30.76, 30.76, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825ad-mqw6gzqx7mrn69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F58214625726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898453253', 'Par Aro Preto Vzan Vmaxx 26 Paredão P/Freio A Disco+Raios Finos Pretos+Cubos Aço 36F Roda Montada', 'Este anúncio se refere a 1 PAR de RODAS VMAXX MONTADAS, serão enviados 2 aros montados completos. O aro Vmaxx Vzan é um dos principais aros para do Downhill. Foi desenvolvido para uso Extremo dentro das modalidades do DH. Sua estrutura é capaz de suportar grandes obstáculos que são exigidos pelos consumidores desta modalidade. Aro: Vmaxx DH P/Freio à Disco Furação: 36. Peso: 780 gramas cada Material: Alumínio Tipo de Válvula: Grossa(Scharader) Marca: Vzan Aro 26 A linha de cubos da SHUNFENG todos os requisitos para um componente satisfatório. A sua composição é toda em aço deixando-o mais resistente, os eixos permitem a trava completa das rodas. Eles são compatível com sistemas de 18 a 24v e podem ser utilizado em freios de borracha, quanto disco e hidráulicos. Cubo de aço para freio a disco preto com esfera (par) Cubos com rolar de esferas; Eixo dianteiro e traseiro; Furação do raio: 36 furos para raio até 2.0mm (Raio Fino); Sistema: para uso de roda livre marcha 6v/18v 7v/21v e 8v/24v; Composição: Aço; Marca: SHUNFENG Raiação Preta aço 255mm 2.0 fina p/ aro 26 paco Marca: paco Modelo 255mm 2.0 Cor: preto Este anúncio se refere a 1 PAR de RODAS VMAXX Montadas, serão enviados 2 aros montados completos. Aros já vem montados!', 280.36, 280.36, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rfi6-m9dsnmwmswq18d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22898453253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798834952', 'Banco Selim Bmx GTS-K Tipo DDK MTB Freestyle Jump 250x160mm', 'Olá, seja bem vindo(a) em nossa loja! - PRODUTO NOVO - ENVIO IMEDIATO - PRODUTO COM NOTA FISCAL - MELHOR CUSTO BENEFICIO BANCO SELIM GTS-K PARA BMX FREERIDE JUMP CROSS DOWHILL BIKE O Banco Selim GTS-K 243 é um acessório projetado para práticas extremas como Dirt Jump, BMX, Cross, Freeride e Downhill. Ele possui um comprimento de 241 mm e uma largura de 160 mm, o que proporciona uma base adequada para essas modalidades de alta intensidade. Suas principais características incluem: - Cor preta, o que lhe confere um visual esportivo e discreto. - Conforto e durabilidade, sendo ideal para absorver impactos frequentes e manobras radicais. - Design ergonômico, que oferece suporte adequado ao ciclista, sem comprometer a mobilidade. - Resistência: projetado para aguentar fortes impactos e as condições rigorosas dos esportes de aventura. Essas características fazem do Selim GTS-K 243 uma escolha ideal para ciclistas que buscam desempenho e robustez em modalidades extremas. QUALQUER DÚVIDA ESTAMOS À DISPOSIÇÃO!', 47.72, 47.72, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-mdrzf6i6amz82e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23798834952', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
