INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898097865', 'Regulador Freio Gm Monza 1982 a 1996 - 203917 - 2105', 'Regulador Freio Gm Monza 1982 a 1996 203917 2105 1.6/1.8/2.0 - (AUTOMATICO) (1 RODA - TRASEIRA - LADO DIREITO) (SISTEMA ATE) Compensa o desgaste das lonas, mantendo as sapatas sempre próximas ao tambor. Aplica nas rodas traseiras. Mas também nas rodas dianteiras, com freio a tambor dianteiro. Para regulagem automática, a peça fica entre as sapatas, presa por molas e com o auxilio (ou não) dos acionadores compensa o desgaste das lonas. Ocorre quando pedal de freio é acionado. Regulagem manual, ajuste deve ser feito manualmente por um mecânico. _x000D_ Fabricado em aço, com componentes em aço inox e materiais sinterizados.', 35.21, 35.21, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd4d-lvvgdm92hd8m3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22898097865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40703491186', 'Filtro Ar Cabine Peugeot 206 2004 a 2009 - 507134 - AKX35157', 'Filtro Ar Cabine Peugeot 206 2004 a 2009 507134 AKX35157 (Feline / Holliday / Presence / Moonlight / Sensation) - Motor 1.4 8v Gasolina/Flex - (Mecânico) - (Sem carvão) - (Com espuma) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 30.87, 30.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-823p8-mok2uss1wkcse4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F40703491186', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
