INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498024963', 'Kit Bico Injetor CELTA 2000/2001 - 36658 - 1212', 'Kit Bico Injetor CELTA 2000/2001 1.0 8v Gas. (Sist.Delphi - Multi Point) (4 Ponteiras) [(8 O''rings (4 -Ø Int. 7,52/Ø Secção 3,53 / 4 - Ø Int. 9,19/Ø Secção 2,62)] Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 28.64, 28.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7ren7-m2gx2rrzg5ud6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23498024963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997626358', 'Ponteira Motopoda Sabre Adaptador Roçadeiras Tubo 26mm 9 Estrias Toyama Tbc26 Tbc33 Tb43s', 'Lâmina Moto Poda Para Roçadeira – Tubo 26mm 9 Estrias Transforme sua roçadeira em uma máquina multifuncional com a Lâmina Moto Poda. Compatível com todos os modelos de roçadeiras com tubo de 26mm e 9 estrias, este acessório proporciona maior eficiência e praticidade para cortes de poda, galhos e manutenção de áreas verdes. Ideal para profissionais e usuários que buscam versatilidade sem abrir mão da qualidade. Características Técnicas: Compatível com tubos de 26mm e 9 estrias. Montagem simples: acople ao tubo da roçadeira, aperte os parafusos e coloque óleo de lubrificação de corrente no reservatório. Acompanha corrente e sabre de 30cm, garantindo cortes precisos. Máquinas Compatíveis: Tekna, Nagano, Matsuyama, Toyama, Bandai, Terra, Kawashima, Vulcan, Gamma Elite, Branco, Lira, Siga Tools, Brutatec, Yamasaki, Ferrari, Cid, FortG, Tramontina, Garthen, Azen, Intech Machine, Nakasaki, Honda (detalhes completos listados acima). Itens Inclusos: 1 Corrente 1 Sabre (lâmina) de 30cm Parafusos Informações Importantes: Utilize óleo de lubrificação de corrente comum no reservatório antes do uso. Garantia do Vendedor: 3 Meses', 169.0, 156.91, NULL, 'Home & Living > Gardening > Lawn Mowers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meptxw4cymtd25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177369665%2F18997626358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
