INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25911146461', 'LAIKOU Sakura Creme Facial Niacinamida Clareador Hidratante 50g', 'Pele mais iluminada, hidratada e radiante todos os dias ✨ Descubra o poder do cuidado com Extrato de Sakura + Niacinamida, uma combinação perfeita para ajudar a deixar sua pele mais hidratada, uniforme e com aparência saudável. A textura leve do creme proporciona uma sensação confortável na pele, ideal para fazer parte da sua rotina diária de skincare. 💖 Benefícios do Sakura Niacinamida Creme Facial 🌸 Pele mais iluminada Ajuda a melhorar a aparência da pele opaca, proporcionando um aspecto mais radiante e saudável. 💧 Hidratação profunda Mantém a pele hidratada e macia durante o dia, evitando a sensação de ressecamento. ✨ Ajuda a uniformizar o tom da pele Com Niacinamida, auxilia no cuidado da pele com aparência irregular e sem brilho. 🌿 Textura leve e confortável Absorve facilmente, deixando a pele suave sem sensação pesada ou oleosa. 🌸 Ingredientes Principais 🌸 Extrato de Sakura (Flor de Cerejeira) Conhecido por seu cuidado suave, ajuda a proporcionar uma pele com aparência mais luminosa e delicada. 💧 Niacinamida Ingrediente popular no skincare, conhecido por auxiliar na hidratação e melhorar a aparência geral da pele. 📦 Informações do Produto Marca: LAIKOU Linha: Sakura Produto: Creme Facial com Niacinamida Peso líquido: 50g Validade: 5 anos ✨ Como usar 1️⃣ Após limpar o rosto, aplique uma quantidade adequada do creme. 2️⃣ Espalhe suavemente pelo rosto até completa absorção. 3️⃣ Use diariamente pela manhã e/ou à noite para uma rotina completa de cuidados.', 120.0, 59.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/cn-11134207-820l4-mqfnljicdbm462', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F250961519%2F25911146461', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
