INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207961037', 'Par Pneu Moto Michelin 90/90-21 + 150/70-17 Anakee Adventure Big Trail Tiger 800', 'Par de Pneus Michelin Anakee Adventure 90/90-21 + 150/70-17 – Máxima Performance para Big Trail On/Off-Road O par de pneus Michelin Anakee Adventure (90/90-21 dianteiro + 150/70-17 traseiro) foi desenvolvido para motociclistas que exigem alto desempenho, segurança e durabilidade em qualquer tipo de terreno. Com tecnologia avançada da Michelin, esse conjunto oferece excelente aderência no asfalto e ótima tração em pisos irregulares, sendo perfeito para motos big trail e viagens de longa distância. 🔧 Especificações Técnicas: Dianteiro: 90/90-21 Traseiro: 150/70-17 Modelo: Anakee Adventure Tipo de uso: 80% on-road / 20% off-road Construção: Radial (traseiro) / Convencional (dianteiro) Marca: Michelin 🚀 Principais Benefícios: Aderência superior no molhado: Tecnologia com sílica que garante mais segurança em dias de chuva Alta durabilidade: Composto resistente ao desgaste, ideal para viagens longas Estabilidade e controle: Excelente desempenho em curvas e altas velocidades Versatilidade total: Enfrenta asfalto, terra e cascalho com eficiência Conforto na pilotagem: Menos vibração e melhor absorção de impactos 🏍️ Indicação de Uso: Compatível com motos big trail como BMW GS, Honda Africa Twin, Yamaha Ténéré, Suzuki V-Strom, entre outras. Ideal para quem busca um pneu confiável para uso urbano, rodoviário e aventuras leves off-road. 💡 Por que escolher o par Anakee Adventure? Adquirindo o par, você garante equilíbrio total entre dianteira e traseira, melhorando a dirigibilidade e segurança da moto. É a escolha perfeita para quem quer rodar com confiança em qualquer condição.', 3211.1, 2799.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-820lq-mmhinds7mmtib9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1680878209%2F58207961037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
