INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499005442', 'Flange Bomba Combustível Fiat Palio 2004 a 2008 - 808624 - 2401', 'Flange Bomba Combustível Fiat Palio 2004 a 2008 808624 2401 (Weekend) - 1.8 8v Flex Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 63.49, 63.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl1-lmszyjm5mlay92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20499005442', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898074476', 'Tênis Hocks Bold Vanilla', 'Tênis Hocks Bold Vanilla É hora de voltar ao passado e viver a essência do skate. Apresentamos o novo tênis da linha vivencia Hocks Bold, um modelo que combina estilo, conforto e uma incrível inspiração nas clássicas silhuetas dos anos 2000. O cabedal é uma verdadeira obra prima, são mais de 90 peças na sua construção combinando diversos materiais e acabamento para criar uma estética única e um visual urbano. Cabedal em couro natural com detalhes refletivos, lingueta com bolso mocado, calcanhar conformado e super acolchoado, cadarço fatlace mais passadores em TPU, solado com duas costuras de borracha mais costura de blaque, palmilha FlexForm em PU termo conformado proporcionando maior conforto e memória, prolongando a durabilidade. OBS: RECOMENDAMOS QUE CONFIRA A TABELA DE MEDIDAS ANTES DA COMPRA, PARA EVITARMOS TROCA POR ERRO DE TAMANHO. TABELA DE MEDIDAS: 34- 22,7cm 35- 23,3cm 36- 24,0cm 37- 24,7cm 38- 25,3cm 39- 26,0cm 40- 26,7cm 41- 27,3cm 42- 28,0cm 43- 28,7cm 44- 39,3cm Conservação do seu tênis: A PRINCE OF STREETS não recomenda a lavagem ou o uso de produto químico para a limpeza dos produtos. Este tênis deve seguir as seguintes instruções de limpeza: -Não colocar na máquina de lavar -Não usar alvejantes, sabão em pó, detergente e nenhum outro produto químico -Não deixar de molho -Limpar com pano ou esponja úmida -Deixar secar a sombra em superfície plana -Não coloca-lo em secadora. r', 499.9, 374.93, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rd6f-m76nbuae090a08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490976150%2F20898074476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
