INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20676077856', 'Mesa Para Computador Escrivaninha 4115 com 2 Gavetas', 'Modelo: Escrivaninha 4115; Material da estrutura: MDP 15 mm/12mm; Acabamento: Pintura UV; Largura: 100 cm; Profundidade: 45 cm; Altura: 75 cm; Em forma de L: Não; É gamer: Não; Quantidade de portas: 01; Material de dobradiças: Metálicas; Quantidade de gavetas: Não se aplica; Com puxador: Sim; Material do puxador: ABS; Com fechadura: Não se aplica; Quantidade prateleiras: 01; Possui suporte para teclado: Não se aplica; Com rodízios: Não se aplica; Peso suportado: 38 kg distribuídos; Requer montagem: Sim (kit montagem incluso); Condição do item: Novo; É kit: Não; Altura da embalagem: 9,5 cm; Largura da embalagem: 47,7 cm; Comprimento da embalagem: 106,7 cm; Peso: 20,000 kg; Embalagem do envio: Papelão e plástico. Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - O produto será entregue desmontado; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, custos de transporte por escadas e/ou elevadores, guincho ou içamento, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, certifique-se que todas as instruções dispostas no manual, bem como todas as ferragens descritas, estejam presentes dentro da embalagem. Verifique se há alguma peça danificada, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 282.92, 282.92, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-23030-3slj3kkp