INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206313547', 'Fritadeira Elétrica Sem Óleo Air Fryer WAP Oven WAOD2 Antiaderente 12 litros 1800W Black Inox', 'Fritadeira Elétrica Sem Óleo WAP Oven 12L - A Revolução Da Sua Cozinha Com Mais Saúde E Praticidade! Descubra A Revolução Na Sua Cozinha Com A Fritadeira Elétrica Sem Óleo Air Fryer WAP Oven, A Combinação Perfeita Entre Inovação, Saúde E Praticidade. Com Função Forno E Fritadeira, Este Equipamento Multifuncional Permite Assar, Cozinhar E Fritar Sem Óleo, Garantindo Refeições Mais Saudáveis, Saborosas E Crocantes Em Um Único Aparelho. A Capacidade Generosa De 12 Litros E A Tecnologia De Circulação De Ar Quente 360° Proporcionam Cozimento Uniforme, Deixando Os Alimentos Crocantes Por Fora E Suculentos Por Dentro. O Painel Digital Intuitivo Conta Com 10 Funções Pré-Programadas, Timer Ajustável De 1 Minuto A 24 Horas E Controle De Temperatura De 30C A 200C, Garantindo Resultados Perfeitos Em Cada Receita. Com Revestimento Antiaderente Gray Stone Nos Acessórios, A Limpeza É Fácil E Rápida. Acompanha Bandeja Coletora De Gordura, Duas Bandejas, Cesto Removível De 4,5L E Kit Completo De Acessórios Para Mais Versatilidade No Dia A Dia. Destaques Do Produto: Capacidade De 12 Litros Função 2 Em 1: Forno E Fritadeira Sem Óleo Tecnologia De Circulação De Ar Quente 360 Painel Digital Com 10 Funções Pré-Programadas Controle De Temperatura De 30 C A 200 C Timer Ajustável De 1 Minuto A 24 Horas Revestimento Antiaderente Gray Stone Acessórios Incluídos: Bandejas, Cesto Removível E Bandeja Coletora De Gordura WAP Oven - Inovação, Sabor E Saúde Em Cada Receita!', 559.0, 559.0, NULL, 'Home Appliances > Kitchen Appliances > Deep Fryers', 'https://cf.shopee.com.br/file/sg-11134201-825zx-mlgi173mx345e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58206313547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256406421', 'Armário Aéreo Cristal MDP 15mm com 2 Portas com Vidro e 2 Prateleiras Bartira', 'Armário Aéreo Bartira Cristal MDP 15mm com 2 Portas com Vidro e 2 Prateleiras - 80cm de largura O armário aéreo Bartira Cristal é o módulo perfeito para compor a sua cozinha. Produzido em MDP de 15mm de espessura, ele proporcionar um espaço muito especial para você manter diversos itens de cozinha muito bem armazenados e fáceis de encontrar. Equipado com porta de bater com vidro, esse móvel ainda dispõe em sua estrutura com puxador em alumínio, sistema de dobradiças com amortecedor, acabamento em finish foil que possibilita maior vida útil ao produto e capacidade para suportar até 24kg bem distribuídos. Categoria: Móveis > Cozinhas > Cozinha Modulada Fabricante: Bartira Características Gerais: Feito em MDP 15mm Acabamento finish foil Porta com vidro Prateleiras Medidas do vidro: 89,7 x 39,7 x 2cm (AxLxP) Puxadores em alumínio discretos e resistentes Sistema de dobradiças com amortecedor Peso suportado: 24kg Material: MDP 15mm Tipo: Armário Aéreo Tipo de Porta: Bater Porta com vidro: sim Puxador: Alumínio Quantidade de Portas: 2 Quantidade de Prateleiras: 2 Acabamento: Finish Foil Acabamento: Fosco Suporta até (kg): 24 Conteúdo da Embalagem: - 1 Armário Aéreo Bartira Cristal MDP 15mm com 2 Portas com Vidro e 2 Prateleiras - 80cm de largura Dimensões: Altura (cm): 90 Largura (cm): 80 Profundidade (cm): 39,1 Garantia: 6 meses Atenção: Não nos responsabilizamos pela montagem ou instalação do produto, Foto meramente ilustrativa Entrega do Produto: Não nos responsabilizamos pelo transporte por escadas/elevadores, guincho ou içamento deste produto.., orientamos que este produto seja montado por um técnico de sua confiança, após a sua entrega, Todas as instruções, manuais e peças necessárias para a montagem são fornecidas junto com o produto, não nos responsabilizamos pela instalação/montagem', 549.0, 521.55, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8261w-mlhrhca5hhjj98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58256406421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193690653', 'Palheta Traseira Bosch REAR 12E', 'Palheta Traseira Bosch Rear - Encontre a Compatível com Seu Carro! Modelo: Palheta Traseira Bosch Rear 10E As palhetas Bosch Rear são conhecidas pela sua qualidade, durabilidade e excelente desempenho em qualquer condição climática. Se você busca a melhor opção para manter seu para-brisa limpo e sua visibilidade perfeita, encontrou o produto certo! Características do Produto: Marca: Bosch Modelo: Rear Aplicação: Palheta traseira Material: Borracha de alta qualidade Durabilidade: Longa vida útil com resistência a desgaste Benefícios: Desempenho Superior: Limpeza eficiente e silenciosa. Fácil Instalação: Substituição rápida e simples. Durabilidade: Desenvolvidas para resistir às condições mais extremas. Compatibilidade: Diversos modelos disponíveis para diferentes veículos. Como Escolher a Palheta Certa: Instruções de Compra: Confirme o ano e modelo do seu veículo e adicione ao carrinho. Garantia de Satisfação: Garantimos a qualidade de nossos produtos Bosch. Caso tenha qualquer problema ou dúvida, nossa equipe de atendimento está pronta para ajudar! Fotos do Produto: Imagens detalhadas das palhetas Fotos ilustrativas mostrando a instalação Perguntas Frequentes: Como sei qual é a palheta correta para meu carro? No anuncio e a descrição informamos o ano e modelo dos veículos . Se precisar de ajuda, entre em contato conosco. As palhetas são originais Bosch? Sim, todos nossos produtos são 100% originais Bosch. Qual é o prazo de entrega? O prazo de entrega varia conforme a região. Verifique as opções de envio ao finalizar a compra. Entre em Contato: Se tiver dúvidas ou precisar de assistência na escolha da palheta correta, não hesite em nos contatar através do chat do Mercado Livre. Estamos aqui para ajudar! Garanta agora a visibilidade perfeita em todas as condições climáticas com as Palhetas Bosch Rear! Escolha a sua e compre já!', 64.97, 64.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5lcwdvjr8ud0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F22193690653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494528247', 'WHISKY BOURBON JIM BEAM HONEY 1000ML', 'Licor Fino De Mel Bourbon Americano Jim Beam Honey 1l é uma variante do tradicional Jim Beam, enriquecido com infusão de mel, o que confere uma graduação alcoólica de 35%. A marca Jim Beam, com mais de 200 anos de tradição, representa o autêntico espírito americano. Este destilado é produzido a partir de milho, centeio e cevada maltada, e passa por um processo de envelhecimento de 4 anos em barris novos de carvalho carbonizado.', 124.99, 99.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-825b0-mfwnoeitr8cqa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F23494528247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
