INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597627495', 'Desengraxante Multiuso (500ml) C/ Gatilho - H7', 'H-7 DESENGRAXANTE REMOVEDOR MULTIUSO PARA LIMPEZA PESADA No mercado há mais de 37 anos, é um produto de origem americana, 100% biodegradável, com fórmula a base de água e livre de ácidos ou solventes.Já chega de cair em furadas, o H-7 é o verdadeiro limpador multiuso que sua oficina precisa! Com alta eficiência, ele é perfeito para limpezas diversas de graxa, óleo, gordura e fuligem.O famoso desengraxante já vem pronto para uso, e, não precisa ser diluído. O H-7 pode ser aplicado em: máquinas, motores, engrenagens, correntes, pisos, calçadas, cerâmicas, inox, alumínio, fogões, fornos, coifas, grelhas, churrasqueira, calçados, carpetes, toalhas, box de banheiro, bicicletas, portões, piscina, lataria ou onde mais você precisar.Sem cheiro, e com muito mais eficácia.Use sem medo o H-7, ele é um desengraxante que não agride o meio ambiente, e nem a saúde do usuário.Não importa qual for o desafio, o desengraxante H-7 encara. EMBALAGENS: 500ml c/Gatilho e Refil 1lt c/Gatilho e Refil 5lt', 39.32, 39.32, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzjg0hs29hr908', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F19597627495', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
