INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198811798', 'Relógio Champion Feminino Rosé Digital Led CH40080P', 'SOBRE A EMPRESA: Somos a Relógios Campana, uma empresa especializada em vendas online, revendedora autorizada das maiores marcas do mercado. Trabalhamos apenas com relógios originais com garantia de fábrica. Comprando conosco você tem a segurança que receberá seu produto nas seguintes condições: => REVENDEDOR AUTORIZADO => PRODUTO ORIGINAL => GARANTIA DO FABRICANTE => PRODUTO NOVO => EMBALAGEM ORIGINAL DO PRODUTO => MANUAL DE INSTRUÇÕES => CERTIFICADO DE GARANTIA => NOTA FISCAL => RELÓGIO A PRONTA-ENTREGA SOBRE O PRODUTO: O Relógio Champion Feminino Rosé Digital Led CH40080P combina um design minimalista com tecnologia e sofisticação, sendo a escolha ideal para mulheres que procuram um acessório moderno e versátil. Seu acabamento rosê e o elegante visor preto criam um visual contemporâneo que se adapta facilmente a diferentes estilos e ocasiões. O diferencial do modelo é o display digital que permanece discreto quando inativo e revela as informações por meio da iluminação LED vermelho, proporcionando um efeito visual moderno e sofisticado. A caixa quadrada em metal harmoniza perfeitamente com a pulseira mesh em aço inoxidável prateado, oferecendo conforto, excelente ajuste ao pulso e um acabamento premium. Especificações: Marca: Champion Modelo: CH40080P Tipo de relógio: Digital Gênero: Feminino Estilo: Casual Cor da caixa: Rosê Cor da pulseira: Rosê Alarme: Não Cronômetro: Não Timer: Não Calendário: Sim Luz: Sim Resistência à água: Sim – rotinas diárias Material da Caixa: Aço Material da pulseira: Mesh de Aço Tipo de Fecho: Fivela de gancho Características do vidro: Cristal Mineral Tamanho da caixa (A x L): 44 x 37 mm Espessura da caixa: 10 mm Lug-to-Lug: 44 mm Comprimento da pulseira: 22 cm Largura da pulseira: 24 mm Tampa do fundo: Rosqueado Peso: 124 Gramas Alimentação: Bateria Conteúdo da Embalagem: Relógio, certificado de garantia, manual de instruções. Garantia do Fabricante: 12 meses Fabricante: Magnum Indústria da Amazônia S/A Ficou alguma dúvida? Estamos à disposição no campo de mensagens!', 399.9, 399.9, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/br-11134207-820lq-mq7q1fg1454wbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F418189829%2F22198811798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
