INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202946177', 'L''Oréal Professionnel Serie Expert NutriOil - Condicionador 200ml', 'Condicionador para cabelos secos e ressecados. L''Oréal Professionnel Serie Expert NutriOil deixa os fios 4x mais nutridos, macios e com brilho. O Condicionador L''Oréal Professionnel Serie Expert NutriOil foi desenvolvido especialmente para ser um tratamento nutritivo para cabelos secos. Sua fórmula é enriquecida com Óleo de Coco e Óleo de Soja, e possui uma textura leve que garante a dose certa de nutrição para os seus fios. Como usar: Aplique no cabelo lavado e úmido. Passe no comprimento e pontas. Deixe agir por alguns instantes. Enxágue bem. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 180.9, 180.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-8261e-mjy9394pd7glac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58202946177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203186092', 'Nivea Shine Amora - Hidratante Labial 4,8g', 'Hidratante labial. Nivea Shine é ideal para usar no dia a dia pois, graças a sua formulação com óleos naturais, deixa os lábios hidratados e suavemente coloridos. O Hidratante Labial Nivea Shine oferece cuidado e proteção por 24 horas, hidratando e proporcionando brilho delicado aos lábios. Garante uma sensação confortável e combate o ressecamento e as rachaduras.Além disso, possui fórmula livre de óleos minerais e sua embalagem é reciclável. Fórmula livre de óleos minerais. Como usar: Deslize o hidratante sobre os lábios e reaplique sempre que achar necessário. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 24.9, 24.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mjfjbf57dog188', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58203186092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797608331', 'Joelho 90° Esgoto 200mm Amanco', 'SOBRE O PRODUTO A Linha Amanco Esgoto Série Normal é um sistema para condução e armazenamento de esgoto sanitários, água pluvial e ventilação. Um portfólio completo para atender todos os projetos. Utilizada em instalações prediais de esgoto de aparelhos sanitários, escoamento por gravidade não submetida à pressão e na ventilação do sistema, com classe de temperatura pico CT 45C. CARACTERÍSTICAS - Atende a norma NBR 5688. - Linha fabricada em PVC. - Cor Branca. - Classe de Rigidez SN-1500 Pa. VANTAGENS Possui bolsas de dupla atuação (opção soldável ou com junta elástica). SOBRE A LINHA Voltados para instalações prediais de esgoto de aparelhos sanitários, escoamento por gravidade não submetida à pressão e na ventilação do sistema, os produtos dessa linha fazem a correta condução e armazenamento de dejetos. Fabricados em PVC na cor branca, os tubos e conexões atendem à norma NBR 5688.', 224.9, 224.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rd5q-lx16txhjgns6b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F22797608331', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
