INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19305206777', '100 Sacos Adesivados Transparente (cem) 100un', 'O Saco Plástico Transparente com Aba Adesiva é perfeito para qualquer tipo de produto. Sua transparência é nítida e traz vida aos seus produtos. Disponível em diversos tamanhos. Contendo uma variedade de funcionalidades, para bijuterias, presentes e também para embalar lembrancinhas de festas. Saquinhos com lacre resistentes. Embalados em pacote de plástico polipropileno extra brilho. A compra de um item equivale a um pacote com 100 sacos', 39.9, 39.9, NULL, 'Stationery > Gift & Wrapping > Gift Wrappers', 'https://cf.shopee.com.br/file/0efd0e1fc58cc4f37e603702cb89fef8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F330527204%2F19305206777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52506449893', 'Jogo De Panelas Com 10 Peças Mimo Style Pratic Cook Verde', 'Jogo de Panelas Com 10 Peças Mimo Style Pratic Cook Verde Agua - 10769 PJ10PGR Transforme sua rotina na cozinha com o Conjunto de Panelas Pratic Cook da Mimo Style. Composto por 10 peças fabricadas em alumínio reforçado com revestimento cerâmico, cada panela possui borda de 2 milímetros e fundo triplo com placa para indução. Compatível com todos os tipos de fogão, incluindo a gás, elétrico, vitrocerâmico e indução, esse conjunto garante praticidade, durabilidade e versatilidade no preparo de suas receitas. As panelas contam com cabos de baquelite com efeito madeira e protetor de chamas, oferecendo segurança e conforto no manuseio, já que não aquecem. As tampas de vidro temperado com saída de vapor facilitam o acompanhamento dos alimentos durante o preparo, sem precisar levantar a tampa. Além disso, o revestimento cerâmico de duas camadas com proteção térmica facilita a limpeza e evita que os alimentos grudem, tornando o uso muito mais prático no dia a dia. Com design moderno e acabamento marmorizado, esse conjunto de panelas traz sofisticação para a sua cozinha. Suas cores marcantes e linhas elegantes combinam com diferentes estilos de decoração, oferecendo não só funcionalidade, mas também um toque de charme ao ambiente. Ideal para quem deseja cozinhar bem sem abrir mão do estilo e da elegância. Perfeito para o uso diário, esse conjunto foi desenvolvido para atender desde os pratos mais simples até os mais elaborados. É indicado para o preparo de sopas, molhos, refogados, frituras e ensopados. Antes do primeiro uso, recomenda-se realizar o processo de cura para aumentar a durabilidade do revestimento. Com materiais de alta qualidade e estrutura robusta, o Conjunto de Panelas Pratic Cook é a escolha certa para quem busca eficiência, beleza e resistência na cozinha. Especificações Usos indicados Fogões a gás, elétrico, vitrocerâmico e indução. Composição Cabo em baquelite com efeito madeira Panelas com 2mm e fundo triplo com revestimento em cerâmica Tampas em vidro temperado Utensílios em plástico Panela Diâmetro: 16 cm x Altura: 7,5 cm Capacidade: 1500 ml Panela Diâmetro: 18 cm x Altura: 8 cm Capacidade: 2000 ml Caçarola Diâmetro: 20 cm x Altura: 9 cm Capacidade: 2800 ml Caçarola G Diâmetro: 22 cm x Altura: 9,5 cm Capacidade: 3600 ml Frigideira Diâmetro: 18 cm x Altura: 3,8 cm Capacidade: 750 ml Frigideira Diâmetro: 22 cm x Altura: 4,1 cm Capacidade: 1200 ml Leiteira Diâmetro: 14 cm x Altura: 12 cm Capacidade: 2000 ml Utensílios Concha 30 cm x 8,7 cm x 12 cm Escumadeira 33 cm x 5 cm x 11,6 cm Espátula 33 cm x 8,8 x 4 cm Material: Plástico', 679.0, 370.0, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/sg-11134201-8261x-ml5ic0nsne9u33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1404215442%2F52506449893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
