INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55302038241', 'Par de Lâmpadas LED 69 Ba9S-5050-5SMD 12V 6000k Tarponn - TP-5008', 'Tecnologia aliada a preço, assim é a Lâmpada Tarponn LED 69 Ba9S-5050-5SMD 12v 6000k! Composto por torre de LED responsável pela iluminação lateral e frontal, possui renda 69/Ba9S. Além de ser muito útil para atender os carros mais antigos, seu projeto de iluminação interna também é útil para ser instalado em farolete, luz de placa, porta mala. Possui baixo consumo de energia e alta durabilidade, ou seja, perfeito para você! Características: Torre de LED lateral e frontal Compacta Baixo consumo Durabilidade superior Iluminação branca fria Fácil instalação Aplicação: Farolete, luz de placa, porta-mala e luz interna. Ficha Técnica: Cor: Branca Fria Temperatura de Cor: 6000k Encaixe: Ba9S Tensão: 12v Equivalência: 5w Tipo de LED: SMD 5050 Fluxo luminoso: 85,5 Im Características: -Marca: Tarponn -Modelo: TP-5008 *Imagens meramente ilustrativas* Conteúdo da embalagem: - 01 par de lâmpadas LED', 19.48, 17.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-8227j-mhglckaoy29x7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F55302038241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792523934', 'Filtro Ar Cabine Hyundai Tucson 2013 a 2019 - 507240 - AKX1984', 'Filtro Ar Cabine Hyundai Tucson 2013 a 2019 507240 AKX1984 2.0 16V Flex - Automático / Mecânico - (Sem carvão) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 20.16, 20.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-822xz-mo9t63189ddsb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792523934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
