INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598987975', 'Carteira Carta Hogwarts - Harry Potter', 'Precisa correr para algum lugar, mas não sabe onde deixou seu dinheiro? A gente te ajuda! Com essa carteira você nunca mais vai esquecer onde deixou o dinheiro para os seus rolês! Com muito espaço, você guarda seus documentos, dinheiro e cartões em um único lugar! O produto é importado, feito em tecido sintético por fora e Nylon por dentro, com fechamento por zíper, possui detalhes que vão fazer você se apaixonar! Precisa de uma mãozinha na hora de organizar seus cartões e documentos? A gente te ajuda! Com essa carteira você tem espaço para os seus documentos, dinheiro e cartões em um único lugar! Não importa se você vai para o trabalho, faculdade ou rolê, essa carteira te acompanha em todas as suas aventuras! Especificações: Altura: 9cm| Largura: 2cm| Comprimento: 18cm| Peso: 0,145gr| Material: Tecido sintético e Nylon Cuidados: Não molhar ou deixar de molho. Usar uma flanela de algodão para remover o pó e outros resíduos que possam ficar acumulado tanto no lado externo quando interno da carteira. Não usar produtos abrasivos.', 99.9, 99.9, NULL, 'Women Bags > Wallets > Bifold & Trifold Wallets', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mkl042usjqbk49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F20598987975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
