INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260760619', 'Provermin Pó 20g Cada Vermífugo Oral Aves E Suínos', 'O Provermin é um vermífugo oral de amplo espectro à base de fembendazol, indicado para o tratamento de nematódeos gastrointestinais e pulmonares em bovinos, equinos, suínos, ovinos, caprinos e aves. Administrado via ração ou água, elimina ovos, larvas e adultos, sendo um antiparasitário de baixa toxicidade e alta eficácia. Loja Agropecuária +2 Principais Características e Dosagens (20g): Bovinos: 1 sachê (20g) para cada 90 kg de peso vivo (dose única). Equinos: 1 sachê (20g) para cada 54 kg de peso vivo (dose única). Suínos, Ovinos e Caprinos: 1 sachê (20g) para cada 80 kg de peso vivo (dose única). Aves: 1 sachê (20g) para cada 2 kg de alimento, durante 3 dias seguidos. Ação: Combate vermes como Ascaridia galli, Capillaria spp. e Heterakis gallinarum', 29.9, 7.99, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-820mg-moa2neqtx05fd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F823664460%2F58260760619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
