INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43677367254', 'Verse Protetor Plásticos Motores Restaurador Vonixx 500ML', 'O Protetor de Plásticos, Borrachas e Motores Verse 500ml da Vonixx é a solução perfeita para revitalizar e restaurar diversos componentes do seu veículo. Com acabamento brilhante, ele é ideal para proteger e dar vida nova a plásticos, borrachas, pneus, painéis, caixas de roda e motores. Sua fórmula exclusiva da linha de proteção da Vonixx garante resultados duradouros e de alta qualidade. Com formato em garrafa e volume de 500 mL, é o produto perfeito para revestir e cuidar do seu veículo. Não perca a oportunidade de deixar seu carro impecável com o Protetor de Plásticos, Borrachas e Motores Verse 500ml da Vonixx.', 72.99, 72.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-81zvc-mig8d510unt2ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1151751638%2F43677367254', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19560177345', 'Lola Cosmetics Liso, Leve and Solto Máscara Antifrizz 230g', 'Máscara Antifrizz Lola Cosmetics Liso, Leve and Solto possui efeito antifrizz para uso diário, perfeito para cabelos lisos naturais ou alisados. Ajuda no alinhamento dos fios e prolonga o feito liso. Sua composição é rica em Tamarindo, Canela e óleo de Oliva que são hidratantes para os fios e ajudam no fortalecimento e no crescimento, além de prolongar o efeito liso e a redução de fri[zz. Tem proteção térmica e solar e deixa o cabelo mega brilhante. * RESULTADO: Reconstrução * SUGESTÕES DE USO: 1.Aplique a máscara após a lavagem com o shampoo; 2.Distribua mecha por mecha; 3.Deixe agir de 3 a 5 minutos; 4.Finalize enxaguando abundantemente. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Lola Cosmetics Liso, Leve and Solto Máscara Antifrizz 230g', 50.9, 35.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-22110-wyrkw1fxshjv41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F19560177345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
