INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499239261', 'Shampoo Seda Ceramidas', 'O Shampoo Seda Ceramidas é ideal para proporcionar uma limpeza profunda e um cuidado intenso aos seus cabelos, deixando-os mais brilhantes, macios e cheios de vida. Enriquecido com Microceramidas, ajuda a revitalizar os fios e proteger contra danos diários. Modo de usar: Aplique o shampoo nos cabelos molhados, massageando suavemente o couro cabeludo até formar espuma e enxágue. Para resultados ainda mais incríveis, use também o Tratamento Condicionador Ceramidas. Seda possui a certificação PETA, o que significa que Seda não testa seus produtos em animais.', 17.49, 17.49, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-825a6-mqnelz9kwm4v16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676552986%2F23499239261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
