INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097908822', 'Kit Devocional Priorize Deus', 'Priorize Deus é o devocional mais completo do Brasil. Esta ferramenta extraordinária disponibiliza uma série de recursos pensados para levar o leitor a um relacionamento diário com Deus, o que causará enorme impacto na sua vida prática e no entendimento da fé. Cada uma das 365 reflexões do livro é acompanhada de perguntas-chave, um plano anual de leitura bíblica e ministrações em áudio com acesso por QR Code, além de seções adicionais nas páginas finais. Tudo elaborado com extrema responsabilidade e dedicação para tornar a experiência do leitor com o Senhor impactante e transformadora.', 161.22, 161.22, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mawogvpblabz9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F23097908822', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
