INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399309894', 'Mstail 2.2L Fonte de água automática em aço inoxidável de grande capacidade para gatos com janela de visualização', 'Características: 1. Material em aço inoxidável SUS304, seguro e ecológico; 2. Excelente design de saída de água que incentiva os animais de estimação a beberem mais água, o que é benéfico para a saúde; 3. Capacidade de 2,2 litros, tamanho compacto concebido especificamente para gatos; 4. Bomba de água silenciosa; 5. Funcionamento automático ao ligar, simplificando o processo. 6. Fácil de desmontar, conveniente para a limpeza, pode ser lavado na máquina de lavar louça. Especificações: Material do produto: Aço inoxidável Dimensões da caixa: 18*18*11,5 cm Peso da caixa: 0,56 kg Cabo de alimentação: 1,5 m Certificações: CE, FCC, RoHS Observações: Devido às diferenças de monitor e efeitos de luz, a cor real do artigo pode ser ligeiramente diferente da cor apresentada nas imagens. Por favor, permita uma variação de 1 a 3 cm nas medições devido à medição manual. Agradecemos a sua compreensão! Lista de embalagem: Dispensador de água*1 Bomba de água*1 Elemento filtrante*2 Algodão filtrante*2 Manual de instruções em inglês*1 Saída de água*1', 360.0, 139.99, NULL, 'Pets > Pet Accessories > Bowls & Feeders', 'https://cf.shopee.com.br/file/br-11134207-820lw-mp0ichdw94oz6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1699010507%2F23399309894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
