INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8266035600', 'Suporte Instrumento de Chão Ask G5 Dobrável Guitarra Baixo + 2 Palhetas', 'O Suporte para Instrumentos de Corda da Ask oferece toda a praticidade, resistência e versatilidade que você precisa para o dia-a-dia. Com design simples e discreto, ele é ideal para repousar o seu violão, baixo ou guitarra enquanto você não está usando, seja em apresentações ou no ensaio. A estrutura é em aço com detalhes plásticos, e ele suporta até 5kg, garantindo a durabilidade e resistência necessária. Sem contar que como é compacto você pode leva-lo para diversos lugares dentro da sua capa com muita praticidade.Características:Material: Aço / PlásticoCompatível: Violão Flat, Baixo e GuitarraRegulagem de altura: NãoRegulagem de ângulo: NãoDobrável: SimPés antiaderente: SimPeso: 410gContém:01 Suporte02Palhetas Sortidas*Imagens Ilustrativas', 50.85, 50.85, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rff3-m3gremtv4ch369', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F8266035600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
