INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799603007', 'Creme Dental Sensitive Pro Alívio Imediato Xtreme 4x90g', 'O creme dental para sensibilidade Colgate Sensitive Pro Alívio Imediato Xtreme Temperatures possui tecnologia avançada que cria uma barreira protetora para alívio da dor do dente causada pela sensibilidade dental proporcionando conforto ao ingerir bebidas e alimentos quentes ou frios. Benefícios: Tecnologia avançada: este creme dental para sensibilidade proporciona alívio da dor de dente causada pela sensibilidade dental, mesmo ao ingerir alimentos ou bebidas em temperaturas extremas. Alívio imediato 2x mais rápido: a arginina sela os canais que levam ao centro do dente proporcionando alívio imediato da sensibilidade dental duas vezes mais rápido (comparado com pastas de dente com nitrato de potássio, com base em estudos clínicos publicados). Bebidas e alimentos quentes ou frios sem sentir dor: esse creme dental para sensibilidade Colgate Sensitive Pro Alívio Imediato Xtreme Temperatures cria um escudo protetor contra a sensibilidade dental, mesmo quando provocada por temperaturas extremas. Clinicamente comprovado: tenha em casa a marca mais confiável para o tratamento de sensibilidade, segundo os dentistas (BRMO 2022). Uso diário: esse creme dental para sensibilidade Colgate Sensitive Pro Alívio Imediato Xtreme Temperatures pode ser usado diariamente. Contém flúor, que ajuda a proteger sua boca contra cáries e tem um sabor refrescante de menta.', 52.39, 52.39, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7ra27-m536dc1dy11cf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F18799603007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26178691654', 'Institutas da Religião Cristã | João Calvino', 'Institutas da Religião Cristã | João Calvino Esta primeira edição das Institutas, escrita originalmente em latim, apresenta ao leitor o fundamento do pensamento e o coração de Calvino, estabelecendo-se como a mais importante obra de sua vida obra que ele reeditou cinco vezes, até a sua última edição, em 1559. Depois de cinco séculos de seu lançamento, as Institutas permanecem úteis e relevantes para o estudo da doutrina e da piedade cristã. Dividida em duas partes, esta edição histórica oferece uma visão profunda do conhecimento de Deus e da vida cristã, e é uma obra que serve tanto ao interessado em aprofundar seu conhecimento da doutrina cristã como ao estudioso da obra do reformador francês.', 148.65, 148.65, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd3y-m718y51ke0lu5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F26178691654', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28086096700', 'Bíblia Anote NVT Slim espiral - Typo Rosa: Série Slim', 'Bíblia Anote Slim Typo Rosa| NVT | Capa Dura Espiral Bíblia Anote Slim Para você que gosta de registrar aquele trecho que acabou de ler na Bíblia, mas nem sempre conta com um espaço onde fazer suas próprias anotações, a GEOGRÁFICA EDITORA traz a Bíblia Anote NVT Slim. Nela, você tem como diferencial os espaços laterais em branco para poder registrar passagens que poderão ser usadas em seus estudos bíblicos ou pregações. A Bíblia Anote traz a Nova Versão Transformadora (NVT), uma tradução contemporânea, com formas verbais que facilitam em muito o entendimento. Nesta versão da Anote Slim, tivemos o cuidado de criar um novo produto, menor, mais leve e com uma letra mais confortável para leitura, sem deixar de lado o grande diferencial dela que são os espaços para anotação e as folhas mais encorpadas para fazer o Bible journal. Páginas:768Dimensões:Altura: 23 cm Largura: 19,5 cm Profundidade: 3 cm', 94.35, 94.35, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfhb-m9ekqrxcbh3t1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F28086096700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
