INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253233092', 'Par Junta Homocinética Lado Câmbio Corsa Classic 1994 2012', 'Caso precise confirmar se esta peça é compatível com seu veículo, envie uma pergunta abaixo informando modelo, ano e motor. Se possível, inclua também placa ou chassi para uma verificação mais assertiva. Peça nova, à pronta entrega, com garantia e nota fiscal. Este anúncio contém: Par Junta Homocinética lado câmbio Aplicação Montadora: Chevrolet / GM Veículo: Corsa Motor: 1.0 / 1.4 / 1.6 Ano: 1994 a 2012 Montadora: Chevrolet / GM Veículo: Corsa Classic Motor: 1.0 / 1.6 Ano: 2002 a 2010 Montadora: Chevrolet / GM Veículo: Corsa Pick-up Motor: 1.6 Ano: 2002 a 2010 Montadora: Chevrolet / GM Veículo: Corsa Sedan Motor: 1.0 Ano: 1998 e 1999 Sobre o produto A junta homocinética conecta o cubo da roda ao semieixo da transmissão, transmitindo a potência do motor para as rodas mesmo em diferentes angulações. Por ser essencial na transmissão de força, é considerada uma peça de segurança. Caso apresente desgaste ou quebra, o veículo pode perder totalmente a tração, causando a parada imediata.', 409.99, 328.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-8262x-mjg8tnueegate9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1557506191%2F58253233092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23496962684', 'KIT 12~96 SAIA PARA CUPCAKE BRANCO 12.1 ( NC TOYS CUPCAKE )', 'Dê um toque de elegância e acabamento impecável aos seus cupcakes com as nossas Saias Ajustáveis na cor Branca. Perfeitas para complementar a decoração de eventos sofisticados como casamentos, batizados, chás de bebê e festas com temas clean, elas garantem um visual profissional e refinado à sua mesa de doces. Feitas em Papel Offset de 250g, um material de alta qualidade e com a gramatura ideal, as saias proporcionam firmeza e beleza. O grande diferencial é a possibilidade de 2 ajustes, o que garante um encaixe perfeito para diferentes tamanhos de cupcakes, evitando desperdício e facilitando a montagem. Características do Produto: Modelo: Saia/Wrapper para Cupcake com 2 ajustes. Cor: Branca. Material: Papel Offset 250g, resistente e durável. Medidas: Boca: 8 cm Base: 4,5 cm Altura: 4,5 cm Quantidade: Escolha o kit ideal para sua necessidade: 12, 24, 48 ou 96 unidades. Adquira já as suas saias e garanta um visual impecável e profissional para todos os seus cupcakes!', 16.24, 16.24, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb2855r1ket5be', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23496962684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
