INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299460751', 'CAMISETA FITNESS FEMININA COM AMARRAÇÃO NO PESCOÇO BÁSICA DLK', 'A camiseta frente única com amarração no pescoço permite ajuste personalizado do nível de sustentação, conforme a preferência de uso. O decote alto amplia a cobertura na parte frontal, trazendo equilíbrio e contribuindo para mais conforto em movimentos de inclinação ou exercícios no solo. Confeccionada em poliamida a peça oferece elasticidade, secagem rápida e proteção UV 50+, além de garantir mais durabilidade para acompanhar sua rotina de treino. DESTAQUES - Modelagem frente única com amarração ajustável no pescoço - Feita em poliamida: Tecido com secagem rápida e perfeito para a prática de exercícios de baixo impacto - Possui compressão média e proteção UV 50+ - Abertura para bojo (não acompanha) - Decote alto para maior cobertura durante o treino INFORMAÇÕES ADICIONAIS Nível de compressão da peça: Médio Composição do tecido: 85% Poliamida 15% Elastano Sobre a cor do produto: Pode haver variação na cor do produto final de acordo com o brilho do monitor ou tela do celular. Garantia: Contra defeito de fabricação SOBRE A MARCA - Somos uma das maiores marcas de moda fitness do Brasil. - Entregamos as melhores roupas esportivas há mais de 10 anos. - Já chegamos a mais de 5 mil cidades em todo o país. - Contamos com mais de 2,8 milhões de DLK Lovers.', 95.99, 95.99, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-81ztk-mn315w0gyoeg91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F22299460751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
