INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15327147248', 'Jogo De Talheres Tramontina Churrasco Jumbo 12 Peças', 'Jogo De Talheres Tramontina Churrasco Jumbo 12 Peças Para saborear aquele churrasco especial com a família e os amigos, conte com o jogo para churrasco Tramontina Dynamic com lâminas em aço inox e cabos de madeira natural 12 peças. Desenvolvido para lhe proporcionar praticidade e beleza à sua mesa, ele tem peças produzidas com lâminas em aço inox, onde as facas tem maior durabilidade em seu fio de corte devido ao tratamento térmico e os garfos contam com maior resistência devido a estampagem. Seus cabos são em madeira natural e contam com rebites de alumínio que os deixam com um belíssimo design. Escolha seu corte de carne preferido e compartilhe sua mesa com a Tramontina! Descrição do produto Lâminas de aço inox As lâminas das facas têm maior durabilidade do fio devido ao tratamento térmico As lâminas dos garfos conta com maior espessura e uma estampagem do aço que garante maior resistência, evitando deformações Cabos de madeira natural Rebites de alumínio Antes da primeira utilização, lave bem as peças e seque-as Tenha cuidado ao manusear produtos cortantes e perfurantes e mantenha-os fora do alcance de crianças Para maior durabilidade dos produtos, recomenda-se secar bem antes de guardar Para descarte dos produtos e embalagens siga as orientações de reciclagem vigentes Peso Líquido: 0,7710 kg. Peso Bruto: 0,97 kg. Dimensões Embalagem (Compr. X Larg. X Alt.): 445x 270x 40 mm Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 264.89, 165.31, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/79147e98caacb56421a3e7b6afdd3739', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F15327147248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20561833850', 'Filtro Óleo Honda Wrv 1.5 2018 Wega', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação WR-V EX 1.5 FLEXONE 16V 5P AUT. 2018 WR-V EXL 1.5 FLEXONE 16V 5P AUT. 2018 Conteúdo Da Embalagem 1 Filtro de Óleo Tipo de Veículo para SUV''s e Caminhonetes Marca Fundada em 1969, a Wega Motors Brasil possui sede própria em Itajaí/SC, com uma moderna instalação que produz uma ampla gama de produtos para o mercado de reparação automotiva na linha leve e pesada. A Wega Motors é certificada em Sistema de Gestão da Qualidade ISO9001 – Versão 2000 (pelo BVQI – Bureau Veritas Certification), certificação essa que abrange a fabricação e comercialização de filtros de óleo, ar e combustível, velas e acessórios. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o filtro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 4 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7798001699219 Código do Fabricante WO120 WEG >', 13.98, 13.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkw-lltnb9bq1tnefd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20561833850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
