INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259691835', 'Maionese Tradicional Hellmanns', 'A Maionese Hellmann''s Tradicional é cremosa e perfeita para dar um toque especial aos seus lanches e refeições. Com Hellmann''s, você transforma seus pratos em momentos deliciosos, adicionando um sabor irresistível. * Sabor e cremosidade incomparáveis. * Ideal para sanduíches, wraps, hambúrgueres, molhos e saladas. * Possui ômegas 3 e 6 provenientes do óleo de soja. * Hellmann''s tem apenas 40 calorias por colher de sopa (12g).', 10.79, 10.79, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-825ak-mqnelm8vf5e5dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554820%2F58259691835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493092590', 'Kit 02 Berços Para Boneca Cristal Ursinho C02 Brinquedo Infantil Branco Rosa - Lyam Decor', 'Através das brincadeiras os pequenos desenvolvem ainda mais a criatividade, trabalham as interações sociais, a sensibilidade e o carinho com o próximo, faz parte da educação infantil e está diretamente ligado à formação emocional e física. Brincar de boneca é uma terapia e o Kit 02 Berços Para Boneca Cristal Ursinho C02 Brinquedo Infantil Branco Rosa - Lyam Decor vem para tornar esses momentos ainda mais divertidos! Acompanha colchãozinho, travesseiro e mosquiteiro, para o máximo aconchego da boneca. É produzido com materiais de excelente qualidade, conta com pintura atóxica, bordas arredondadas para maior proteção e possui certificação de segurança emitido pelo INMETRO (Instituto Nacional de Metrologia, Qualidade e Tecnologia). Estimular a imaginação das crianças proporciona uma infância feliz e prazerosa, aproveite e adquira já o seu! Dimensões do produto (L x A x P) 76 x 46 x 29 cm Medidas Internas: Largura interna do berço: 53 cm Profundidade interna do berço: 22 cm Largura externa do berço: 55 cm Altura do berço: 33 cm Altura da prateleira: 13 cm Largura da prateleira: 18 cm Profundidade da prateleira: 24 cm Comporta bonecas de até 53 cm. Características: Produzido com estrutura em MDP de 15mm. Pintura atóxico verniz U.V. Grades em madeira de qualidade. Produto na cor Branco Rosa. Acompanha mosqueteiro, véu, colchãozinho e travesseiro. Selo de aprovação do INMETRO. Cantos superiores arredondados e protegidos com borracha para maior segurança. Idade mínima recomendada de 3 anos. Produto enviado desmontado, acompanha todos os acessórios para montagem. Sistema de montagem com parafusos. A limpeza deve ser feita com pano levemente umedecido em água limpa, sem esfregar, não utilizar produtos abrasivos, desengordurantes, álcool ou solvente. Observações importantes: - Produto para uso residencial em ambiente interno, não devendo ficar exposto diretamente ao sol, calor e umidade excessivos. - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - As imagens são meramente ilustrativas, não acompanham objetos de decoração e eletrônicos. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento. - Montagem, desmontagem e outras instalações serão de responsabilidade do cliente. Não nos responsabilizamos, no ato da entrega, por subir escadas/elevadores ou pelo transporte por guincho em apartamentos. Eventuais despesas são de responsabilidade do comprador. - Confira as dimensões do produto e certifique-se de que passará normalmente por supostos elevadores, portas, escadas e/ou corredores de sua residência.', 375.9, 375.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd5g-lwd9yc83avz986', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1107280577%2F22493092590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598087924', 'Carrinho Bar Com Porta Taças Industrial Indy A03 Hanover Dourado - Lyam Decor', 'Seja para organizar os mais diversos objetos ou para dar aquele toque de modernidade na decoração, o Carrinho Bar Com Porta Taças Industrial Indy, da Lyam Decor, é combinação perfeita de tudo isso e muito mais. Com design escandinavo e toque industrial expresso nos pés metálicos, esse carrinho bar com gaveta é sinônimo de funcionalidade, já que podemos aproveita-lo como um aparador de madeira na sala de jantar, sala de estar ou até mesmo no corredor; aliás, que tal criar um cantinho do café moderno e cheio de personalidade?! Opções não faltarão. Basta usar a criatividade e dispor bebidas, taças, xícaras e até mesmo algum item decorativo. Aproveite agora mesmo e transforme o seu espaço com elegância. Adicione o Carrinho Bar Indy e surpreenda-se! Dimensões do Carrinho Bar (L x A x P) 110 x 85 x 40 cm Características do Carrinho Bar: Estrutura em MDP 15mm com acabamento BP e traseira em HDF 3mm com acabamento BP. Produto na cor Hanover e pés na cor Dourado, ambos fosco. 01 gaveta com corrediças telescópicas e aplique de tela sintética (PVC com poliéster). 01 prateleira inferior e 01 bandeja superior. Rodas fixas decorativas, não giram. Porta taças de aço na tonalidade dourado. Puxador em Madeira maciça de eucalipto. Pés de tubo metálico em aço e acabamento em pintura epóxi, as extremidades dos pés possuem ponteiras plásticas para evitar atrito do móvel com o piso. Peso máximo suportado 23 kg distribuídos. - A limpeza deve ser feita com pano levemente umedecido em água limpa, sem esfregar, não utilizar produtos abrasivos, desengordurantes, álcool ou solvente. Observações importantes: - Produto para uso residencial em ambiente interno, não devendo ficar exposto diretamente ao sol, calor e umidade excessivos. - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - As imagens são meramente ilustrativas, não acompanham objetos de decoração e eletrônicos. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento. - Montagem, desmontagem e outras instalações serão de responsabilidade do cliente. Não nos responsabilizamos, no ato da entrega, por subir escadas/elevadores ou pelo transporte por guincho em apartamentos. Eventuais despesas são de responsabilidade do comprador. - Confira as dimensões do produto e certifique-se de que passará normalmente por supostos elevadores, portas, escadas e/ou corredores de sua residência.', 1478.9, 1478.9, NULL, 'Home & Living > Tools & Home Improvement > Trollies', 'https://cf.shopee.com.br/file/br-11134207-820m3-moi6ybz0u2gz5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1107280577%2F23598087924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
