INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994066428', 'Arruinados pelo Amor de Deus: Jonas e Naum nos Ensinam Sobre Juízo, Graça e Restauração|Yago Martins', 'Arruinados pelo amor de Deus entrelaça arte e fé, revelando a conexão profunda entre a experiência estética e a busca por transcendência. Tomando como ponto de partida uma visita ao Museu do Louvre e a fascinante escultura do Torso masculino de Mileto, Yago Martins reflete sobre o poder da ruína, que, mesmo em sua incompletude, inspira transformação e nos convida a reconsiderar a vida. Sob essa ótica, Yago se propõe explorar as figuras bíblicas dos profetas Jonas e Naum, ressaltando a impossibilidade de escaparmos da presença divina e a urgência de mudança diante de um olhar que nos conhece verdadeiramente. Merece destaque seu convite a uma viagem aos tempos bíblicos, especialmente a Nínive, capital do antigo Império Assírio e palco de manifestação vigorosa do Deus que, ainda hoje, nos convoca à mudança e ao amor, mesmo em meio a um mundo marcado por violência e egoísmo. Arruinados pelo amor de Deus é mais que uma leitura; é alimento para a alma sedenta de transformação. 24x16 cm 272 Páginas', 55.9, 53.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rau3-maowlu2zewza2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23994066428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
