INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8751883076', 'Quebra Cabeça Multikids 3D Planetas com 100 Peças - BR1057', 'Montar Quebra Cabeça é uma brincadeira mais que divertida! É um momento de chamar os amigos, e familiares para ajudar a formar a tão esperada imagem da caixa, além de ser um processo educativo que auxilia no desenvolvimento das crianças e no trabalho em grupo. São 100 peças disponíveis para montar essa linda imagem dos planetas, não tem como não se encantar! Não perca tempo e garanta já o seu Quebra Cabeça da Multikids! Características - Marca:Multikids - Modelo: BR1057 Específicações Técnicas: - Funcionalidade: Divertir, estimular e desenvolver o raciocinio - Idade recomendada: A partir de 6 anos - Gênero: Meninos e Meninas - Participantes: 1 ou mais - Quantidade de Peças: 100 - Desenho Principal: Planeta Dimensões e Peso: - Dimensões (Embalagem A x L x C): 05 X 15 X 23 cm - Peso: 0,232 Conteúdo da embalagem: - Quebra Cabeça Multikids 3D Planetas com 100 Peças - BR1057', 61.37, 55.23, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/9ee5128549f7715354bfe7b0cd994c4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F8751883076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099068704', 'Socorro | O meu Marido é o Meu Pastor | Jani Ortlund', '“Ainda que ser a esposa de pastor não constitua um ofício na igreja, essa posição vem acompanhada por expectativas veladas e responsabilidades indefinidas. Ao passo que saber intimamente que a integridade do homem que está atrás do púlpito comporta bênçãos enormes, viver sob o constante e inalterável holofote pode cansar a alma. Uma esposa de pastor deve aprender a se alimentar da Palavra de Deus, oferecer a outra face, agarrar se a Cristo, abraçar os meios de graça, proteger os seus filhos de críticas e chamados que eles não escolheram e apoiar o seu marido, cujo chamado demanda que ele abdique de sua vida reiteradamente. E tudo isso é feito sob os olhares de todos. Uma esposa de pastor precisa de uma amiga confiável, e ela encontrará essa amiga no livro de Jani Ortlund. A sabedoria de Jani tem sido refinada por quase cinquenta anos como esposa de seu pastor. O seu estilo de escrita é simples, direto e sensato. Prático, penetrante e pessoal, este livro é como Jani sábio, tenro e, acima de tudo, fiel ao chamado de Cristo para ‘tomar parte nos seus sofrimentos’ (Fp 3.10). Eu amo este livro.” 14x21cm 134 Páginas', 43.9, 41.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbm2-lnzv1fqhhiit43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F21099068704', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
