INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256270302', 'Código Tributário Nacional - CTN de bolso - 2026 Rideel', 'Conheça o ProdutoDestaques: CTN: atualizado até a LC nº 227/2026 Atendendo aos anseios dos leitores por obras que tenham formato compacto, que permitam a rápida consulta ao texto legislativo plenamente atualizado e que, também, possuam baixo custo de aquisição, a Rideel criou a Coleção de Bolso. São livros que trazem o texto da Constituição Federal, dos principais códigos e da CLT em volumes independentes. Com diagramação pensada para proporcionar leitura agradável, notas remissivas elaboradas por especialistas em cada área, diversos facilitadores de consulta, como índice sistemático e detalhado índice alfabético-remissivo, são obras fundamentais para acadêmicos e operadores do Direito. A coleção abrange as principais áreas do Direito e é composta de 8 títulos: Constituição Federal, Código Civil, Código de Processo Civil, Código Penal, Código de Processo Penal, Código de Defesa do Consumidor, Consolidação das Leis do Trabalho, Código Tributário Nacional e Código de Trânsito Brasileiro. Tradição, qualidade editorial e preço acessível, esta é a Coleção de Bolso da Editora Rideel! Atualizações publicadas até 31-10-2026 disponíveis gratuitamente.', 34.5, 34.5, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/sg-11134201-825zx-mlfff2m6eeq0d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F58256270302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699364611', 'Balcão Bartira Cristal MDP 15mm com 2 Portas, 3 Gavetas e 1 Prateleira', 'O balcão Bartira Cristal é o módulo perfeito para compor a sua cozinha. Feito em MDP de 15mm de espessura, ele proporcionar um espaço muito especial para você manter diversos itens de cozinha muito bem armazenados e fáceis de encontrar. Equipado com porta de bater e gavetas com corrediças telescópicas em aço, esse móvel ainda dispõe em sua estrutura de puxador e pés em alumínio, acabamento em finish foil que possibilita maior vida útil ao produto e capacidade para suportar até 75kg bem distribuídos. Características Gerais: Feito em MDP 15mm Acabamento finish foil Tampo em laminado BP 20mm Porta de bater Gaveta para talheres e utensílios Corrediças telescópicas em aço Puxador em alumínio discretos e resistentes Sistema de dobradiças com amortecedor Peso suportado pelas gavetas: 5 Kg Medidas internas das gavetas: 10,3 x 31,5 x 42cm (AxLxP) Peso suportado pelo gavetão: 5 Kg Medidas internas do gavetão: 17,6 x 31,5 x 42cm (AxLxP) Pés em alumínio com niveladores- Peso suportado: até 75kg Quantidade de gavetas: 3 Quantidade de portas: 2 Quantidade de prateleira: 1 Tampo do balcão incluso: Sim Adaptável com pia: Não Acabamento: Fosco Dimensões: Altura (cm): 84 cm Largura (cm): 120,1 cm Profundidade (cm): 60,2 cm Garantia: 6 meses Atenção: Não nos responsabilizamos pela montagem ou instalação do produto. Foto meramente ilustrativa. Entrega do Produto: Não nos responsabilizamos pelo transporte por escadas/elevadores, guincho ou içamento deste produto. Orientamos que este produto seja montado por um técnico de sua confiança, após a sua entrega. Todas as instruções, manuais e peças necessárias para a montagem são fornecidas junto com o produto, não nos responsabilizamos pela instalação/montagem.', 659.0, 659.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mlhrmpf9ov0k24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F23699364611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
