INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14513258399', 'Caneta hidrográfica Fine Point 88/30 Laranja Palha Stabilo', 'A Caneta Stabilo Point 88 Fine Point 0,4mm é a escolha ideal para estudantes, profissionais, artistas e amantes de papelaria que buscam máxima precisão em seus traços. Reconhecida como a fineliner número 1 do Brasil, ela combina qualidade, conforto e um design icônico para proporcionar uma experiência de escrita e desenho incomparável. Seu famoso design hexagonal listrado é conhecido mundialmente e oferece excelente ergonomia durante o uso. A ponta extrafina de 0,4 mm permite criar linhas nítidas, detalhadas e precisas, sendo perfeita para escrita, desenhos técnicos, lettering, anotações, mapas mentais, contornos e ilustrações. A ponta revestida de metal garante maior resistência e durabilidade, além de permitir o uso com réguas, estênceis e outros instrumentos de precisão. Outro grande diferencial é sua alta proteção contra secagem: a caneta pode permanecer destampada durante o uso sem comprometer a qualidade da tinta. Disponível em uma ampla variedade de cores vibrantes, a Stabilo Point 88 é referência em desempenho, versatilidade e confiabilidade para o dia a dia. Principais Benefícios Traço extrafino de 0,4 mm para máxima precisão Fineliner número 1 do Brasil Design hexagonal listrado reconhecido mundialmente Ideal para escrita, desenho, lettering e trabalhos detalhados Ponta revestida de metal para maior resistência Compatível com réguas e estênceis Alta proteção contra secagem sem tampa Tampa ventilada para maior segurança Tampa com encaixe na extremidade da caneta Cores vibrantes e excelente desempenho Detalhes do Produto Modelo: Point 88 Fine Point Tipo: Caneta Fineliner Espessura do Traço: 0,4 mm Ponta: Revestida de metal Tampa: Ventilada e com encaixe traseiro Aplicação: Escrita, desenho, ilustração, lettering, estudos e trabalhos técnicos A Stabilo Point 88 é a caneta perfeita para quem busca precisão, durabilidade e acabamento profissional em cada traço. INMETRO 006320/2013', 21.88, 21.88, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-823rb-mpay39emtdlab0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F14513258399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200447362', 'Cama Box Conjugado Solteiro 88cm Supreme Gazin', 'O Cama Box Conjugado Solteiro 88cm Supreme Gazin oferece conforto e resistência ideais para o dia a dia. Seu revestimento superior e lateral em tecido plano evita o acúmulo de poeira e materiais orgânicos, facilitando a limpeza. Conta com camada de espuma cilíndrica laminada D20, espuma D28 e estrutura em madeira de reflorestamento, garantindo durabilidade e conforto. Um produto com excelente custo-benefício e acabamento em matelassê. Características: Camada de espuma cilíndrica laminada D20 Estrutura colchão espuma D28 Estrutura base em madeira de reflorestamento Pés em madeira 12cm Peso máximo suportado 90kg Pillow/Euro One face Matelassê em tecido plano Revestimento lateral e superior em tecido plano Selo Inmetro 008900/2024 Tampo base em TNT 50gr/m² Dimensões: Altura: 41 cm Largura: 88 cm Profundidade: 188 cm Peso: 22,25 kg Garantia do fornecedor de 3 meses.', 539.9, 449.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-821dj-mgsgoswjku161b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F58200447362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
