INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202441309', 'Centrífuga de Roupa Wanke Premium Plus 15kg', 'Centrífuga de Roupa Wanke Premium Plus 15kg, funcionalidade e eficiência se unem neste incrível produto que oferece capacidade para até 15kg de roupa molhada, ideal para famílias que precisam otimizar o tempo no dia a dia. Com três programas de centrifugação, ele garante um desempenho sob medida para diferentes tipos de tecidos, cuidando das peças com total delicadeza. O protetor de roupas proporciona ainda mais segurança durante o uso, enquanto o botão ergonômico facilita o manuseio, tornando o processo mais confortável. O timer de 5 minutos permite total controle do tempo de centrifugação e o suporte para fios contribui para a organização do ambiente. Características: Potência: 300W Consumo de energia por ciclo: 0,0022 KWH 3 programas de centrifugação Protetor de roupas Botão ergonômico Suporte para fios Capacidade para 15kg de roupa molhada Timer de 5 minutos Desliga automaticamente Reaproveitamento de água Exclusiva tampa de segurança Selo Inmetro:012140/2025 Dimensões: Altura: 70 cm Largura: 44 cm Profundidade: 42 cm Peso: 7,10 kg Garantia do fornecedor de 12 meses', 739.9, 669.9, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/sg-11134201-81zw8-miq7wz1chs027c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F58202441309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
