INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8370384263', 'Livro - O dia em que o mundo parou - Capa comum - Ciranda Cultural', 'As ruas ficaram vazias. Os parques foram fechados. Não houve mais encontro com amigos, nem abraços, nem brincadeiras. O mundo parou. O texto sensível e poético de Donaldo Buchweitz, com belas ilustrações de Márcia Menezes, traz a reflexão sobre o momento que passamos isolados, cada um na sua casa. Editora: Ciranda Cultural Edição: 1, 2020 Autor: Donaldo Walter Buchweitz Idioma: Português Páginas: 32 Dimensões: L 24.00 x A 24.00 x E 0.30 ISBN: 9786555002591', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/5fe6202d4df675cc669ed71b54b70349', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8370384263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
