INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40677834190', 'Box Dale Carnegie - Autoconfiança, Oratória e Produtividade - Desenvolvimento Pessoal', 'Aprimore suas habilidades pessoais e profissionais com este box exclusivo que reúne três obras clássicas de Dale Carnegie, autor mundialmente reconhecido por transformar vidas através da comunicação, da motivação e do desenvolvimento humano. • Como desfrutar a sua vida e o seu trabalho Descubra princípios simples e eficazes para encontrar mais satisfação, motivação e equilíbrio na rotina, cultivando uma vida mais leve e significativa. • Como desenvolver autoconfiança e influenciar pessoas falando em público Aprenda a eliminar o medo de se apresentar, fortalecer sua presença e transmitir ideias com clareza, segurança e impacto. • A maneira rápida e fácil de falar com eficácia Um guia prático para aprimorar a comunicação em reuniões, conversas, discursos e situações do dia a dia — tornando você mais persuasivo e assertivo. Por que este box é perfeito para você? - Técnicas aplicáveis imediatamente - Conteúdos que fortalecem autoconfiança e comunicação Ideal para profissionais, estudantes e líderes Excelente opção de presente Desenvolva sua voz, sua presença e sua qualidade de vida com os ensinamentos atemporais de Dale Carnegie. Editora: Principis Edição: 1, 2026 Autor: Dale Carnegie Idioma: Português Páginas: 656 Dimensões: L 15.70 x A 23.00 x E 4.00 ISBN: 7908312135768 Coleção: Não se aplica Linha Editorial: Principis - Desenvolvimento pessoal Faixa Etária: + 14 anos Assuntos (tags): Autoajuda, Crescimento espiritual, Inspiração, Vida, Desenvolvimento pessoal, Autodesenvolvimento, Trabalho, Disciplina, Decisões, Desfrutar, Propósito, Carreira, Procrastinar, Aumento de confiança , Entusiasmo, Gratidão, Prazer, Talentos escondidos, Satisfação BISAC: Autoajuda / Autoajuda / Crescimento Pessoal Linha de Produto: Box Principis Encadernação: Não se aplica Acabamento: Não se aplica Material: Papel', 74.9, 49.9, NULL, 'Books & Magazines > Books > Psychology & Relationships', 'https://cf.shopee.com.br/file/sg-11134201-8260p-mj715125oah251', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F40677834190', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
