INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20147521437', 'Talco Desodorante Tabu Tradicional 100G', 'Talco Desodorante Tabu, a proteção que sua pele merece.🌸 Experimente o frescor e o cuidado do Talco Desodorante Tabu Tradicional 100g! Com uma fórmula suave e delicada, ele proporciona uma sensação de limpeza e frescor o dia todo, deixando a sua pele suavemente perfumada com um aroma único e marcante. Transforme sua rotina com o frescor Tabu e sinta-se confiante o dia todo! ✨ Benefícios: ✅ Pele suavemente perfumada: Sinta a suavidade e o frescor com uma fragrância que dura o dia inteiro. ✅ Proporciona frescor e bem-estar: Ideal para manter a sensação de frescor, mesmo nas horas mais intensas. ✅ Previne e elimina o mau odor: Combate o mau cheiro, deixando sua pele livre de odores indesejáveis. ✅ Dermatologicamente testado: Seguro para todos os tipos de pele. Perfeito para o uso diário, o Talco Desodorante Tabu é a escolha certa para quem busca frescor e proteção com um toque de sofisticação. Modo de Uso: 1️⃣ Aplique o talco nas axilas, pés ou qualquer área do corpo que necessite de proteção extra contra odores. 2️⃣ Use após o banho ou sempre que sentir necessidade de frescor. 3️⃣ Aplique uma quantidade generosa e massageie até total absorção. COMPOSIÇÃO: Talc, Triclosan, Parfum, Benzyl Alcohol, Benzyl Benzoate, Benzyl Salicylate, Citral, Citronellol, Coumarin, Limonene, Eugenol, Geraniol, Hexyl Cinnamal, Hydroxycitronellal, Linalool.', 19.99, 12.29, NULL, 'Beauty > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/b6557ad8d40f967eef9353c23edbf05d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436104412%2F20147521437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
