INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15993784152', 'Radio Mp3 Com Suporte Celular Blutetooh E Carregador 2 Usb', 'Você está procurando por um aparelho de som automotivo inovador para deixar seu carro completo de verdade? Conheça Radio Seven com suporte para acoplar o celular e curtir as viagens com muito mais diversão. O MP3 Player é compatível com smartphones Android e iOS. Com ele, você vai ter acesso aos aplicativos de navegação e música do seu celular. O aparelho tem 2 entradas USB, sendo que uma delas é para carregamento rápido de celular, Bluetooth para ligações e streaming de músicas, equalizador e sintonização de rádio AM e FM. Toda a tecnologia está ao seu alcance. Aproveite! RÁDIO MP3 PLAYER COM SUPORTE PARA CELULAR +2 ENTRADAS USB MARCA SEVEN PARTS Entrada USB/SD. Entrada AUX. Função Bluetooth. Suporte formato MP3/WMA. Memória para 18 estações de rádio. Equalizador predefinidos (Pop/Rock/Classic/Jazz/Flat). Equalizador custom (Agudo/Grave) Funções (Pause/Repetição/Reprodução Aleatória/Mudança de Pastas). Função Reset. 4 saídas RCA. Potência de saída 4x50w. Personalização painel de até 7 cores. Dissipador de calor.', 141.38, 120.18, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lgmqyj49o0qe48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F15993784152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
