INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57460324230', 'Religião Estranha | Como os Primeiros Cristãos Eram Esquisitos, Perigosos e Cativantes | Nijay Gupta', 'Os primeiros cristãos eram estranhos! Na sociedade romana, os primeiros cristãos se destacavam pela estranheza de suas crenças e práticas. Eles acreditavam em coisas incomuns: adoravam um Deus invisível, não tinham templos físicos nem ofereciam sacrifícios em seus cultos, chamavam uns aos outros de irmãos, “comiam” do corpo e “bebiam” do sangue de Cristo, além de tantas outras condutas que seriam consideradas bizarras e perigosas em comparação com outras religiões do mundo antigo. Neste livro, Nijay K. Gupta nos leva ao mundo greco-romano, mergulhado nas práticas de paganismo, idolatria e superstições, para revelar por que os cristãos eram vistos como perigosos, subversivos e, ao mesmo tempo, magnéticos. A obra mostra como uma pequena seita judaica impactou o poderoso Império Romano por meio de sua vida cotidiana e como o cuidado com órfãos, doentes, idosos, escravos e outros considerados improdutivos gerou a estranheza que moldou o coração da fé cristã. Gupta combina, com profundidade, o melhor da teologia do Novo Testamento com os desafios da igreja do século 21, mostrando como o exemplo dos primeiros cristãos pode oferecer modelos de engajamento e esperança aos crentes de hoje. 21X14 CM 240 Páginas', 47.9, 40.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-820o9-mo4pt8qoyghvf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F57460324230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44751775811', 'Jejum Digital | Uma Jornada de desintoxicação digital e reconexão com o Criador', 'Descubra uma jornada transformadora de desintoxicação digital com este livro essencial da Penkal. Em 212 páginas repletas de sabedoria prática, você encontrará um guia completo para recuperar o equilíbrio entre a tecnologia e sua vida espiritual. Com dimensões de 15x21cm, este livro oferece uma abordagem fundamentada em princípios bíblicos para ajudar você a reconquistar o controle sobre seu tempo, pensamentos e relacionamentos. A obra propõe exercícios práticos e reflexões profundas para estabelecer limites saudáveis com dispositivos digitais, restaurar momentos de silêncio e fortalecer sua conexão com Deus. Ideal para quem busca usar a tecnologia com sabedoria sem perder o foco no que realmente importa. O conteúdo é apresentado em linguagem acessível e estruturado em capítulos que abordam desde o estabelecimento do silêncio até a renovação da esperança, proporcionando uma experiência de leitura que combina aprendizado prático com crescimento espiritual. 14x21cm 212 Páginas', 30.99, 25.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821d5-mh9k10zvyxanb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F44751775811', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
