INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48753112513', 'Scottini Descripto | N.1012 | Difícil', 'Descripto é uma abordagem criativa para exercitar a associação de palavras e símbolos, ampliando sua lógica. Cada enigma solucionado é um passo em direção a uma mente mais ágil e imaginativa. Demonstre suas habilidades e supere os desafios! Vamos nessa! Os caça-palavras contém assuntos diversos relacionados a cultura, tecnologia, ciência, arte...A questões exercitam nosso cérebro trazendo questões da atualidade e do passado, fazendo nosso córtex trabalhar toda a área da memória. Essa dinâmica de construção traz benefícios de longo prazo, fazendo nosso cérebro rejuvenescer. 21x14 cm 96 Páginas', 11.9, 6.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-822x2-mi9lt3vc5u6afc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F48753112513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48106358309', 'Box Dale Carnegie | Autoconfiança, Oratória e Produtividade | 3 Livros de Desenvolvimento Pessoal', 'Aprimore suas habilidades pessoais e profissionais com este box exclusivo que reúne três obras clássicas de Dale Carnegie, autor mundialmente reconhecido por transformar vidas através da comunicação, da motivação e do desenvolvimento humano. Como desfrutar a sua vida e o seu trabalho Descubra princípios simples e eficazes para encontrar mais satisfação, motivação e equilíbrio na rotina, cultivando uma vida mais leve e significativa. Como desenvolver autoconfiança e influenciar pessoas falando em público Aprenda a eliminar o medo de se apresentar, fortalecer sua presença e transmitir ideias com clareza, segurança e impacto. A maneira rápida e fácil de falar com eficácia Um guia prático para aprimorar a comunicação em reuniões, conversas, discursos e situações do dia a dia - tornando você mais persuasivo e assertivo. Por que este box é perfeito para você? - Técnicas aplicáveis imediatamente - Conteúdos que fortalecem autoconfiança e comunicação Ideal para profissionais, estudantes e líderes Excelente opção de presente Desenvolva sua voz, sua presença e sua qualidade de vida com os ensinamentos atemporais de Dale Carnegie. 656 páginas 16x23 cm', 51.9, 46.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82615-ml2c9oztlwcj14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F48106358309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798637993', '365 Palavras cruzadas plus - volume IV', 'Fazer palavras cruzadas é uma forma criativa e divertida de desenvolver o raciocínio, deixar o pensamento mais ágil e enriquecer o vocabulário, além de você se manter atualizado sobre diversos assuntos. 15x22cm 288 Páginas', 17.95, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rau1-maxd79qyc5xf04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23798637993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
