INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298164041', 'Parafusadeira Furadeira de Impacto 20V com 2 Baterias de Lítio 1.5Ah Hawk', 'LOJA WEHAWK - OFICIAL⭐ PARAFUSADEIRA E FURADEIRA DE IMPACTO 20V HAWK ✅Furadeira de impacto com 3 funções ✅ Ferramenta sem fio, com bateria de maior duração. ✅ Acompanha maleta de acessórios com 2 baterias.🔋🔋 Ferramenta com maior potência para os apertos mais difíceis e para furar paredes. Produto sem fio, a bateria, para utilizar de forma portátil e sem ficar preso a tomada! Com 20V, ela tem muito mais força e consegue perfurar com maior facilidade os materiais mais resistentes, como concreto. MALETA DE ACESSÓRIOS • 1 Jogo de Ponteira; • 6 Chaves; • 1 Socket Magnético para chaves; • 6 Brocas; • 1 Extensor Flexível; • 2 Bateria 20V 1500MAH ESPECIFICAÇÕES ⭐ Marca: Hawk 🔋Bateria: 20v 1500mAh li-ion ⚡Frequência: 60Hz 🔌Tensão do Carregamento: Bivolt 🕑Tempo de Carregamento: De 2 a 3 Horas ⚡2 Velocidades: 0-400 / 0-1400rpm 🔩Capacidade de Perfuração: Madeira 30mm / Aço 15mm ✅Capacidade do Mandril: 3/8"" - 10mm 🔦LED de Iluminação ✊Empunhadura Emborrachada', 233.79, 233.79, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbmx-m5err4u859x0d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F919559444%2F23298164041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792246234', 'CREME PARA CABELO TRIM LAVANDA SUAVE MEN 65G', 'O Creme Trim foi desenvolvido para o tratamento dos cabelos. Ele ajuda a combater o ressecamento e mantém os cabelos sempre bonitos e hidratados todos os dias. Com uma suave fragrância de lavanda, o creme Trim ajuda também a reduzir o frizz e a proporcionar um brilho intenso e mais maciez aos seus cabelos. Beneficios - Combate o ressecamento - Cabelos bonitos e hidratados diariamente - Possui textura de pomada - Reduz o frizz nos cabelos - Suave fragrância de lavanda - Brilho intenso e maciez aos cabelos Como usar O creme Trim é bastante simples de usar. Com os cabelos úmidos, basta aplicar uma pequena quantidade do produto e massagear, modelar ou pentear.', 39.99, 29.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-824ge-mepynucmywox11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F23792246234', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
