INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498891027', 'Kit 4 Desodorante Antitranspirante Aerosol Feminino Rexona Powder Dry 72 horas 150ml', 'Desodorante Antitranspirante Aerosol Feminino Rexona Powder Dry 72 horas • A exclusiva fórmula do Desodorante Aerosol Feminino Rexona Powder Dry garante 72 horas de proteção contra o suor e o mau odor ativado pelo movimento • O desodorante antitranspirante aerosol Powder Dry a mantém seca, refrescada, protegida e confiante para encarar qualquer situação • Desodorante feminino fácil de usar: agite e aplique nas axilas a não menos de 15 cm da pele • A fragrância desse antitranspirante contém uma combinação única de jasmim e baunilha, garantindo a sensação de frescor durante o dia inteiro. • Esse desodorante antibacteriano não contém álcool* e não afeta a camada de Ozônio, sua lata é de alumínio 100% reciclável, feito com energia elétrica 100% renovável • O Desodorante Aerosol Feminino Rexona Powder Dry permite que você fique sempre protegida, não importa o que aconteça. Rexona não te abandona Mais uma vez Rexona se supera e relança sua linha de desodorantes com uma fórmula inovadora, o Desodorante Aerosol Feminino Rexona Powder Dry combina um novo e exclusivo ativo antitranspirante com a tecnologia de fragrâncias encapsuladas. Esse desodorante antitranspirante aerosol a mantém protegida por até 72 horas, ativado pelo seu movimento e a deixa muito mais confiante para você encarar qualquer desafio. Com o registro de 16 patentes e mais de 300 testes técnicos, está comprovado que essa nova tecnologia antitranspirante entrega um nível de proteção contra o suor como nenhuma outra proposta regular já entregou antes. A nova e exclusiva fórmula de Rexona Powder Dry trabalha com um sistema de partículas menores e mais estáveis que formam uma barreira protetora mais resistente e duradoura contra a transpiração e o mau odor, mantendo você seca, refrescada e protegida a cada novo movimento e por muito mais tempo. Sua fragrância contém uma combinação única de jasmim e baunilha, garantindo a sensação de frescor durante o dia inteiro. A lata usada no desodorante é feita de alumínio 100% reciclável, e o produto é feito com energia elétrica 100% renovável, não contém álcool* e não afeta a camada de ozônio. Experimente também outros produtos da linha de desodorantes aerosol femininos Rexona e se sinta sempre protegida durante qualquer atividade, porque Rexona não te abandona! *Não contém álcool etílico', 69.16, 69.16, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-823r7-mojps8lwntal61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23498891027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
