INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204088346', 'CeraVe para Pele Seca a Extra Seca - Creme Hidratante Facial e Corporal Sem Perfume 50g', 'Creme hidratante facial e corporal para peles secas e ressecadas. CeraVe para Pele Seca a Extra Seca é ideal para hidratar profundamente e fortalecer a barreira natural da pele. O Creme Hidratante Facial e Corporal CeraVe para Pele Seca a Extra Seca é um hidratante de alta performance. Formulado para combater a secura e o ressecamento, CeraVe creme hidratante proporciona um alívio imediato e duradouro, deixando a pele macia e suave. CeraVe Creme Hidratante Facial e Corporal Sem Perfume para Pele Seca e Extra Seca é enriquecido com três ceramidas essenciais e Ácido Hialurônico, ativos poderosos que atuam em sinergia para restaurar a elasticidade da pele. Sua fórmula única reforça a barreira cutânea, impedindo a perda de água e proporcionando uma hidratação intensa e duradoura. Experimente CeraVe creme e desfrute de uma pele hidratada, saudável e radiante. Fórmula não comedogênica, hipoalergênica, livre de óleo, sem perfume e não irritante. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 49.9, 49.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-8262y-mjzyi3op7daba0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204088346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
