INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25595532826', 'CAIXA ACUSTICA PCX4800 Flash Light 380w Preto Philco', 'A Caixa de Som Amplificada Philco deixa suas confraternizações ainda melhores graças ao Flash Lights, sistema de luzes com diferentes modos de iluminação. Som de qualidade por muito mais tempo! A bateria interna recarregável tem duração de até 8h, com alto desempenho e muito mais tempo de utilização. A potência de 380W da Caixa de Som Philco permite que alcance uma excelente performance em qualquer ambiente. Através da conexão Bluetooth 5.3, você conectar seu dispositivo móvel com alto poder de resposta e estabilidade. Melhore sua experiência com a melhor conectividade! Conta ainda com função TWS, que possibilita a conexão com duas Caixas de Som PCX4800 sem a utilização de fio, aumentando ainda mais a potência e diversão nas suas festas. E o melhor? Possui IPX-5, que protege contra jatos de água de baixa pressão. E não para por aí! A Caixa de Som Amplificada Philco PCX4800 tem Bluetooth, entrada auxiliar para fone e microfone e USB! Da batida eletrônica aos acordes calmos de um piano, conte com a Caixa de Som Amplificada 380W Flash Lights Philco PCX4800! Potência 380W Bluetooth 5.3 Woofer 8 “ e Tweeter Tweeter Flash light Entrada de Alimentação AC 127V/220V Bateria Interna de Li-Ion 7,4V 2000mAh USB: Entrada USB para reprodução de músicas. Entrada auxiliar de áudio P2 Entrada para microfone Função TWS LED indicador de bateria Função EX Bass Proteção IPX5 Autonomia de 8h com volume em 50% e luzes desligadas Estamos à disposição para esclarecer qualquer dúvida. Atenciosamente, Equipe NegociuN!', 1158.35, 567.9, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mamqj1634w3z1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F13433