INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493188681', 'Creme de Pentear para Cachos Levíssimo 1l bn.Cachos (4 itens)', 'O Pentear Levíssimo (1000ml), da linha bn.CLÁSSICOS, auxilia na definição dos cachos e crespos, e protege a fibra capilar dos danos causados pela poluição e por radicais livres. O produto é indicado para quem gosta de fios definidos e com um acabamento leve e solto, que não pese nos cabelos. A linha bn.CLÁSSICOS reúne os produtos mais queridinhos e famosos do bn.Cachos para o cuidado diário dos cabelos tipo 3ABC e 4ABC. Ingredientes Fórmula exclusiva com Óleo de Gardênia, Vitamina E, que oferece uma ação anti oxidante, e óleo de coco. O mix desses ingredientes proporciona maior desembaraço, nutrição e definição dos fios crespos e cacheados. Composição ÁGUA PURIFICADA, CLORETO DE CETRIMÔNIO, ÁLCOOL ETÍLICO, GLICEROL, ÁLCOOL CETOESTEARÍLICO, CORANTE AMARELO 15985, ÓLEO MINERAL, VASELINA SÓLIDA, ÁCIDO CÍTRICO, FENOXIETANOL, METILPARABENO, BUTILPARABENO, ETILPARABENO, PROPILPARABENO, FENILTRIMETICONE, ÓLEO DE COCO, EXTRATO DA FLOR DE GARDENIA DO TAITI, DEXTROALFATOCOFEROL, BUTIL-HIDROXITOLUENO, FRAGR NCIA (ALFA-ISOMETIL IONONA, AMIL CINAMAL, SALICILATO DE BENZILA, BUTILFENIL METILPROPIONAL, CITRONELOL, CUMARINA, HEXIL CINAMAL, HIDROXIISOHEXIL 3-CICLOHEXENO CARBOXALDEÍDO, LIMONENO).', 287.99, 177.39, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rdys-ly60naiyrpf846', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F22493188681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794677613', 'Kit Martelinho De Ouro Kit Ventosa P/ Desamassar', 'Kit Martelinho De Ouro Kit Ventosa P/ Desamassar Indicadas para profissionais da área de martelinho de ouro. Usadas em conjunto com Cola em Bastão e Repuxador Manual para Martelinho de Ouro. Possuem desenho e ângulo de contato projetados para melhorar o repuxo da lata. ITENS INCLUSOS: 5 Peças de Ventosa ** Não Acompanha Cola E Repuxador. Somente as Ventosas COR: Amarelo DIMENSÕES: 2un Oval, sendo 1un 30x20mm e 1un 40x25mm 3un Redondas, sendo o diâmetro de cada: 16mm, 21mm e 26mm MARCA: Vonder', 24.99, 24.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh28xpnkb30kca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F938446605%2F23794677613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197916887', 'Kit 12 unidades - Gel Lubrificante Íntimo K-med 2 Em 1 200ml', 'K-Med 2 em 1 Gel Lubrificante Íntimo e Gel de Massagem O K-Med 2 em 1 Gel Lubrificante Íntimo e Gel de Massagem é desenvolvido à base de água e vitamina E, proporcionando mais conforto, segurança e prazer durante a relação sexual. Serve tanto como lubrificante íntimo quanto como gel de massagem corporal. Pode ser usado com preservativos, sendo uma opção versátil e eficaz para momentos íntimos. Benefícios: Lubrificante íntimo e gel de massagem à base de água. Sem fragrância, facilmente removível. Pode ser usado com preservativos. Sem contraindicações. Modo de Uso: Como gel de massagem: Aplicar sobre a região desejada sempre que necessário. Não há restrição de uso em relação à frequência e à quantidade. Pode ser usado durante a relação sexual ou quando houver necessidade de lubrificação íntima adicional. Recomendações e Orientações: Não danifica o látex, podendo ser aplicado sobre o preservativo ou na região genital. Uso externo. Não é contraceptivo e não contém espermicida. Evitar contato com os olhos. Em caso de irritação ou incômodo, suspender o uso e consultar um médico. Em caso de gravidez, consultar um médico antes de usar o produto. Contraindicado para uso em áreas lesionadas. Proibido reprocessar. Testes Realizados: Dermatologicamente testado, ginecologicamente testado, clinicamente testado.', 316.39, 209.9, NULL, 'Health > Sexual Wellness > Lubricants', 'https://cf.shopee.com.br/file/sg-11134201-7rdx1-m18c182c67q6b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23197916887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398659846', 'BODY SPLASH FEMININO AURA 200ML - PRIMACIAL PERFUME ABAUNILHADO', 'Body Splash Aura 200ml Perfume Feminino Floral | Perfume Feminino Gourmand Uma fragrância envolvente, elegante e confortável, que combina a suavidade das notas florais com um toque cremoso e levemente adocicado. A baunilha aparece de forma delicada, equilibrada com notas aromáticas, criando um aroma sofisticado, feminino e fácil de agradar. Perfeito para quem quer um perfume doce na medida certa, nem enjoativo nem simples, ideal para o dia a dia com um toque de elegância. Pirâmide Olfativa: Topo: Gengibre Coração: Lavanda Fundo: Baunilha Quando Usar: 🌤️ Dia: Excelente 🌙 Noite: Muito bom 🌸 Melhor em clima ameno e dias mais frescos 📦 Detalhes do Produto: ✔ Conteúdo: 200ml ✔ Body splash feminino floral e levemente doce ✔ Fixação leve a moderada ✔ Ideal para reaplicar ao longo do dia ✔ Fragrância elegante e confortável 💡 Dica de uso: Aplique após o banho e reaplique ao longo do dia para manter a pele sempre perfumada e destacar o fundo cremoso da fragrância.', 69.9, 45.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820m7-mm0ga7dwexacc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F23398659846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13468614431', 'Paleta Iluminador PhálleBeauty 3 Cores PH0319', 'Iluminador PhálleBeauty PH0319 Paleta Iluminador PhálleBeauty 3 Cores deixe o seu rosto radiante e realçado com aspecto natural e suave. Perfeito para destacar áreas específicas da face e assim, deixar seu formato mais valorizado. Como Usar Paleta Iluminador PhálleBeauty 3 Cores Conselho de Aplicação Com um pincel, pegue o iluminador de sua escolha e aplique nos pontos altos do rosto, como ponte do nariz, têmporas, alto das maçãs, e arco do cupido. Nossos Experts Ensinam Para que a iluminação tenha um efeito natural, é preciso que a pele esteja hidratada antes da aplicação da maquiagem. Por isso, mantenha sua rotina diária de hidratação facial para que a make fique impecável.', 19.99, 19.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/aac5416dd20c2b5d951cf531a934ca31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F13468614431', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
