INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11646847459', 'Colar elementos do mar 45cm Prata 925', 'Apresentamos o deslumbrante Colar Elementos do Mar em Prata 925 de 45cm, uma peça encantadora que traz consigo a beleza e a magia do oceano. Este colar é perfeito para os amantes do mar e suas criaturas maravilhosas. O colar apresenta três encantadores pingentes: uma concha, búzios e uma estrela-do-mar. Cada um desses elementos do mar é minuciosamente trabalhado em prata 925, um metal precioso conhecido por sua qualidade excepcional e brilho duradouro. O acabamento polido realça o brilho natural da prata, conferindo ao colar uma aparência elegante e sofisticada. A combinação desses elementos do mar cria uma composição harmoniosa e encantadora, simbolizando a conexão com o oceano e sua vasta vida marinha. O colar é uma maneira especial de expressar seu amor pela natureza marítima e sua beleza única. Com seu comprimento de 45cm, o colar fica perfeitamente posicionado no seu colo, adicionando um toque de estilo e elegância ao seu visual. Ele é uma escolha versátil, adequada para uso diário ou para ocasiões especiais, adicionando um toque de encanto marinho a qualquer look. Adquira hoje mesmo o Colar Elementos do Mar em Prata 925 de 45cm e traga consigo a beleza e a energia do oceano. Seja para uso pessoal ou como um presente especial, este colar é uma escolha encantadora. Use-o com orgulho e deixe que ele seja um reflexo do seu amor pela vida marinha e pela natureza exuberante.', 182.9, 112.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-ly17dzwtnn0sd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F11646847459', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50313619948', 'Comic - Invencível Vol. 15 - Novo/Lacrado', 'Invencível Vol. 15 Mark Grayson se vê em uma encruzilhada: enfrentar as batalhas de frente é sempre a melhor solução para as maiores ameaças do mundo ou existe uma maneira melhor? Segmentos: Comics Marcas: Panini Autor(es): Robert Kirkman, Ryan Ottley ISBN: 9786525952444 Check-List: Maio/2026 Classificação Etária: 16 anos Editora: Panini Indicação: Jovens Maduros - Ensino Médio/Universitário Número de páginas: 144 Tipo de capa: Capa Cartão Data de Lançamento: 21/05/2026 Idioma: Português Condição: Novo/Lacrado', 53.9, 53.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-825aj-mqerdfz654hue2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F50313619948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29932416132', 'Mini Calculadora De Bolso Matemática Plástica De 8 Dígitos Portátil De Alta Qualidade', 'A Mini Calculadora de Bolso Matemática Plástica de 8 Dígitos Portátil de Alta Qualidade é uma excelente opção para quem precisa de um dispositivo prático e funcional para cálculos rápidos. Compacta e leve, ela cabe facilmente no bolso ou na bolsa, sendo ideal para levar a qualquer lugar, seja no trabalho, escola ou no cotidiano. Com display de 8 dígitos, ela oferece uma leitura clara para realizar cálculos simples de forma eficiente. Fabricada com material plástico de alta qualidade, garante durabilidade e resistência, suportando o uso diário. Seu design compacto e portátil a torna uma ferramenta conveniente e confiável, perfeita para quem precisa de algo pequeno e de fácil acesso.', 24.9, 23.9, NULL, 'Stationery > School & Office Equipment > Calculators', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8akw1lne48h86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F29932416132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
