INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57108137825', 'Capa Mole + 60 Envelopes (420 Figurinhas) Álbum Copa do Mundo 2026 - Oficial Panini', 'Copa do Mundo 2026 Álbum Capa Mole + 60 Envelopes(420 Figurinhas) Este Kit contém: 1 Álbum Capa Mole + 60 Envelopes - cada envelope contém 7 figurinhas, totalizando 420 figurinhas Prepare-se para viver a maior Copa do Mundo de todos os tempos! A Coleção Oficial Panini FIFA World Cup 2026 chegou para registrar cada capítulo dessa jornada histórica. Pela primeira vez com 48 seleções e disputada em três países - Canadá, México e Estados Unidos -, esta é a maior coleção já produzida na história dos mundiais! São 112 páginas repletas de adrenalina e 980 figurinhas para colecionar, incluindo figurinhas especiais com efeito metalizado, estádios, cidades-sede e os craques que prometem brilhar nos gramados. Cada envelope agora vem com 7 figurinhas, garantindo ainda mais emoção a cada abertura. Comece agora sua coleção, convoque os amigos para as trocas e complete o guia definitivo do maior espetáculo da Terra! Seja você um colecionador veterano ou um iniciante, o Álbum da Copa 2026 é o seu passaporte para o evento esportivo mais assistido do planeta. Não fique de fora dessa tradição! Segmentos: Colecionáveis, Colecionáveis - Esportes Marcas: Panini Editora: Panini Data de Lançamento: Maio/2026 Idioma: Português Condição: Novo/Lacrado', 468.32, 421.49, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/sg-11134201-81zts-mmkmvttgjf9hca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F57108137825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497988998', 'Volante Esportivo Ford Ka Fiesta Courrier Escort Zetec', 'Oferecemos durabilidade e resistência incomparáveis. Nosso volante foi projetado para oferecer máxima segurança, garantindo aderência firme e conforto, proporcionando controle absoluto em todas as suas viagens. CONTEÚDO DA EMBALAGEM: • Volante Esportivo Personalizado; • Diâmetro de 350mm; • Cubo Adaptativo; • Emblema; • Parafusos para instalação. COMPATIBILIDADES: • Ford Escort Zetec 1997 À 2003 • Ford Fiesta 1978 À 2022 • Ford Ka 1997 À 2021 • Ford EcoSport 2003 À 2022 • Ford Courier 1997 À 2013 EXCLUSIVIDADE • Qualidade superior em poliuretano: Volantes com toque macio, controle preciso e resistência excepcional, graças ao poliuretano de alta tecnologia e cubos metálicos que garantem segurança e durabilidade. • Personalização única: Volantes em diversas cores e compatibilidades, ideais para realçar o estilo e a personalidade do seu carro. • Atendimento especializado: Se não encontrar seu modelo em nossa descrição, entre em contato com nossa equipe e nós ajudaremos a encontrar a solução ideal para você. IMPORTANTE: • Verifique a compatibilidade do anúncio com seu veículo. Tire suas dúvidas ANTES da compra. • Entrega rápida: Compras realizadas hoje serão despachadas no próximo dia útil. • Recomendamos a instalação por um profissional. • A instalação dos nossos volantes resulta na perda da funcionalidade do airbag. Eleve a experiência ao dirigir com nossos volantes.', 399.98, 207.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdxi-m1mutlprpwzh7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401494968%2F22497988998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
