INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697369156', 'Gin Tanqueray London Dry 750ml', 'Características Principais do Produto: Marca: Tanqueray Pais de Origem: Inglaterra Graduação Alcoólica: 47,3% Volume: 750ml Tipo de Garrafa: Vidro Temperatura ideal: Temperatura ambiente ou com gelo Departamento: Destilados Categoria: Gin Informações Adicionais do Produto: O Gin Tanqueray London Dry é o gin mais premiado da categoria. Charles Tanqueray criou essa receita em 1830 depois de experimentar várias combinações até encontrar o equilíbrio perfeito entre seus botânicos preferidos, como o zimbro, semente de coentro, raiz de angélica e alcaçuz. O Gin London Dry Tanqueray é o preferido dos bartenders dos 50 melhores bares do mundo para fazer o tradicional e premiadíssimo gin tônica, uma bebida símbolo de sofisticação e refrescância. "É proibida a venda e o consumo de bebidas alcoólicas para menores de 18 anos. Se beber não dirija." Fornecedor - Diageo Brasil Ltda', 104.6, 91.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-824j3-mpibj4853vnmdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F20697369156', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993619908', 'Caixa Térmica Termolar SUV 3500 Rosa 8L', 'Características do Produto: Marca: Termolar Acabamento: Lisa Capacidade: 8L Conservação Térmica: 10h frio / 20h com gelo Isolamento Térmico: Poliestireno Expandido (EPS) Livre de BPA: Sim Material Atóxico: Sim Material Externo: Plástico EAN: 7891023584430 Informações Adicionais do Produto: A nova caixa térmica da Termolar, que une design funcional, praticidade e inovação em um formato compacto. Tem capacidade para até 12 latas de 350 ml, 9 garrafas de 330 ml ou 8 latões de 473 ml. Sua tampa reversível vira uma mesinha com porta-copos e porta-celular, e o estojo para utensílios traz ainda mais praticidade. Com conservação térmica diferenciada, mantém até 9 horas de frio sem uso de gelo para alimentos e até 20 horas de frio com uso de gelo para bebidas. A tecnologia AirFlow permite a circulação de ar pela base sem contato com o piso, garantindo eficiência térmica. A alça retrátil com trava de segurança facilita o transporte e proporciona mais estabilidade, tornando a SUV 8 L a companheira perfeita para seus passeios, viagens e aventuras do dia a dia. Garantia: 10 Meses, oferecida pelo Fornecedor. Fornecedor: Termolar S/A', 84.0, 82.9, NULL, 'Sports & Outdoors > Others', 'https://cf.shopee.com.br/file/sg-11134201-824hs-mpia9aw02brh5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23993619908', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
