INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16160424046', 'Módulo Soft Rebatimento de Retrovisores + Tilt Down Universal', 'O modulo de rebatimento com tilt down é a melhor opção para você garantir praticidade e segurança em seu dia a dia, assegurado com a função tilt down, que é acionada ao engatar a ré, inclinando o espelho retrovisor para o melhor ângulo. Especificações Técnicas: • Recolhe os Espelhos ao Ligar o Alarme (Rebatimento) • Após Engatar a Marcha Ré, Realiza a Manobra Tilt Down, Inclinando o Ângulo do Espelho Elétrico do Passageiro para Permitir Visão do Ponto Cego na Área de Manobra da Ré • Ao Desengatar a Marcha Ré, Retorna Automaticamente o Espelho para a Posição Original de Direção • Função Semi Automática • Aplicação Universal • Fácil Instalação Aplicação: • Universal • Veículos com retrovisor elétrico • Conteúdo da Embalagem: • 01 Módulo de Retrovisor • 01 Chicotes • Manual e Certificado de Garantia Importante: • Garantia de 273 Dias. • Valor Unitário.', 159.9, 150.31, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/3324773a723947edcec249651684e450', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F16160424046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099447524', 'Pão de Leite Paderrí', 'O Pão de Leite Paderrí é macio, levemente adocicado e perfeito para o café da manhã, lanche da tarde ou para um hot dog! Com a autêntica receita francesa, é uma excelente opção para toda a família. Cada embalagem contém 8 unidades, ideal para sanduíches, torradas ou para consumir puro.', 12.49, 12.49, NULL, 'Food & Beverages > Bakery > Breads', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mj72kvggjcw6c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F23099447524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493953039', 'Fluxo para Solda Aluminex Oxigen ALUMINEX200 - 200g', 'Fluxo para Solda Aluminex Oxigen ALUMINEX200 - 200g O Fluxo para Solda é a solução ideal para garantir uma soldagem eficiente e de alta qualidade em materiais metálicos, especialmente em alumínio. Sua formulação avançada facilita o processo de fusão da solda, promovendo uma excelente aderência e melhorando a resistência das juntas soldadas. Com a aplicação desse fluxo, o risco de oxidação é reduzido, garantindo um acabamento perfeito e sem impurezas durante o processo de soldagem. Este fluxo para solda é essencial para quem busca maior durabilidade nas soldas realizadas, especialmente em ambientes exigentes, onde a integridade das conexões é crucial. A embalagem de 200g é prática e proporciona o rendimento ideal para diversos tipos de trabalhos, otimizando o uso do produto e permitindo um desempenho superior em cada aplicação. É compatível com diferentes tipos de soldagem, sendo um aliado indispensável para profissionais e hobbyistas que buscam qualidade no acabamento das suas soldas.', 85.9, 85.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfga-m97tt0lh9a68e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23493953039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54407380958', 'Mochila de Hidratação Absolute Outfit Nero 2 Litros para Ciclismo Preto/Roxo', 'A Mochila de Hidratação Absolute Outfit Nero 2L é ideal para quem precisa se manter hidratado durante pedais mais longos, treinos ou aventuras. Com design funcional e confortável, permite transportar água e itens essenciais com praticidade e segurança. Benefícios Principais Capacidade de 2 litros ideal para pedais prolongados e atividades intensas. Construção resistente em poliéster e poliuretano, garantindo durabilidade no uso diário. Alças ajustáveis com ventilação que proporcionam mais conforto térmico. Fecho peitoral que melhora a estabilidade durante o pedal. Bolso externo para transporte de pequenos objetos. Apito de emergência integrado para situações de segurança. Detalhes refletivos que aumentam a visibilidade em ambientes com pouca luz. Compatibilidade e Aplicação Indicada para ciclismo MTB, urbano, trilhas, corridas e atividades outdoor em geral. Ideal para ciclistas que buscam praticidade, hidratação e conforto durante o uso. Especificações Técnicas Produto: Mochila de hidratação Marca: Absolute Modelo: Outfit Nero Capacidade: 2 Litros Material: Poliéster e poliuretano Alças: Ajustáveis com ventilação Fechamento: Peitoral com ajuste Extras: Apito de emergência e detalhes refletivos Itens Inclusos 1 Mochila de hidratação 2L', 91.12, 77.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Dry Bags', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mlz9qqi9f091f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F54407380958', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492994216', 'Farol Milha Auxiliar Agile Sonic 2011 2012 2013 2014 2015 2016 + Par Lâmpada Halógena H27', 'Farol de Milha Auxiliar Chevrolet Agile Sonic 2011 2012 2013 2014 2015 2016 + Par Lâmpada Halógena H27 Característica: Produtos novos de ótima qualidade. Especificações técnicas farol de milha: Lente lisa em acrílico; Encaixe de lâmpada h27; Regulagem de foco manual; Suporta lâmpadas até 55 watts. Especificações técnicas lâmpada: Halógena Potência: 27 watts; Encaixe de lâmpada: H27; Tensão de operação: 12V; Uso automotivo de fácil instalação; Fabricado com materiais de alta tecnologia; Vida útil até 3 vezes maior que lâmpadas comuns. Conteúdo da embalagem: 02 Faróis de milha; 02 Lâmpadas H27. Compatível com os modelos: Agile 2011; Agile 2012; Agile 2013; Agile 2014; Agile 2015; Agile 2016; Sonic 2011; Sonic 2012; Sonic 2013; Sonic 2014; Sonic 2015; Sonic 2016. Obs: valor anunciado referente ao KIT. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços! Importante: Não somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 108.7, 97.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lv0ui7kwl9ur2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242764769%2F23492994216', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
