INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49202494829', 'Conjunto Bebê Masculino Menino Infantil Verão Manga Curta Tamanho 1 ao 8 - Roupa para Bebê Masculino L02', 'Conjunto Infantil Masculino – Camiseta ou Regata + Bermuda Estilo, conforto e liberdade para o dia a dia Conjunto infantil composto por: -1 camiseta ou regata (escolha o modelo) -1 bermuda moletinho As peças são ideais para o uso diário, seja na escola, passeios ou momentos de lazer. A malha leve e a bermuda com elástico confortável garantem liberdade para brincar com muito conforto. Detalhes do Produto -Camisetas e regatas em meia malha 100% algodão -Gola redonda com reforço de ombro -Bermudas em moletinho com no mínimo 85% algodão -Elástico na cintura com ajuste confortável -Modelos variados – escolha o conjunto desejado Tabela de Medidas – Camiseta/Regata Tam 1 – Busto 27 cm | Comprimento 36 cm | Tam 2 – Busto 28 cm | Comprimento 38 cm | Tam 3 – Busto 29 cm | Comprimento 40 cm | Tam 4 – Busto 31 cm | Comprimento 46 cm | Tam 6 – Busto 33 cm | Comprimento 48 cm | Tam 8 – Busto 34 cm | Comprimento 49 cm | Tam 10 – Busto 36 cm | Comprimento 53 cm | Bermuda Moletinho Tam 1 – Cintura 20 cm | Comprimento 26 cm Tam 2 – Cintura 21 cm | Comprimento 27 cm Tam 3 – Cintura 21 cm | Comprimento 28 cm Tam 4 – Cintura 22 cm | Comprimento 32 cm Tam 6 – Cintura 23 cm | Comprimento 35 cm Tam 8 – Cintura 24 cm | Comprimento 36 cm Tam 10 – Cintura 25 cm | Comprimento 38 cm Pode haver pequena variação nas medidas devido ao processo de confecção. Vantagens do Produto Peças leves, frescas e respiráveis Conforto ideal para o verão e dias quentes Modelos fáceis de vestir e combinar Ótima durabilidade e acabamento Dica: Adicione mais de um modelo ao carrinho e aproveite o mesmo frete para montar o kit ideal para o seu filho. Perguntas Frequentes 1. Posso escolher o conjunto? Sim. Basta selecionar a estampa e o tamanho desejado no momento da compra. 2. As peças são fresquinhas? Sim. A camiseta ou regata é feita em malha 100% algodão, ideal para dias quentes. 3. A bermuda tem elástico? Sim. Todas as bermudas têm elástico confortável e macio na cintura.', 50.0, 24.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Sets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhs4vqnzkx6p1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F49202494829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
