INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254311412', 'Magnésio Inositol Yoha Melatonina Triptofano Taurina Glicina Relaxamento Sono 208g 26 Porções Camila Loures', 'Magnésio Inositol Yoha Melatonina Triptofano Taurina Glicina Relaxamento Sono 208g 26 Porções Magnésio + Inositol Yoha é um suplemento alimentar em pó desenvolvido para complementar sua rotina noturna com uma combinação inteligente de ativos selecionados. Sua fórmula reúne magnésio, inositol, glicina, taurina, L-triptofano e melatonina em um produto prático, saboroso e fácil de consumir. Disponível nos sabores Limão, Laranja e Maracujá, possui excelente dissolução e uma experiência leve e refrescante para o consumo diário. Destaques da fórmula: Magnésio Inositol Glicina Taurina L-Triptofano Melatonina Características do produto: 26 porções 208g Sem adição de açúcares Não contém glúten Suplemento alimentar em pó Sabores refrescantes Sugestão de consumo: Diluir 1 medida dosadora conforme orientação da embalagem. Pode ser consumido preferencialmente no período noturno. Sabores disponíveis: Limão Laranja Maracujá Conteúdo da embalagem: 01 Magnésio + Inositol Yoha 208g Importante: Este produto não é medicamento. Não exceder a recomendação diária de consumo indicada na embalagem. Mantenha fora do alcance de crianças. Gestantes, lactantes e crianças somente devem consumir este produto sob orientação de médico ou nutricionista.', 89.0, 59.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-820mh-mpxngeo83thd5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1648042360%2F58254311412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56210920609', 'Livro Me deixe para trás - Capa Comum', 'Neste romance militar de tirar o fôlego, dois inimigos mortais se encontram do mesmo lado de uma guerra: Ele, o soldado mais temido do esquadrão, ela, a recruta nova que não se deixa intimidar. Ambos se lançam num jogo perigoso de ódio, vingança e desejo, e as consequências serão arrebatadoras. Este livro faz parte da era dark da Bloom Brasil, a casa de leitores de romances de todos os gêneros. Dark romance é um gênero que retrata o amor através de temas sensíveis, violentos — e por vezes perturbadores. Contém conteúdo sexual explícito e violência gráfica. Recomenda-se cautela ao ler. Leia os descritivos de gatilhos no início do livro antes de começar (os gatilhos estão incluídos no trecho de amostra). Nell Gallows foi a única sobrevivente de um esquadrão de elite das Tropas Ocultas depois de uma missão trágica. Como recompensa, foi jogada em uma divisão ainda mais perigosa e hostil. Antes de embarcar no novo desafio, ela procura uma última noite de prazer e se rende ao charme sombrio de um desconhecido, mas acaba descobrindo que o homem em questão é seu futuro colega de equipe. Cruel e impiedoso, o soldado Bradshaw é conhecido como o inferno na terra e declara guerra à nova recruta. Juntos, eles são duas máquinas mortíferas querendo se destruir, mas uma atração perturbadora faz com que se desejem na mesma intensidade com que se odeiam. Nell está determinada a ir até o fim e confrontar seus demônios, mas Bradshaw usará todas as armas para que ela desista. Motivados pela violência tanto quanto pela luxúria, eles travam um cabo de guerra que vai arrastá-los para os limites da insanidade. Este livro contém: Romance militar dark romance bully romance enemies to lovers personagens com moral duvidosa proximidade forçada cenas quentes', 58.26, 58.26, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-823ot-moigfor2ikum90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F56210920609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
