INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52112516546', 'Capacete Flip-up Four Seasons para Moto com Dupla Viseira, Integral e Aberto, Unissex, Acolchoado e Quente', 'Capacete de motocicleta de rosto aberto, capacete de motocicleta de rosto inteiro com queixo levantado, capacete de motocicleta de todas as estações para homens e mulheres, adequado para ambos os sexos✨ ênfase 🛵 Uso duplo (rosto inteiro e meio rosto) para atender a diferentes necessidades de pilotagem 🛡️ Casca resistente a arranhões em ABS, tinta durável 🎨 Várias cores para escolher 🏍️ Exibição do produto Este capacete de motocicleta com facelift de dois espelhos permite alternar facilmente entre capacetes integrais e meio capacetes, tornando-o perfeito para pilotos que valorizam estilo e segurança. 📏 Especificações do produto 🧩 Material: Carcaça de ABS de alta qualidade 🎨 Cor: Várias cores para escolher 🎯 Estilo: Rosto inteiro/Meio rosto Combinação 🌟 Características: Resistente a arranhões, resistente e durável, leve 🌍 Exibição da cena É uma escolha ideal para deslocamento e viagem de motocicleta. 🧑🤝👩 Adequado para ambos os sexos. 🔍 Detalhes do produto O processo avançado de pintura garante brilho duradouro da cor. O design leve reduz a fadiga e é adequado para pilotos de todas as idades. 📊 Comparação do produto Comparado aos capacetes regulares, este tipo tem uma superfície mais durável e uma variedade de cores da moda. 💡 Precauções de compra 🎨 A cor pode variar ligeiramente devido às configurações de iluminação ou exibição 🙋 Se você tiver alguma dúvida ou precisar de suporte, sinta-se à vontade para entrar em contato com o atendimento ao cliente a qualquer momento', 545.9, 282.45, NULL, 'Motorcycles > Motorcycle Helmets & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824hh-mpq777yhy6tn9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F