INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897083411', 'Dedique-se de coração - Buzz Editora', 'A história da Starbucks não é apenas um registro de crescimento e sucesso. Ela conta também como uma empresa pode ser construída de maneira diferente. Em Dedique-se de coração percebemos que uma empresa pode, sim, funcionar com o coração, nutrir a alma e ainda dar lucros. Neste livro, vemos que é possível, a longo prazo, oferecer valor aos seus acionistas sem sacrificar a crença central de que se deve tratar os funcionários com respeito e dignidade, tanto porque a Starbucks tem uma equipe de líderes que acreditam que isso é o certo quanto porque essa é a melhor forma de se fazer negócios. É Difícil imaginar qualquer café que seja mais agradável do que esta narrativa. — PUBLISHERS WEEKLY — Para empreendedores, gerentes e admiradores da Starbucks: Dedique-se de coração é a história definitiva de como uma empresa de ponta construiu sua reputação no varejo mundialmente, conduzindo tudo com o coração. — BUSINESS TIMES — Ao nos presentear com a história detalhada de como a Starbucks compreendeu a mente de seus clientes, Schultz nos revela um autêntico truísmo norte-americano: Se você for capaz de entender a imaginação de sua clientela, será um vencedor. — USA TODAY —', 50.41, 50.41, NULL, 'Books & Magazines > Books > Business & Investment', 'https://cf.shopee.com.br/file/sg-11134201-7r9ac-ln7cmpccqago27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23897083411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
