INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992569799', 'Food Wars! Vol. 32 - Panini', 'Ao investigarem os diversos incidentes com Batalhas Culinárias que ocorreram por todo o Japão, Erina e Soma descobriram que um homem chamado "Saiba" foi quem instigou a invasão dos Les Cuisiniers Noir e agora, buscam saber sua verdadeira identidade. Enquanto isso, Soma aceita travar uma Batalha Culinária contra Suzuki, um misterioso Instrutor Provisório do Instituto Totsuki?!', 19.0, 19.0, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rblx-ln3hiamlx4vu78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22992569799', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
