INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11747188985', 'Viseira para Corrida Microfibra HUPI Branca', 'Viseira para Corrida Microfibra HUPI Branca A viseira HUPI vem ao mercado para que você possa esfriar a cabeça e preocupar-se com nada além de correr. Isto porque é um item tão leve e confortável que você nem vai sentir na cabeça! Qualidade profissional A fabricação é realizada 100% em poliéster, que auxilia na transpiração, evitando a retenção de suor refletindo na qualidade da sua corrida. A aba curva protege os olhos e a pele da região facial dos raios ultravioletas que podem causar danos permanentes à sua saúde. A faixa de sustentação da viseira é ajustável e veste muito bem, sem qualquer peça de plástico ou metal que possa causar desconforto. Fabricada em poliéster também é projetada para não reter suor, mas promover sustentação sem incômodo. A parte interna da faixa, na região da aba possui um tecido aveludado, evitando que o suor escorra em direção aos olhos. Use a viseira para praticar atividades ao ar livre, importante se proteger do sol. Não esqueça da viseira mesmo em dias nublados, afinal proteção nunca é demais. Modelo de viseira para corrida Dryfit é unissex, pode ser usado como veseira feminina ou masculino! Clique Aqui e conheça todos os modelos de Viseiras para Corrida da HUPI! Ficha técnica * Composição: 100% poliéster; * Peso: 50 gramas; * Aba curva; * Tecido aveludado na parte interna frontal; * Faixa de sustentação moldável; * Tamanho único.', 130.08, 109.9, NULL, 'Fashion Accessories > Hats & Caps', 'https://cf.shopee.com.br/file/6aaadb468034a3319770e893b4785553', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F11747188985', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198308524', 'Kit Máscara de Cílios Volume + Caneta Delineadora Marrom Payot', 'Kit Olhos - Máscara de Cílios Volume + Caneta Delineadora Marrom Payot, contém: 1 - Máscara de Cílios Payot 5 Em 1 Cor: Volume A Máscara para cílios VOLUME 5 em 1 oferece: VOLUME, COMPRIMENTO, DEFINIÇÃO, ALTA PIGMENTAÇÃO E NÃO BORRA. Super volume e definição incrível. Cílios encorpados e com uma cor preta intensa. Não empelota, não esfarela, não borra, secagem rápida e de fácil remoção. Seu aplicador alcança até mesmo os menores fios, proporcionando um efeito que amplia e realça o olhar. Para efeito de cílios postiços é só aplicar várias camadas! Oftalmologicamente testada. Vegano Sem testes em animais Livre de óleo, parabenos, fragrância e álcool. 1- Caneta Delineadora Silver Cor: Marrom A Caneta Delineadora Payot possibilita fácil aplicação, sua ponta fininha e firme é ideal para traços precisos, sejam eles finos ou espessos. Possui alta pigmentação, longa duração e secagem rápida. Não borra. Resistente à água. Produto vegano. Não testado em animais.', 133.9, 113.9, NULL, 'Beauty > Makeup > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd5p-m76rfq94zm365e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F619779318%2F23198308524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
