INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194197505', 'Capacete Moto Bieffe 3 Sport Classic', '3 Sport Lendário e aventureiro Com design marcante, o capacete enduro possui pala alongada e pode ser utilizado em 3 formatos diferentes: 1. Versão enduro com pala e viseira; 2. Versão street sem pala e com viseira; e 3. Versão cross com pala e sem viseira, com óculos de proteção. Aproveite do conforto e versatilidade desse modelo para desbravar novos horizontes. Características do produto: - Casco de alta resistência: produzido com a tecnologia HEAP - High Energy Absorption Polymer; - Filtro à poeira e resíduos: entrada de ar revestida com Expanded Aluminium Alloy; - Pala alongada: proteção eficaz contra a luz solar; - Revestimento interno: materiais impermeáveis e de alta resistência, garantindo durabilidade e baixa retenção de odores; removível e lavável com tratamento hipoalergênico; - Sistema Easy Fit: abertura que proporciona conforto para o uso de óculos, com encaixe perfeito das hastes no interior do capacete; - Viseira com proteção UV: antirrisco em policarbonato de 2 mm; - Cinta jugular: fecho micrométrico; - Peso: 1480g - Certificação: NBR7471', 499.9, 499.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-7rdvh-mbr5vqxywi1id5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F624400687%2F23194197505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
