INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594748410', 'Escapamento Pro Tork Shot 8 Titan 150 Ks 2004 2005 2006 2007 2008 Curva Preta', 'O Shot 8 é mais um super lançamento da Pro Tork, a primeira empresa a ter escapamentos atestados pelo Inmetro no Brasil. Ele faz parte de uma trilogia de produtos, sendo que em breve, outros dois modelos de ponteiras serão apresentados ao mercado. Assim, há a possibilidade de troca de ponteira, mantendo a mesma curva. O item, disponível para diversos tipos de motocicletas nacionais, se destaca pelo ronco esportivo. Desenvolvido em aço, com boquinha em alumínio. Especificações: - Ronco esportivo; - Fabricado em aço; - Boquinha em alumínio; - Marca: Pro Tork. Aplicações: - TITAN 150 KS 2004 - 2008. Instalação: - Pronto para instalar, não necessita adaptações; - Recomendamos que a instalação seja feita em uma oficina especializada; - A loja não se responsabiliza pela má instalação do produto. Observação: - Imagem ilustrativa: Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 247.26, 204.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-81zvw-micybx94xkw77a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22594748410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
