INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204802995', 'Conjunto Infantil Menino Estampa Lateral Elian Bege', 'Combinando estilo e conforto, o Conjunto Elian é composto por camiseta em meia malha e bermuda em moletinho. A camiseta de mangas curtas possui estampa na lateral, remetendo ao verão e natureza. Já a bermuda conta com elástico no cós e recortes laterais com detalhe imitando lapela, trazendo um charme extra à peça. Ideal para passeios e momentos de lazer, invista nesse look cheio de personalidade para os meninos aproveitarem a estação da melhor forma!Detalhes da peça: • Conjunto composto por camiseta e bermuda • Feito em meia malha e moletinho • Possui estampa com tema de verão • Possui elástico no cós • Possui recortes laterais • Ideal para passeios e momentos de lazer', 119.9, 95.92, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mr1tpsgs3090ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58204802995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45950893767', 'Kit 10 Cuecas Zorba Slip Algodão 791', 'DESCRIÇÃO: Kit com 10 Cuecas Zorba Slip Algodão. Modelo clássico, 100% algodão. Possui a tecnologia Go Tagless, sem etiquetas costuradas, não arraha e não irrita a pele. Veste do P ao GG. COMPOSIÇÃO: 100% Algodão. PAÍS DE ORIGEM: Brasil. INSTRUÇÕES DE LAVAGEM: Temperatura máxima de lavagem 30ºC; processo suave; não alvejar; não secar em tambor; secagem em varal por gotejamento a sombra; temperatura máxima da base do ferro a 110ºC sem vapor; não limpar a seco. INDICAÇÃO: Dia a dia. CONTÉM: 01 kit com 10 unidades. TABELA DE MEDIDAS: P – 38 ao 40 - Cintura entre 76 e 80 cm M – 42 ao 44 - Cintura entre 84 e 88 cm G – 46 ao 48 - Cintura entre 92 e 96 cm GG – 50 ao 52 - Cintura entre 100 e 104 cm XG – 54 ao 56 - Cintura entre 108 e 112 cm XGG – 58 ao 60 - Cintura entre 116 e 120 cm Caso sua medida esteja no intervalo das medidas entre um tamanho e outro, considerar o tamanho maior.', 195.9, 195.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-821el-mgpnnvs19iq68c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F733918049%2F45950893767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
