INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297674108', 'Silicone Acetico Alta Temperatura Blister 50gr Preto Tekbond 22024001202', 'Silicone Acético para Alta Temperatura 50gr Preto TEKBOND O SILICONE ACÉTICO PRETO ALTA TEMPERATURA é um adesivo selante tixotrópico monocomponente, baixo módulo, anti-fungo e de cura acética. Sua cura ocorre em temperatura ambiente e na exposição à umidade do ar. Possui excelente resistência a óleo de motor e óleos lubrificantes, pode ser aplicado em tampa de válvulas, caixas de câmbio, caixas de engrenagens, tampa de motores, etc. Ideal para ser utilizado como um substituto de juntas de retentores, de papel, cortiça e feltro. Este produto não deve ser usado em vidros laminados, metal corrosível, espelhos, superfícies pintadas eou porosas, superfícies alcalinas, aquário, acrílicos, concreto, cimento, tijolo, pedra calcária, zinco, placa de aço galvanizado. Não recomendado para plásticos à base de polietileno, polipropileno e policarbonato. Não indicado para fachadas de vidro e qualquer adesão estrutural que necessite resistência, contato de alimentos, imersão contínua em meios líquidos e em espaços totalmente fechados. CódigoModelo:22024001202 Marca: TEKBOND Especificações Técnicas Aparência (visual): Pasta preta com odor característico (ácido acético) Densidade a 25 ºC (gmL): 0,93 à 1,15 Tempo de formação de película: 5 à 15 minutos Temperatura ideal de aplicação: 5 à 35C Temperatura de trabalho: - 54 à 232C Alongamento à ruptura: 100 % Dureza Shore A: 18 Cura gradativa a 23C e 55% U.R. após 24 horas: 3 mm Imagens meramente ilustrativas. Todas as informações divulgadas são de responsabilidade do fabricantefornecedor.', 17.06, 17.06, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rdy0-lycd87wvc1iv02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F23297674108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093587008', 'Vestido Feminino Em Algodão Marialícia Verde', 'O Vestido Feminino em Algodão Marialícia é confeccionado em meia malha de algodão devorê. Ideal para dias ensolarados, garantindo frescor e estilo. Com alças reguláveis, ele se adapta perfeitamente ao corpo, proporcionando conforto durante todo o uso. Seu tecido leve e fluido permite liberdade de movimentos, tornando a peça perfeita para passeios ao ar livre, encontros casuais ou até mesmo um dia na praia. A estampa delicada em toda a peça traz um toque moderno e discreto, enquanto o detalhe no busto valoriza o decote. Combine com sandálias ou rasteirinhas para um visual descontraído e atual. Essa peça é indispensável no guarda-roupa de quem busca praticidade com elegância.', 169.9, 169.9, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-8259s-mr1svgubtnnw14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23093587008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
