INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18903961310', 'COLECAO ENCONTRE - ENCONTRE SUA CALMA', 'Além do sucesso da coleção sentimentos e emoções do nosso autor James Missé, a Pé da Letra editora mostra nesse grande lançamento feito por psicólogos infantis atividades que irão ajudar nesse processo. Você, às vezes, se sente preocupado ou ansioso? Este livro está repleto de atividades para ajudá-lo a compreender e administrar essas emoções. Você pode fazê-las sozinho, com amigos ou familiares. Escrito pela psicóloga infantil Dra. Katie O’Connell, Ph.D. Contém técnicas simples - incluindo as de pensamento - que podem ser usadas para combater a ansiedade.', 29.6, 29.6, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/c347a11dd5be3dd7f4599504dd30e80f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F18903961310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
