INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18915355391', 'Fita de Cetim Carretel 4mm nº00 - 100m Cor 219 Preto - 1un', '🎀 Fita de Cetim Carretel Progresso 4mm nº00 100m ideal para decorar e dar acabamento profissional às suas embalagens! O Fita de Cetim Carretel Progresso 4mm nº00 100m combina funcionalidade e qualidade, sendo uma excelente escolha para quem busca praticidade e um ótimo resultado no uso diário. Descrição Técnica: Produto: Fita de Cetim Carretel Progresso 4mm nº00 Modelo: 100m Quantidade: 01 unidade Marca: Rizzo Embalagens Dúvidas Frequentes: Quanto tempo leva o envio? ⏰ Todos os pedidos com etiqueta de envio liberado pela shopee até as 18hs são coletados no próximo dia útil pela transportadora Shopee Express. Qual o prazo de entrega? 🛵 A loja não tem acesso a parte logística da shopee. A Shopee não informa para a loja prazo de entrega. Ao clicar em comprar na opção envios é apresentado o prazo de entrega. O produto é novo? 😀 Sim. Só trabalhamos com produto novos e dentro da embalagem original do fabricante. Como faço para comprar mais de um item da loja? 🛍 No app ao lado do botão comprar tem o ícone de um carrinho de supermercado, clicando nele o produto será acrescentado no carrinho que fica na parte superior do app. Após acrescentar todos os produtos que gostaria é só clicar no carrinho e selecionar todos os itens e clicar em continuar. Comemore com Alegria: 🥰😀 Na Rizzo Distribuidora, a tradição e o encanto do nosso espaço físico no coração da 25 de março, em São Paulo, são cuidadosamente embalados para chegar até você. Permita-nos levar a magia de uma das lojas mais tradicionais da região diretamente para o conforto da sua casa ou empresa.', 30.9, 30.9, NULL, 'Stationery > Gift & Wrapping > Ribbons', 'https://cf.shopee.com.br/file/7bfaa65bfa253e5d6660101918b56e2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400124163%2F18915355391', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
