INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397135748', 'Alpargatas Havaianas Mule II Unissex', 'O sapato tipo mule, aberto na parte de trás, é charmoso, confortável e muito prático. Daqueles que é só calçar e pronto: não tem complicação. A versão da Havaianas tem sola de borracha, como as sandálias, e cabedal em algodão reciclado e certificado pelo selo de sustentabilidade BCI (Better Cotton Initiative). Vai deixar seus looks muito mais charmosos.', 144.99, 144.99, NULL, 'Women Shoes > Flats > Slip Ons, Mary Janes & Mules', 'https://cf.shopee.com.br/file/sg-11134201-7rdy5-mbpf9axcrcpoee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1090996394%2F23397135748', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
