INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8630859861', 'Sutiã Love Secret Amamentação 92300 Taça B', 'Características: Sutiã de amamentação costa estilo regata anatômica. Sustentação e conforto com base reforçada. Clik frontal para melhor amamentação ideal para seios fartos. Base reforçada dupla. Proteção antibacteriana design anatômico acompanha o formato dos seios. Não marca sobre a roupa protege, corrige e disfarça os mamilos grossos. Totalmente antialérgico evitando proliferação de bactérias. Protege e disfarça em eventual vazamento de leite. Aplique de florzinha frontal. Outros Detalhes: Taça B. Acompanha protetor de mamilos em puro algodão. Modo de lavagem: Lavar à mão com sabão neutro. Enxague normal. Não usar alvejante à base de cloro. Secar à sombra. Não passar a ferro. Não usar máquina de secar. Não limpar a seco. Composição: Corpo: 95% Algodão e 5% Elastano. Forro do bojo : 100% Algodão. Enchimento do Protetor: 100% Poliuretano. Revestimento do Protetor: 100% Algodão.', 103.9, 103.9, NULL, 'Women Clothes > Maternity Wear > Nursing Bras', 'https://cf.shopee.com.br/file/0092db82223338e21a26826dd4df71ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F8630859861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
