INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2972086378', 'Corda De Pular Cabo Aço Speed Rope 2 Rolamentos Cross', 'A corda de pular Speed Rope 2 Rolamentos, potencializa seu treino ao máximo. Ela possui dois rolamentos, um simples e um rolamento esfera, ideal para ser usada nos treinos de Cross training, Funcional, MMA e diversas outras modalidades esportivas. Especificações da Corda de Pular Speed Rope: Cabo com 3 metros de comprimento totalmente ajustável Material do Cabo: Aço revestido por polímero; Material da Manopla: PVC com dois rolamentos; Rolamentos: um rolamento simples e um rolamento esfera; Cor da corda: Preta; Peso do conjunto: 100 gramas; Além disso, a corda para treino Speed Rope possui um cabo de 3 metros de aço galvanizado e revestido por um polímero especial de plástico, que evita a disjunção dos filamentos de aço, se tornando muito mais resistente. Produto com garantia de 3 meses contra defeitos de fabricação Atenção: Não recomendado o uso de corda com cabo revestido sobre superfícies ásperas ou abrasivas como cimento, asfalto, concreto, pisos de piscina e outros, para evitar o desgaste prematuro.', 39.9, 39.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/198df743e472254d7ee9aadad9487f9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F407831463%2F2972086378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
