INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898560997', 'Chinelo Coca Cola Bahai Branco - Feminino', 'Arrase aonde for com esse chinelo! Chinelo Coca Cola Bahai Branco - FemininoParte superior do formulário Ficha Técnica: Marca: Coca-Cola Chinelo de dedo, exibe todo o pé Material: Borracha Palmilha: Texturizada por desenhos de garrafinhas de Coca-Cola, estampa floral e nome da marca estampado Solado: Antiderrapante Gênero: Feminino Cor: Branco com estampa colorida Indicação: Dia a Dia Estampa: Floral Tiras: Tiras finas texturizadas com pin Coca Cola metálico em branco Descubra o Chinelo Coca-Cola Bahai Branco, perfeito para quem valoriza estilo e praticidade no dia a dia. Porque investir: Com um design único que combina a elegância do branco com uma charmosa estampa floral, este chinelo proporciona conforto incomparável graças à sua palmilha texturizada e solado antiderrapante. Seja para relaxar ou passear, ele é a escolha ideal para momentos de lazer com autenticidade. Conteúdo da Embalagem: 1 Par de Chinelo Coca Cola Bahai Branco - FemininoParte superior do formulário', 89.99, 57.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rato-maiwu9ay4h3k09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F22898560997', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
