INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206304639', 'Perfurador de Solo a Gasolina 52cc 2,5HP com Brocas 80x20cm + 80x30cm + 4x Extensor 1m FAK520PS Carbon Fak', 'PERFURADOR DE SOLO GASOLINA 52CC 2,5HP FAK520PS CARBON FAK ITENS INCLUSOS: - Motor 52cc 2,5HP - Broca 80x20cm - Broca 80x30cm - 4x Extensor 1m - Manual de Instruções - Jogo de Chaves - Dosador de Combustível O aliado ideal para quem trabalha no campo! Com motor potente de 52 cilindradas e 2,5HP, o Perfurador de Solo Carbon Fak FAK520PS é a ferramenta perfeita para agilizar tarefas na propriedade rural. Projetado para atender às exigências do agronegócio, este equipamento oferece alta eficiência na perfuração de diversos tipos de solo, sendo ideal para plantio de mudas, cercamento de áreas, reflorestamento, instalação de mourões e demais atividades agrícolas. CARACTERÍSTICAS DO PRODUTO Estrutura e brocas de alta resistência; Fácil manuseio e manutenção; Produto leve e compacto; Proporciona perfurações na vertical / horizontal; Maior autonomia. FICHA TÉCNICA Motor: gasolina 2 Tempos Óleo 2T: 25:1 ---- 25 Litros de gasolina: 1 Litro de óleo 2T; Potência: 2,50 HP (1,85kw) - 52cc; Rotação: Máxima 11.000 RPM - Na Lenta 3.000 RPM; Arranque: Manual com mola retrátil; Autonomia: Aproximadamente 1 hora; Tanque: 1000 ml; Redução: Taxa de Redução 29:1 Engrenagens: Em Aço Temperado; *Garantia de 6 meses (3 meses de fábrica + 3 meses de loja)* **Assistência técnica e peças de reposição diretamente com a CARBON FAK em todo território nacional', 1250.9, 1071.97, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820l8-mlhspuzqct1j80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389803646%2F58206304639', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47462412952', 'HIDRATANTE DESODORANTE BARBARIUS MASCULINO 200G - PRIMACIAL PERFUME AMADEIRADO AROMÁTICO', 'Hidratante Desodorante Corporal Barbarius 200g O Hidratante Desodorante Corporal Barbarius foi desenvolvido para quem busca unir cuidado diário, perfumação e sensação de pele bem cuidada em um só produto. Com textura agradável e fragrância marcante, ele ajuda a manter a pele macia, confortável e levemente perfumada ao longo do dia. Sua fragrância masculina combina frescor cítrico, nuances aromáticas e um fundo amadeirado quente e envolvente, criando uma assinatura sofisticada, moderna e versátil para diferentes momentos da rotina. Pirâmide Olfativa: Notas de Topo: Bergamota, Mandarina e Sálvia Notas de Coração: Lavanda, Folhas de Violeta e Cedro Notas de Base: Vetiver, Sândalo, Âmbar e Musk Benefícios do produto: -Hidratante desodorante corporal com fragrância -Ajuda a deixar a pele macia e confortável -Proporciona sensação de cuidado diário -Deixa a pele levemente perfumada -Fragrância masculina marcante e versátil -Ideal para uso diário Modo de uso: Aplique o hidratante desodorante corporal sobre a pele limpa e seca, massageando suavemente até completa absorção.', 89.9, 54.9, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820m2-mpl9a6vct3pd7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F47462412952', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599307112', 'PERFUME MASCULINO LE NOIRE HOMME EXCÈS - PRIMACIAL PERFUME AMADEIRADO', 'Fragrância Le Noire Excès Homme Masculino Perfume Masculino Noturno | Misterioso, Sofisticado e Marcante Uma fragrância criada para o homem moderno que vive a noite com intensidade. O Le Noire Excès Homme combina frescor vibrante com profundidade envolvente, resultando em um aroma elegante, misterioso e irresistível. Ideal para quem quer se destacar com estilo e deixar uma marca inesquecível. Inspirado pela energia das noites urbanas, esse perfume entrega uma abertura fresca e energética, seguida por um coração intenso e moderno. No fundo, notas quentes e sofisticadas criam um rastro envolvente, perfeito para homens audaciosos, confiantes e com presença marcante. Pirâmide Olfativa: Topo: Lavanda e Limão Amalfi Coração: Nargamota (óleo de cipriol) e Notas Oceânicas Fundo: Patchouli e Âmbar Quando Usar: 🌙 Noite: Excelente 🍂 Dias amenos e frios: Perfeito 📦 Detalhes do Produto: ✔ Perfume masculino ✔ Fixação longa, até 12 horas ✔ Projeção moderada ✔ Família olfativa Amadeirado Aromático ✔ Ideal para quem gosta de fragrâncias sofisticadas e noturnas 💡 Dica de uso: Aplique nos pontos de pulsação, como pescoço e pulsos, para maior projeção e fixação. Ideal para uso noturno, onde sua fragrância se destaca ainda mais e cria uma presença marcante.', 179.0, 164.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2s9q3xy6rpx0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F18599307112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
